export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  category: string;
  image: string;
  rating: number;
  reviews: number;
  isFeatured: boolean;
  createdAt: number;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface CSContact {
  id: string;
  name: string;
  phoneNumber: string; // international format like 62812345678
  isActive: boolean;
}

export interface UserInfo {
  name: string;
  address: string;
  phone: string;
}

import { Product, CSContact } from '../types';

const PRODUCTS_KEY = 'lumina_products';
const CS_KEY = 'lumina_cs_contacts';

// Initial Mock Data
const INITIAL_PRODUCTS: Product[] = [
  {
    id: '1',
    name: 'Handcrafted Leather Tote',
    description: 'Quality leather tote bag made with vegetable tanned leather. Perfect for daily use.',
    price: 1200000,
    category: 'Fashion',
    image: 'https://images.unsplash.com/photo-1544816153-17684070a7b1?auto=format&fit=crop&q=80&w=800',
    rating: 4.9,
    reviews: 120,
    isFeatured: true,
    createdAt: Date.now()
  },
  {
    id: '2',
    name: 'Minimalist Desk Lamp',
    description: 'Sleek black aluminum lamp with adjustable brightness levels and color temperature.',
    price: 850000,
    category: 'Home Decor',
    image: 'https://images.unsplash.com/photo-1507473885765-e6ed057f782c?auto=format&fit=crop&q=80&w=800',
    rating: 4.8,
    reviews: 85,
    isFeatured: true,
    createdAt: Date.now()
  }
];

const INITIAL_CS: CSContact[] = [
  { id: '1', name: 'Admin Utama', phoneNumber: '6281234567890', isActive: true }
];

export const dbService = {
  // PRODUCTS
  async getProducts(): Promise<Product[]> {
    const data = localStorage.getItem(PRODUCTS_KEY);
    if (!data) {
      localStorage.setItem(PRODUCTS_KEY, JSON.stringify(INITIAL_PRODUCTS));
      return INITIAL_PRODUCTS;
    }
    return JSON.parse(data);
  },

  async saveProduct(product: Product): Promise<void> {
    const products = await this.getProducts();
    const index = products.findIndex(p => p.id === product.id);
    if (index >= 0) {
      products[index] = product;
    } else {
      products.push(product);
    }
    localStorage.setItem(PRODUCTS_KEY, JSON.stringify(products));
  },

  async deleteProduct(id: string): Promise<void> {
    const products = await this.getProducts();
    const filtered = products.filter(p => p.id !== id);
    localStorage.setItem(PRODUCTS_KEY, JSON.stringify(filtered));
  },

  // CS CONTACTS
  async getCSContacts(): Promise<CSContact[]> {
    const data = localStorage.getItem(CS_KEY);
    if (!data) {
      localStorage.setItem(CS_KEY, JSON.stringify(INITIAL_CS));
      return INITIAL_CS;
    }
    return JSON.parse(data);
  },

  async saveCSContact(contact: CSContact): Promise<void> {
    const contacts = await this.getCSContacts();
    const index = contacts.findIndex(c => c.id === contact.id);
    if (index >= 0) {
      contacts[index] = contact;
    } else {
      contacts.push(contact);
    }
    localStorage.setItem(CS_KEY, JSON.stringify(contacts));
  },

  async deleteCSContact(id: string): Promise<void> {
    const contacts = await this.getCSContacts();
    const filtered = contacts.filter(c => c.id !== id);
    localStorage.setItem(CS_KEY, JSON.stringify(filtered));
  }
};

import React, { useState, useEffect, useCallback, createContext, useContext } from 'react';
import { HashRouter as Router, Routes, Route, Link, useNavigate, useParams } from 'react-router-dom';
import { Product, CartItem, CSContact, UserInfo } from './types';
import { dbService } from './services/dbService';
import Header from './components/Header';
import Hero from './components/Hero';
import Footer from './components/Footer';
import CartSidebar from './components/CartSidebar';
import ProductCard from './components/ProductCard';
import AdminDashboard from './pages/Admin/AdminDashboard';
import AdminLogin from './pages/Admin/AdminLogin';

// Context for global state
interface StoreContextType {
  products: Product[];
  cart: CartItem[];
  addToCart: (product: Product) => void;
  removeFromCart: (productId: string) => void;
  updateCartQuantity: (productId: string, quantity: number) => void;
  clearCart: () => void;
  csContacts: CSContact[];
  refreshData: () => void;
  isCartOpen: boolean;
  setIsCartOpen: (open: boolean) => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error('useStore must be used within StoreProvider');
  return context;
};

// --- PAGES ---

const HomePage: React.FC = () => {
  const { products } = useStore();
  const featured = products.filter(p => p.isFeatured);

  return (
    <div className="flex flex-col flex-1">
      <Hero />

      <section id="products" className="px-4 md:px-10 lg:px-40 py-20 flex justify-center">
        <div className="max-w-[1200px] w-full">
          <div className="flex items-end justify-between px-4 pb-8 border-b border-[#dbe6db] dark:border-[#2a3a2a]">
            <div>
              <h2 className="text-[#111811] dark:text-white text-3xl font-bold leading-tight">Featured Selection</h2>
              <p className="text-[#618961] mt-2">Curated quality for your lifestyle</p>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8 py-10">
            {featured.length > 0 ? (
              featured.map(product => <ProductCard key={product.id} product={product} />)
            ) : (
              <p className="col-span-full text-center text-gray-500 py-20">No featured products available.</p>
            )}
          </div>
        </div>
      </section>

      {/* Why Choose Section */}
      <section className="px-4 md:px-10 lg:px-40 py-20 bg-background-light dark:bg-background-dark/50">
        <div className="max-w-[1200px] mx-auto text-center">
          <h2 className="text-4xl font-black mb-6">Why Choose Lumina</h2>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
            {[
              { icon: 'local_shipping', title: 'Fast Delivery', desc: 'Ships within 24 hours' },
              { icon: 'verified_user', title: 'Quality Assured', desc: 'Handpicked premium items' },
              { icon: 'whatsapp', title: 'Easy Order', desc: 'Checkout via WhatsApp' },
              { icon: 'support_agent', title: '24/7 Support', desc: 'Ready to help you anytime' }
            ].map((item, i) => (
              <div key={i} className="p-8 bg-white dark:bg-[#1a2e1a] rounded-xl shadow-sm border border-gray-100 dark:border-gray-800">
                <span className="material-symbols-outlined text-primary text-4xl mb-4">{item.icon}</span>
                <h3 className="text-xl font-bold mb-2">{item.title}</h3>
                <p className="text-gray-500 text-sm">{item.desc}</p>
              </div>
            ))}
          </div>
