          <img src={product.image} alt={product.name} className="w-full h-full object-cover" />
        </div>
        <div className="flex flex-col justify-center">
          <span className="text-primary font-bold text-sm tracking-widest uppercase mb-2">{product.category}</span>
          <h1 className="text-4xl font-black mb-4">{product.name}</h1>
          <div className="flex items-center gap-2 mb-6 text-yellow-500">
            <span className="material-symbols-outlined">star</span>
            <span className="text-gray-600 dark:text-gray-300 font-medium">{product.rating} ({product.reviews} reviews)</span>
          </div>
          <p className="text-3xl font-bold text-primary mb-8">Rp {product.price.toLocaleString('id-ID')}</p>
          <p className="text-gray-600 dark:text-gray-400 leading-relaxed mb-8">{product.description}</p>
          <button 
            onClick={() => addToCart(product)}
            className="flex items-center justify-center gap-3 bg-primary text-[#111811] h-14 rounded-xl text-lg font-bold hover:brightness-110 transition-all shadow-lg shadow-primary/20"
          >
            <span className="material-symbols-outlined">add_shopping_cart</span>
            Add to Shopping Cart
