import React, { useState } from 'react';
import { useStore } from '../App';
import { UserInfo } from '../types';

interface CartSidebarProps {
  isOpen: boolean;
  onClose: () => void;
}

const CartSidebar: React.FC<CartSidebarProps> = ({ isOpen, onClose }) => {
  const { cart, removeFromCart, updateCartQuantity, csContacts } = useStore();
  const [showCheckout, setShowCheckout] = useState(false);
  const [userInfo, setUserInfo] = useState<UserInfo>({ name: '', address: '', phone: '' });

  const total = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);

  const handleCheckout = () => {
    if (cart.length === 0) return;
    setShowCheckout(true);
  };

  const sendWhatsAppOrder = () => {
    if (!userInfo.name || !userInfo.address || !userInfo.phone) {
      alert('Mohon lengkapi data diri Anda.');
      return;
    }

    const activeCS = csContacts.filter(c => c.isActive);
    if (activeCS.length === 0) {
      alert('Maaf, saat ini CS kami sedang tidak aktif.');
      return;
    }

    // Pick a random CS for load balancing
    const cs = activeCS[Math.floor(Math.random() * activeCS.length)];

    let message = `*HALO LUMINA GOODS - PESANAN BARU*\n\n`;
    message += `*Data Pembeli:*\n`;
    message += `Nama: ${userInfo.name}\n`;
    message += `No. Telp: ${userInfo.phone}\n`;
    message += `Alamat: ${userInfo.address}\n\n`;
    message += `*Daftar Pesanan:*\n`;

    cart.forEach((item, index) => {
      message += `${index + 1}. ${item.name} (${item.quantity}x) - Rp ${(item.price * item.quantity).toLocaleString('id-ID')}\n`;
    });

    message += `\n*TOTAL PESANAN: Rp ${total.toLocaleString('id-ID')}*`;
    message += `\n\n_Mohon bantu konfirmasi pesanan saya ya Kak. Terima kasih!_`;

    const encodedMessage = encodeURIComponent(message);
    window.open(`https://wa.me/${cs.phoneNumber}?text=${encodedMessage}`, '_blank');
  };

  return (
    <>
      {/* Backdrop */}
      <div 
        className={`fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] transition-opacity duration-300 ${isOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
        onClick={onClose}
      />

      {/* Sidebar */}
      <div className={`fixed top-0 right-0 h-full w-full max-w-md bg-white dark:bg-background-dark shadow-2xl z-[101] transform transition-transform duration-300 flex flex-col ${isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="flex items-center justify-between p-6 border-b border-gray-100 dark:border-gray-800">
          <h2 className="text-xl font-black">{showCheckout ? 'Checkout Info' : 'Shopping Cart'}</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg">
            <span className="material-symbols-outlined">close</span>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          {!showCheckout ? (
            cart.length > 0 ? (
              <div className="flex flex-col gap-6">
                {cart.map(item => (
                  <div key={item.id} className="flex gap-4">
                    <img src={item.image} alt={item.name} className="size-20 rounded-xl object-cover" />
                    <div className="flex-1">
                      <h4 className="font-bold line-clamp-1">{item.name}</h4>
                      <p className="text-primary font-bold text-sm">Rp {item.price.toLocaleString('id-ID')}</p>
                      <div className="flex items-center gap-4 mt-2">
                        <div className="flex items-center border border-gray-200 dark:border-gray-800 rounded-lg overflow-hidden">
                          <button 
                            onClick={() => updateCartQuantity(item.id, item.quantity - 1)}
                            className="px-2 py-1 hover:bg-gray-100 dark:hover:bg-gray-800"
                          >-</button>
                          <span className="px-3 py-1 text-sm font-bold border-x border-gray-100 dark:border-gray-800">{item.quantity}</span>
                          <button 
                            onClick={() => updateCartQuantity(item.id, item.quantity + 1)}
                            className="px-2 py-1 hover:bg-gray-100 dark:hover:bg-gray-800"
                          >+</button>
                        </div>
                        <button 
                          onClick={() => removeFromCart(item.id)}
                          className="text-red-500 text-xs font-bold hover:underline"
                        >Remove</button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-400 gap-4">
                <span className="material-symbols-outlined text-6xl">shopping_cart_off</span>
                <p>Your cart is empty.</p>
              </div>
            )
          ) : (
            <div className="flex flex-col gap-6 animate-in fade-in slide-in-from-right-4 duration-300">
              <div className="flex flex-col gap-2">
                <label className="text-sm font-bold">Full Name</label>
                <input 
                  type="text" 
                  className="h-12 border rounded-xl px-4 dark:bg-[#1a2e1a] border-gray-200 dark:border-gray-800"
                  value={userInfo.name}
                  onChange={e => setUserInfo({ ...userInfo, name: e.target.value })}
                  placeholder="e.g. John Doe"
                />
              </div>
              <div className="flex flex-col gap-2">
                <label className="text-sm font-bold">Phone Number</label>
                <input 
                  type="tel" 
                  className="h-12 border rounded-xl px-4 dark:bg-[#1a2e1a] border-gray-200 dark:border-gray-800"
                  value={userInfo.phone}
                  onChange={e => setUserInfo({ ...userInfo, phone: e.target.value })}
                  placeholder="e.g. 0812345678"
                />
              </div>
              <div className="flex flex-col gap-2">
                <label className="text-sm font-bold">Full Address</label>
                <textarea 
                  className="h-24 border rounded-xl p-4 dark:bg-[#1a2e1a] border-gray-200 dark:border-gray-800 resize-none"
                  value={userInfo.address}
                  onChange={e => setUserInfo({ ...userInfo, address: e.target.value })}
                  placeholder="Street name, house number, district, city..."
                />
              </div>
              <button 
                onClick={() => setShowCheckout(false)}
                className="text-gray-400 text-sm font-bold hover:underline"
              >Back to Cart</button>
            </div>
          )}
        </div>

        <div className="p-6 border-t border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-black/20">
          <div className="flex items-center justify-between mb-6">
            <span className="text-gray-500 font-bold uppercase tracking-widest text-xs">Total Amount</span>
            <span className="text-2xl font-black text-primary">Rp {total.toLocaleString('id-ID')}</span>
          </div>

          {showCheckout ? (
            <button 
              onClick={sendWhatsAppOrder}
              disabled={!userInfo.name || !userInfo.address || !userInfo.phone}
              className="w-full h-14 bg-primary text-[#111811] rounded-xl font-bold flex items-center justify-center gap-3 hover:brightness-110 disabled:opacity-50 transition-all shadow-xl shadow-primary/20"
            >
              <span className="material-symbols-outlined">send</span>
              Order via WhatsApp
            </button>
          ) : (
            <button 
              onClick={handleCheckout}
              disabled={cart.length === 0}
              className="w-full h-14 bg-primary text-[#111811] rounded-xl font-bold flex items-center justify-center gap-3 hover:brightness-110 disabled:opacity-50 transition-all shadow-xl shadow-primary/20"
            >
              Checkout Now
            </button>
          )}
        </div>
      </div>
    </>
  );
};

export default CartSidebar;

