import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dbService } from '../../services/dbService';
import { Product, CSContact } from '../../types';
import { useStore } from '../../App';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cs'>('products');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null);
  const [editingCS, setEditingCS] = useState<Partial<CSContact> | null>(null);
  const navigate = useNavigate();
  const { refreshData, products, csContacts } = useStore();

  useEffect(() => {
    const isAuth = localStorage.getItem('lumina_admin_auth');
    if (!isAuth) navigate('/admin/login');
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('lumina_admin_auth');
    navigate('/admin/login');
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;

    const product: Product = {
      id: editingProduct.id || Date.now().toString(),
      name: editingProduct.name || '',
      description: editingProduct.description || '',
      price: Number(editingProduct.price) || 0,
      category: editingProduct.category || 'General',
      image: editingProduct.image || 'https://picsum.photos/400',
      rating: editingProduct.rating || 5.0,
      reviews: editingProduct.reviews || 0,
      isFeatured: !!editingProduct.isFeatured,
      createdAt: editingProduct.createdAt || Date.now()
    };

    await dbService.saveProduct(product);
    refreshData();
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  const handleDeleteProduct = async (id: string) => {
    if (confirm('Delete this product?')) {
      await dbService.deleteProduct(id);
      refreshData();
    }
  };

  const handleSaveCS = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCS) return;

    const cs: CSContact = {
      id: editingCS.id || Date.now().toString(),
      name: editingCS.name || '',
      phoneNumber: editingCS.phoneNumber || '',
      isActive: editingCS.isActive !== undefined ? editingCS.isActive : true
    };

    await dbService.saveCSContact(cs);
    refreshData();
    setIsModalOpen(false);
    setEditingCS(null);
  };

  return (
    <div className="px-4 md:px-10 lg:px-40 py-10">
      <div className="max-w-[1200px] mx-auto">
        <div className="flex flex-col md:flex-row items-center justify-between mb-10 gap-6">
          <div>
            <h1 className="text-4xl font-black">Management Dashboard</h1>
            <p className="text-gray-400 mt-1 font-medium">LuminaGoods Administration</p>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={() => { setEditingProduct({}); setIsModalOpen(true); setActiveTab('products'); }}
              className="h-12 px-6 bg-primary text-[#111811] rounded-xl font-bold flex items-center gap-2 hover:scale-105 transition-all"
            >
              <span className="material-symbols-outlined">add</span>
              New Product
            </button>
            <button 
              onClick={handleLogout}
              className="h-12 px-6 border border-gray-200 dark:border-gray-800 rounded-xl font-bold hover:bg-red-50 hover:text-red-500 transition-all"
            >
              Logout
            </button>
          </div>
        </div>

        <div className="flex border-b border-gray-200 dark:border-gray-800 mb-8">
          <button 
            className={`px-8 py-4 font-bold text-sm uppercase tracking-widest ${activeTab === 'products' ? 'border-b-2 border-primary text-primary' : 'text-gray-400'}`}
            onClick={() => setActiveTab('products')}
          >
            Product List
          </button>
          <button 
            className={`px-8 py-4 font-bold text-sm uppercase tracking-widest ${activeTab === 'cs' ? 'border-b-2 border-primary text-primary' : 'text-gray-400'}`}
            onClick={() => setActiveTab('cs')}
          >
            CS Configuration
          </button>
        </div>

        {activeTab === 'products' ? (
          <div className="grid grid-cols-1 gap-4">
            {products.map(p => (
              <div key={p.id} className="bg-white dark:bg-[#1a2e1a] p-4 rounded-2xl flex flex-col md:flex-row items-center gap-6 border border-gray-100 dark:border-gray-800 shadow-sm">
                <img src={p.image} className="size-24 rounded-xl object-cover" />
                <div className="flex-1 text-center md:text-left">
                  <h4 className="text-lg font-bold">{p.name}</h4>
                  <p className="text-sm text-gray-400">{p.category}</p>
                  <p className="text-primary font-bold">Rp {p.price.toLocaleString('id-ID')}</p>
                </div>
                <div className="flex gap-2">
                  <button 
                    onClick={() => { setEditingProduct(p); setIsModalOpen(true); }}
                    className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-blue-50 hover:text-blue-500 transition-all"
                  >
                    <span className="material-symbols-outlined">edit</span>
                  </button>
                  <button 
                    onClick={() => handleDeleteProduct(p.id)}
                    className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-red-50 hover:text-red-500 transition-all"
                  >
                    <span className="material-symbols-outlined">delete</span>
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-4">
            <button 
              onClick={() => { setEditingCS({}); setIsModalOpen(true); }}
              className="bg-dashed border-2 border-dashed border-gray-200 dark:border-gray-800 p-8 rounded-2xl text-center text-gray-400 hover:border-primary hover:text-primary transition-all mb-4"
            >
              + Add New Customer Service
            </button>
            {csContacts.map(c => (
              <div key={c.id} className="bg-white dark:bg-[#1a2e1a] p-6 rounded-2xl flex items-center justify-between border border-gray-100 dark:border-gray-800">
                <div>
                  <h4 className="text-lg font-bold">{c.name}</h4>
                  <p className="text-gray-400">+{c.phoneNumber}</p>
                  <span className={`inline-block mt-2 px-3 py-1 rounded-full text-[10px] font-black uppercase ${c.isActive ? 'bg-primary/20 text-primary' : 'bg-gray-100 text-gray-400'}`}>
                    {c.isActive ? 'Active' : 'Inactive'}
                  </span>
                </div>
                <div className="flex gap-2">
                  <button 
                    onClick={() => { setEditingCS(c); setIsModalOpen(true); }}
                    className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-blue-50 hover:text-blue-500"
                  >
                    <span className="material-symbols-outlined">edit</span>
                  </button>
                  <button 
                    onClick={async () => { await dbService.deleteCSContact(c.id); refreshData(); }}
                    className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-red-50 hover:text-red-500"
                  >
                    <span className="material-symbols-outlined">delete</span>
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Modal for Forms */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsModalOpen(false)}></div>
