            {activeTab === 'products' ? (
              <form onSubmit={handleSaveProduct} className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="flex flex-col gap-2">
                  <label className="text-sm font-bold">Product Name</label>
                  <input required className="h-12 border rounded-xl px-4 dark:bg-[#1a2e1a]" value={editingProduct?.name || ''} onChange={e => setEditingProduct({ ...editingProduct, name: e.target.value })} />
