        </div>

        {activeTab === 'products' ? (
          <div className="grid grid-cols-1 gap-4">
            {products.map(p => (
              <div key={p.id} className="bg-white dark:bg-[#1a2e1a] p-4 rounded-2xl flex flex-col md:flex-row items-center gap-6 border border-gray-100 dark:border-gray-800 shadow-sm transition-all hover:shadow-md">
                <img src={p.coverMedia?.url || p.image} className="size-24 rounded-xl object-cover bg-gray-50" />
                <div className="flex-1 text-center md:text-left">
                  <h4 className="text-lg font-bold">{p.name}</h4>
                  <p className="text-sm text-gray-400">{p.category} • {p.variations?.length || 0} Variations</p>
