import React, { useState } from 'react';
import { useStore } from '../App';
import { UserInfo } from '../types';

interface CartSidebarProps {
  isOpen: boolean;
  onClose: () => void;
}

const CartSidebar: React.FC<CartSidebarProps> = ({ isOpen, onClose }) => {
  const { cart, removeFromCart, updateCartQuantity, csContacts } = useStore();
  const [showCheckout, setShowCheckout] = useState(false);
  const [userInfo, setUserInfo] = useState<UserInfo>({ name: '', address: '', phone: '' });

  const total = cart.reduce((acc, item) => {
    const price = item.selectedVariation ? item.selectedVariation.price : item.price;
    return acc + (price * item.quantity);
  }, 0);

  const handleCheckout = () => {
    if (cart.length === 0) return;
    setShowCheckout(true);
  };

  const sendWhatsAppOrder = () => {
    if (!userInfo.name || !userInfo.address || !userInfo.phone) {
      alert('Mohon lengkapi data diri Anda.');
      return;
    }

    const activeCS = csContacts.filter(c => c.isActive);
    if (activeCS.length === 0) {
      alert('Maaf, saat ini CS kami sedang tidak aktif.');
      return;
    }

    const cs = activeCS[Math.floor(Math.random() * activeCS.length)];

    let message = `*HALO LUMINA GOODS - PESANAN BARU*\n\n`;
    message += `*Data Pembeli:*\n`;
    message += `Nama: ${userInfo.name}\n`;
    message += `No. Telp: ${userInfo.phone}\n`;
    message += `Alamat: ${userInfo.address}\n\n`;
    message += `*Daftar Pesanan:*\n`;

    cart.forEach((item, index) => {
      const price = item.selectedVariation ? item.selectedVariation.price : item.price;
      const varName = item.selectedVariation ? ` [Var: ${item.selectedVariation.name}]` : '';
      message += `${index + 1}. ${item.name}${varName} (${item.quantity}x) - Rp ${(price * item.quantity).toLocaleString('id-ID')}\n`;
    });

    message += `\n*TOTAL PESANAN: Rp ${total.toLocaleString('id-ID')}*`;
    message += `\n\n_Mohon bantu konfirmasi pesanan saya ya Kak. Terima kasih!_`;

    const encodedMessage = encodeURIComponent(message);
    window.open(`https://wa.me/${cs.phoneNumber}?text=${encodedMessage}`, '_blank');
  };

  return (
    <>
      <div 
        className={`fixed inset-0 bg-black/50 backdrop-blur-sm z-[100] transition-opacity duration-300 ${isOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
        onClick={onClose}
      />

      <div className={`fixed top-0 right-0 h-full w-full max-w-md bg-white dark:bg-background-dark shadow-2xl z-[101] transform transition-transform duration-300 flex flex-col ${isOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="flex items-center justify-between p-6 border-b border-gray-100 dark:border-gray-800">
          <h2 className="text-xl font-black">{showCheckout ? 'Checkout Info' : 'Shopping Cart'}</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded-lg">
            <span className="material-symbols-outlined font-black">close</span>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          {!showCheckout ? (
            cart.length > 0 ? (
              <div className="flex flex-col gap-6">
                {cart.map(item => (
                  <div key={`${item.id}-${item.selectedVariation?.id}`} className="flex gap-4">
                    <img src={item.selectedVariation ? (item.coverMedia?.url || item.image) : item.image} alt={item.name} className="size-20 rounded-xl object-cover bg-gray-50" />
                    <div className="flex-1">
                      <h4 className="font-bold line-clamp-1">{item.name}</h4>
                      {item.selectedVariation && <p className="text-xs text-gray-400 font-black uppercase">Var: {item.selectedVariation.name}</p>}
                      <p className="text-primary font-black text-sm">Rp {(item.selectedVariation ? item.selectedVariation.price : item.price).toLocaleString('id-ID')}</p>
                      <div className="flex items-center gap-4 mt-2">
                        <div className="flex items-center border border-gray-200 dark:border-gray-800 rounded-lg overflow-hidden">
                          <button onClick={() => updateCartQuantity(item.id, item.selectedVariation?.id || '', item.quantity - 1)} className="px-2 py-1 hover:bg-gray-100 dark:hover:bg-gray-800">-</button>
                          <span className="px-3 py-1 text-sm font-bold border-x border-gray-100 dark:border-gray-800">{item.quantity}</span>
                          <button onClick={() => updateCartQuantity(item.id, item.selectedVariation?.id || '', item.quantity + 1)} className="px-2 py-1 hover:bg-gray-100 dark:hover:bg-gray-800">+</button>
                        </div>
                        <button onClick={() => removeFromCart(item.id, item.selectedVariation?.id)} className="text-red-500 text-xs font-black uppercase hover:underline">Remove</button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-gray-400 gap-4">
                <span className="material-symbols-outlined text-6xl">shopping_cart_off</span>
                <p className="font-bold">Your cart is empty.</p>
              </div>
            )
          ) : (
            <div className="flex flex-col gap-6 animate-in fade-in slide-in-from-right-4 duration-300">
              <div className="flex flex-col gap-2">
                <label className="text-sm font-bold">Full Name</label>
                <input type="text" className="h-12 border rounded-xl px-4 dark:bg-[#1a2e1a] border-gray-200 dark:border-gray-800" value={userInfo.name} onChange={e => setUserInfo({ ...userInfo, name: e.target.value })} placeholder="e.g. John Doe" />
              </div>
              <div className="flex flex-col gap-2">
                <label className="text-sm font-bold">Phone Number</label>
                <input type="tel" className="h-12 border rounded-xl px-4 dark:bg-[#1a2e1a] border-gray-200 dark:border-gray-800" value={userInfo.phone} onChange={e => setUserInfo({ ...userInfo, phone: e.target.value })} placeholder="e.g. 0812345678" />
              </div>
              <div className="flex flex-col gap-2">
                <label className="text-sm font-bold">Full Address</label>
                <textarea className="h-24 border rounded-xl p-4 dark:bg-[#1a2e1a] border-gray-200 dark:border-gray-800 resize-none" value={userInfo.address} onChange={e => setUserInfo({ ...userInfo, address: e.target.value })} placeholder="Street name, house number..." />
              </div>
              <button onClick={() => setShowCheckout(false)} className="text-gray-400 text-sm font-bold hover:underline">Back to Cart</button>
            </div>
          )}
        </div>

        <div className="p-6 border-t border-gray-100 dark:border-gray-800 bg-gray-50 dark:bg-black/20">
          <div className="flex items-center justify-between mb-6">
            <span className="text-gray-500 font-black uppercase tracking-widest text-xs">Total Amount</span>
            <span className="text-2xl font-black text-primary">Rp {total.toLocaleString('id-ID')}</span>
          </div>
          {showCheckout ? (
            <button onClick={sendWhatsAppOrder} disabled={!userInfo.name || !userInfo.address || !userInfo.phone} className="w-full h-14 bg-primary text-[#111811] rounded-2xl font-black flex items-center justify-center gap-3 hover:brightness-110 disabled:opacity-50 shadow-xl shadow-primary/20">
              <span className="material-symbols-outlined font-black">send</span> Order via WhatsApp
            </button>
          ) : (
            <button onClick={handleCheckout} disabled={cart.length === 0} className="w-full h-14 bg-primary text-[#111811] rounded-2xl font-black flex items-center justify-center gap-3 hover:brightness-110 disabled:opacity-50 shadow-xl shadow-primary/20">
              Proceed to Checkout
            </button>
          )}
        </div>
      </div>
    </>
  );
};

export default CartSidebar;

import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { dbService } from '../../services/dbService';
import { Product, CSContact, Media, Variation, ImageKitConfig } from '../../types';
import { useStore } from '../../App';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cs' | 'settings'>('products');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null);
  const [editingCS, setEditingCS] = useState<Partial<CSContact> | null>(null);
  const [ikConfig, setIkConfig] = useState<ImageKitConfig>({ publicKey: '', urlEndpoint: '', authenticationEndpoint: '' });
  const [isUploading, setIsUploading] = useState(false);

  const navigate = useNavigate();
  const { refreshData, products, csContacts } = useStore();

  useEffect(() => {
    const isAuth = localStorage.getItem('lumina_admin_auth');
    if (!isAuth) navigate('/admin/login');

    dbService.getImageKitConfig().then(cfg => {
      if (cfg) setIkConfig(cfg);
    });
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('lumina_admin_auth');
    navigate('/admin/login');
  };

  const uploadToImageKit = async (file: File): Promise<string> => {
    if (!ikConfig.publicKey || !ikConfig.urlEndpoint) {
      alert('Please configure ImageKit settings first.');
      throw new Error('Missing ImageKit Config');
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('fileName', file.name);
      formData.append('publicKey', ikConfig.publicKey);
      formData.append('useUniqueFileName', 'true');

      // Note: In a production environment, you should use ikConfig.authenticationEndpoint to get a signature.
      // For this prototype, we'll use the public upload (requires "Public Uploads" enabled in ImageKit dashboard).
      const response = await fetch('https://upload.imagekit.io/api/v1/files/upload', {
        method: 'POST',
        body: formData,
      });

      const result = await response.json();
      if (!response.ok) throw new Error(result.message || 'Upload failed');
      return result.url;
    } catch (error) {
      console.error('IK Upload Error:', error);
      alert('Upload to ImageKit failed. Ensure your Public Key is correct.');
      throw error;
    } finally {
      setIsUploading(false);
    }
  };

  const handleMediaUpload = async (e: React.ChangeEvent<HTMLInputElement>, isCover: boolean, index?: number) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const url = await uploadToImageKit(file);
      const media: Media = { type: file.type.startsWith('video') ? 'video' : 'image', url };

      if (isCover) {
        setEditingProduct(prev => ({ ...prev, coverMedia: media, image: url }));
      } else {
        setEditingProduct(prev => {
          const gallery = [...(prev?.gallery || [])];
          if (index !== undefined) gallery[index] = media;
          else if (gallery.length < 9) gallery.push(media);
          return { ...prev, gallery };
        });
      }
    } catch (err) {}
  };

  const addVariation = () => {
    const newVar: Variation = { id: Date.now().toString(), name: '', price: 0, stock: 0 };
    setEditingProduct(prev => ({ ...prev, variations: [...(prev?.variations || []), newVar] }));
  };

  const updateVariation = (id: string, field: keyof Variation, value: any) => {
    setEditingProduct(prev => ({
      ...prev,
      variations: (prev?.variations || []).map(v => v.id === id ? { ...v, [field]: value } : v)
    }));
  };

  const removeVariation = (id: string) => {
    setEditingProduct(prev => ({
      ...prev,
      variations: (prev?.variations || []).filter(v => v.id !== id)
    }));
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;

    const product: Product = {
      id: editingProduct.id || Date.now().toString(),
      name: editingProduct.name || '',
      description: editingProduct.description || '',
      price: editingProduct.variations?.[0]?.price || Number(editingProduct.price) || 0,
      category: editingProduct.category || 'General',
      image: editingProduct.coverMedia?.url || editingProduct.image || '',
      coverMedia: editingProduct.coverMedia || { type: 'image', url: '' },
      gallery: editingProduct.gallery || [],
      variations: editingProduct.variations || [],
      rating: editingProduct.rating || 5.0,
      reviews: editingProduct.reviews || 0,
      isFeatured: !!editingProduct.isFeatured,
      createdAt: editingProduct.createdAt || Date.now()
    };

    await dbService.saveProduct(product);
    refreshData();
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  // Fix: Added the missing handleSaveCS function
  const handleSaveCS = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCS) return;

    const contact: CSContact = {
      id: editingCS.id || Date.now().toString(),
      name: editingCS.name || '',
      phoneNumber: editingCS.phoneNumber || '',
      isActive: editingCS.isActive ?? true,
    };

    await dbService.saveCSContact(contact);
    refreshData();
    setIsModalOpen(false);
    setEditingCS(null);
  };

  const handleSaveSettings = async (e: React.FormEvent) => {
    e.preventDefault();
    await dbService.saveImageKitConfig(ikConfig);
    alert('Settings saved successfully!');
  };

  return (
    <div className="px-4 md:px-10 lg:px-40 py-10 min-h-screen">
      <div className="max-w-[1200px] mx-auto">
        <div className="flex flex-col md:flex-row items-center justify-between mb-10 gap-6">
          <div>
            <h1 className="text-4xl font-black">Management Dashboard</h1>
            <p className="text-gray-400 mt-1 font-medium">LuminaGoods Administration</p>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={() => { setEditingProduct({ gallery: [], variations: [], isFeatured: false }); setIsModalOpen(true); setActiveTab('products'); }}
              className="h-12 px-6 bg-primary text-[#111811] rounded-xl font-bold flex items-center gap-2 hover:scale-105 transition-all"
            >
              <span className="material-symbols-outlined">add</span>
              New Product
            </button>
            <button 
              onClick={handleLogout}
              className="h-12 px-6 border border-gray-200 dark:border-gray-800 rounded-xl font-bold hover:bg-red-50 hover:text-red-500 transition-all"
            >
              Logout
            </button>
          </div>
        </div>

        <div className="flex border-b border-gray-200 dark:border-gray-800 mb-8 overflow-x-auto no-scrollbar">
          {['products', 'cs', 'settings'].map(tab => (
            <button 
              key={tab}
              className={`px-8 py-4 font-bold text-sm uppercase tracking-widest whitespace-nowrap ${activeTab === tab ? 'border-b-2 border-primary text-primary' : 'text-gray-400'}`}
              onClick={() => setActiveTab(tab as any)}
            >
              {tab === 'products' ? 'Products' : tab === 'cs' ? 'Customer Service' : 'ImageKit Settings'}
            </button>
          ))}
        </div>

        {activeTab === 'products' ? (
          <div className="grid grid-cols-1 gap-4">
            {products.map(p => (
              <div key={p.id} className="bg-white dark:bg-[#1a2e1a] p-4 rounded-2xl flex flex-col md:flex-row items-center gap-6 border border-gray-100 dark:border-gray-800 shadow-sm transition-all hover:shadow-md">
                <img src={p.coverMedia?.url || p.image} className="size-24 rounded-xl object-cover bg-gray-50" />
                <div className="flex-1 text-center md:text-left">
                  <h4 className="text-lg font-bold">{p.name}</h4>
                  <p className="text-sm text-gray-400">{p.category} • {p.variations?.length || 0} Variations</p>
                  <p className="text-primary font-bold">Rp {p.price.toLocaleString('id-ID')}</p>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => { setEditingProduct(p); setIsModalOpen(true); }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-blue-50 hover:text-blue-500 transition-all">
                    <span className="material-symbols-outlined">edit</span>
                  </button>
                  <button onClick={() => { if(confirm('Delete?')) dbService.deleteProduct(p.id).then(refreshData) }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-red-50 hover:text-red-500 transition-all">
                    <span className="material-symbols-outlined">delete</span>
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : activeTab === 'cs' ? (
          <div className="grid grid-cols-1 gap-4">
            <button onClick={() => { setEditingCS({}); setIsModalOpen(true); }} className="bg-dashed border-2 border-dashed border-gray-200 dark:border-gray-800 p-8 rounded-2xl text-center text-gray-400 hover:border-primary hover:text-primary transition-all mb-4">
              + Add New Customer Service
            </button>
            {csContacts.map(c => (
              <div key={c.id} className="bg-white dark:bg-[#1a2e1a] p-6 rounded-2xl flex items-center justify-between border border-gray-100 dark:border-gray-800">
                <div>
                  <h4 className="text-lg font-bold">{c.name}</h4>
                  <p className="text-gray-400">+{c.phoneNumber}</p>
                  <span className={`inline-block mt-2 px-3 py-1 rounded-full text-[10px] font-black uppercase ${c.isActive ? 'bg-primary/20 text-primary' : 'bg-gray-100 text-gray-400'}`}>{c.isActive ? 'Active' : 'Inactive'}</span>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => { setEditingCS(c); setIsModalOpen(true); }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-blue-50 hover:text-blue-500"><span className="material-symbols-outlined">edit</span></button>
                  <button onClick={() => { dbService.deleteCSContact(c.id).then(refreshData) }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-red-50 hover:text-red-500"><span className="material-symbols-outlined">delete</span></button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="bg-white dark:bg-[#1a2e1a] p-8 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-800 max-w-2xl">
            <h3 className="text-xl font-black mb-6">ImageKit Configuration</h3>
            <form onSubmit={handleSaveSettings} className="flex flex-col gap-6">
              <div className="flex flex-col gap-2">
                <label className="text-sm font-bold">Public Key</label>
                <input type="text" className="h-12 border rounded-xl px-4 dark:bg-black/20" value={ikConfig.publicKey} onChange={e => setIkConfig({...ikConfig, publicKey: e.target.value})} placeholder="public_..." required />
              </div>
              <div className="flex flex-col gap-2">
                <label className="text-sm font-bold">URL Endpoint</label>
                <input type="text" className="h-12 border rounded-xl px-4 dark:bg-black/20" value={ikConfig.urlEndpoint} onChange={e => setIkConfig({...ikConfig, urlEndpoint: e.target.value})} placeholder="https://ik.imagekit.io/your_id" required />
              </div>
              <p className="text-xs text-gray-500 italic">Note: For public uploads to work, make sure "Allow Public Uploads" is enabled in your ImageKit dashboard settings.</p>
              <button className="h-14 bg-primary text-[#111811] rounded-xl font-bold">Save Settings</button>
            </form>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="relative w-full max-w-4xl bg-white dark:bg-background-dark rounded-3xl p-8 shadow-2xl overflow-y-auto max-h-[90vh]">
            <h2 className="text-3xl font-black mb-10">
              {activeTab === 'products' ? (editingProduct?.id ? 'Edit Product' : 'Add Product') : 'CS Management'}
            </h2>

            {activeTab === 'products' ? (
              <form onSubmit={handleSaveProduct} className="flex flex-col gap-10">
                {/* Basic Info */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="flex flex-col gap-2">
                    <label className="text-sm font-bold">Product Name</label>
                    <input required className="h-12 border rounded-xl px-4 dark:bg-black/20" value={editingProduct?.name || ''} onChange={e => setEditingProduct({ ...editingProduct, name: e.target.value })} />
                  </div>
                  <div className="flex flex-col gap-2">
                    <label className="text-sm font-bold">Category</label>
                    <input required className="h-12 border rounded-xl px-4 dark:bg-black/20" value={editingProduct?.category || ''} onChange={e => setEditingProduct({ ...editingProduct, category: e.target.value })} />
                  </div>
                  <div className="flex flex-col gap-2 md:col-span-2">
                    <label className="text-sm font-bold">Description</label>
                    <textarea required className="h-24 border rounded-xl p-4 dark:bg-black/20 resize-none" value={editingProduct?.description || ''} onChange={e => setEditingProduct({ ...editingProduct, description: e.target.value })} />
                  </div>
                </div>

                {/* Media Section */}
                <div>
                  <h3 className="text-lg font-black mb-4 flex items-center gap-2">
                    <span className="material-symbols-outlined">image</span> Product Media
                  </h3>
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    {/* Cover Media */}
                    <div className="flex flex-col gap-2 col-span-1 md:col-span-2">
                      <label className="text-xs font-bold uppercase tracking-widest text-primary">Cover (Video/Image)</label>
                      <div className="relative aspect-video rounded-2xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden">
                        {editingProduct?.coverMedia?.url ? (
                          editingProduct.coverMedia.type === 'video' ? (
                            <video src={editingProduct.coverMedia.url} className="w-full h-full object-cover" />
                          ) : (
                            <img src={editingProduct.coverMedia.url} className="w-full h-full object-cover" />
                          )
                        ) : (
                          <div className="text-center p-4">
                            <span className="material-symbols-outlined text-4xl text-gray-300">add_a_photo</span>
                            <p className="text-[10px] text-gray-400 mt-2">Upload Cover</p>
                          </div>
                        )}
                        <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*,video/*" onChange={e => handleMediaUpload(e, true)} />
                      </div>
                    </div>

                    {/* Gallery items */}
                    {[...Array(9)].map((_, idx) => {
                      const item = editingProduct?.gallery?.[idx];
                      return (
                        <div key={idx} className="flex flex-col gap-2">
                          <label className="text-xs font-bold uppercase tracking-widest text-gray-400">G{idx+1}</label>
                          <div className="relative aspect-square rounded-xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-100 dark:border-gray-800 flex items-center justify-center overflow-hidden">
                            {item?.url ? (
                               item.type === 'video' ? <video src={item.url} className="w-full h-full object-cover" /> : <img src={item.url} className="w-full h-full object-cover" />
                            ) : (
                              <span className="material-symbols-outlined text-2xl text-gray-200">add</span>
                            )}
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*,video/*" onChange={e => handleMediaUpload(e, false, idx)} />
                          </div>
                        </div>
                      )
                    })}
                  </div>
                  {isUploading && <p className="text-xs text-primary font-bold mt-2 animate-pulse">Uploading to ImageKit...</p>}
                </div>

                {/* Variations Section */}
                <div>
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-lg font-black flex items-center gap-2">
                      <span className="material-symbols-outlined">inventory_2</span> Product Variations
                    </h3>
                    <button type="button" onClick={addVariation} className="text-xs font-bold text-primary hover:underline">+ Add Variation</button>
                  </div>
                  <div className="flex flex-col gap-3">
                    {(editingProduct?.variations || []).map(v => (
                      <div key={v.id} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-4 rounded-2xl bg-gray-50 dark:bg-black/20 items-end border border-gray-100 dark:border-gray-800">
                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-bold uppercase">Name (e.g. XL / Red)</label>
                          <input className="h-10 border rounded-lg px-3 text-sm dark:bg-black/20" value={v.name} onChange={e => updateVariation(v.id, 'name', e.target.value)} placeholder="Name" required />
                        </div>
                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-bold uppercase">Price (Rp)</label>
                          <input type="number" className="h-10 border rounded-lg px-3 text-sm dark:bg-black/20" value={v.price || ''} onChange={e => updateVariation(v.id, 'price', Number(e.target.value))} placeholder="Price" required />
                        </div>
                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-bold uppercase">Stock</label>
                          <input type="number" className="h-10 border rounded-lg px-3 text-sm dark:bg-black/20" value={v.stock || ''} onChange={e => updateVariation(v.id, 'stock', Number(e.target.value))} placeholder="Stock" required />
                        </div>
                        <button type="button" onClick={() => removeVariation(v.id)} className="h-10 bg-red-50 text-red-500 rounded-lg font-bold text-xs hover:bg-red-500 hover:text-white transition-all">Remove</button>
                      </div>
                    ))}
                    {(editingProduct?.variations?.length === 0) && <p className="text-center text-sm text-gray-400 italic py-4">No variations added. Please add at least one.</p>}
                  </div>
                </div>

                <div className="flex items-center gap-4 py-6 border-t border-gray-100 dark:border-gray-800">
                  <input type="checkbox" id="isFeatured" checked={editingProduct?.isFeatured || false} onChange={e => setEditingProduct({ ...editingProduct, isFeatured: e.target.checked })} />
                  <label htmlFor="isFeatured" className="text-sm font-bold">Feature this product on homepage</label>
                </div>

                <div className="flex gap-4">
