                    {editingProduct?.id ? 'Save Changes' : 'Create Product'}
                  </button>
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-10 h-14 border rounded-2xl font-bold">Discard</button>
                </div>
              </form>
            ) : (
