      { id: 'v2', name: 'Deep Black', price: 1300000, stock: 5 }
    ],
    rating: 4.9,
    reviews: 120,
    isFeatured: true,
    createdAt: Date.now()
  }
];

export const dbService = {
  async getProducts(): Promise<Product[]> {
    const data = localStorage.getItem(PRODUCTS_KEY);
    return data ? JSON.parse(data) : INITIAL_PRODUCTS;
  },

  async saveProduct(product: Product): Promise<void> {
    const products = await this.getProducts();
    const index = products.findIndex(p => p.id === product.id);
    if (index >= 0) products[index] = product;
    else products.push(product);
    localStorage.setItem(PRODUCTS_KEY, JSON.stringify(products));
  },

  async deleteProduct(id: string): Promise<void> {
    const products = await this.getProducts();
    const filtered = products.filter(p => p.id !== id);
    localStorage.setItem(PRODUCTS_KEY, JSON.stringify(filtered));
  },

  async getCSContacts(): Promise<CSContact[]> {
    const data = localStorage.getItem(CS_KEY);
    return data ? JSON.parse(data) : [{ id: '1', name: 'Admin Utama', phoneNumber: '6281234567890', isActive: true }];
  },

  async saveCSContact(contact: CSContact): Promise<void> {
    const contacts = await this.getCSContacts();
    const index = contacts.findIndex(c => c.id === contact.id);
    if (index >= 0) contacts[index] = contact;
    else contacts.push(contact);
    localStorage.setItem(CS_KEY, JSON.stringify(contacts));
  },

  async deleteCSContact(id: string): Promise<void> {
    const contacts = await this.getCSContacts();
    const filtered = contacts.filter(c => c.id !== id);
    localStorage.setItem(CS_KEY, JSON.stringify(filtered));
  }
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dbService } from '../../services/dbService';
import { Product, CSContact, Media, Variation } from '../../types';
import { useStore } from '../../App';

// Membaca kredensial dari Environment Variables
const IK_PUBLIC_KEY = process.env.VITE_IMAGEKIT_PUBLIC_KEY || '';
const IK_URL_ENDPOINT = process.env.VITE_IMAGEKIT_URL_ENDPOINT || '';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cs'>('products');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null);
  const [editingCS, setEditingCS] = useState<Partial<CSContact> | null>(null);
  const [isUploading, setIsUploading] = useState(false);

  const navigate = useNavigate();
  const { refreshData, products, csContacts } = useStore();

  useEffect(() => {
    const isAuth = localStorage.getItem('lumina_admin_auth');
    if (!isAuth) navigate('/admin/login');
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('lumina_admin_auth');
    navigate('/admin/login');
  };

  const uploadToImageKit = async (file: File): Promise<string> => {
    if (!IK_PUBLIC_KEY || !IK_URL_ENDPOINT) {
      alert('Error: ImageKit Environment Variables belum dikonfigurasi di Vercel/System.');
      throw new Error('Missing ImageKit Credentials');
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('fileName', file.name);
      formData.append('publicKey', IK_PUBLIC_KEY);
      formData.append('useUniqueFileName', 'true');

      // Note: Di frontend, kita menggunakan Public Upload Policy ImageKit
      const response = await fetch('https://upload.imagekit.io/api/v1/files/upload', {
        method: 'POST',
        body: formData,
      });

      const result = await response.json();
      if (!response.ok) throw new Error(result.message || 'Unggahan gagal');
      return result.url;
    } catch (error) {
      console.error('IK Upload Error:', error);
      alert('Gagal mengunggah ke ImageKit. Pastikan "Allow Public Upload" sudah AKTIF di Dashboard ImageKit Anda.');
      throw error;
    } finally {
      setIsUploading(false);
    }
  };

  const handleMediaUpload = async (e: React.ChangeEvent<HTMLInputElement>, isCover: boolean, index?: number) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const url = await uploadToImageKit(file);
      const media: Media = { type: file.type.startsWith('video') ? 'video' : 'image', url };

      if (isCover) {
        setEditingProduct(prev => ({ ...prev, coverMedia: media, image: url }));
      } else {
        setEditingProduct(prev => {
          const gallery = [...(prev?.gallery || [])];
          if (index !== undefined) gallery[index] = media;
          else if (gallery.length < 9) gallery.push(media);
          return { ...prev, gallery };
        });
      }
    } catch (err) {}
  };

  const addVariation = () => {
    const newVar: Variation = { id: Date.now().toString(), name: '', price: 0, stock: 0 };
    setEditingProduct(prev => ({ ...prev, variations: [...(prev?.variations || []), newVar] }));
  };

  const updateVariation = (id: string, field: keyof Variation, value: any) => {
    setEditingProduct(prev => ({
      ...prev,
      variations: (prev?.variations || []).map(v => v.id === id ? { ...v, [field]: value } : v)
    }));
  };

  const removeVariation = (id: string) => {
    setEditingProduct(prev => ({
      ...prev,
      variations: (prev?.variations || []).filter(v => v.id !== id)
    }));
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;

    const product: Product = {
      id: editingProduct.id || Date.now().toString(),
      name: editingProduct.name || '',
      description: editingProduct.description || '',
      price: editingProduct.variations?.[0]?.price || Number(editingProduct.price) || 0,
      category: editingProduct.category || 'General',
      image: editingProduct.coverMedia?.url || editingProduct.image || '',
      coverMedia: editingProduct.coverMedia || { type: 'image', url: '' },
      gallery: editingProduct.gallery || [],
      variations: editingProduct.variations || [],
      rating: editingProduct.rating || 5.0,
      reviews: editingProduct.reviews || 0,
      isFeatured: !!editingProduct.isFeatured,
      createdAt: editingProduct.createdAt || Date.now()
    };

    await dbService.saveProduct(product);
    refreshData();
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  const handleSaveCS = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCS) return;

    const contact: CSContact = {
      id: editingCS.id || Date.now().toString(),
      name: editingCS.name || '',
      phoneNumber: editingCS.phoneNumber || '',
      isActive: editingCS.isActive ?? true,
    };

    await dbService.saveCSContact(contact);
    refreshData();
    setIsModalOpen(false);
    setEditingCS(null);
  };

  return (
    <div className="px-4 md:px-10 lg:px-40 py-10 min-h-screen">
      <div className="max-w-[1200px] mx-auto">
        <div className="flex flex-col md:flex-row items-center justify-between mb-10 gap-6">
          <div>
            <h1 className="text-4xl font-black tracking-tighter">Admin Panel</h1>
            <p className="text-gray-400 mt-1 font-medium">LuminaGoods Management</p>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={() => { setEditingProduct({ gallery: [], variations: [], isFeatured: false }); setIsModalOpen(true); setActiveTab('products'); }}
              className="h-12 px-6 bg-primary text-[#111811] rounded-xl font-bold flex items-center gap-2 hover:scale-105 transition-all"
            >
              <span className="material-symbols-outlined">add</span>
              Produk Baru
            </button>
            <button 
              onClick={handleLogout}
              className="h-12 px-6 border border-gray-200 dark:border-gray-800 rounded-xl font-bold hover:bg-red-50 hover:text-red-500 transition-all"
            >
              Logout
            </button>
          </div>
        </div>

        <div className="flex border-b border-gray-200 dark:border-gray-800 mb-8 overflow-x-auto no-scrollbar">
          {['products', 'cs'].map(tab => (
            <button 
              key={tab}
              className={`px-8 py-4 font-black text-sm uppercase tracking-widest whitespace-nowrap ${activeTab === tab ? 'border-b-2 border-primary text-primary' : 'text-gray-400'}`}
              onClick={() => setActiveTab(tab as any)}
            >
              {tab === 'products' ? 'Produk' : 'Customer Service'}
            </button>
          ))}
        </div>

        {activeTab === 'products' ? (
          <div className="grid grid-cols-1 gap-4">
            {products.map(p => (
              <div key={p.id} className="bg-white dark:bg-[#1a2e1a] p-4 rounded-2xl flex flex-col md:flex-row items-center gap-6 border border-gray-100 dark:border-gray-800 shadow-sm transition-all hover:shadow-md">
                <img src={p.coverMedia?.url || p.image} className="size-24 rounded-xl object-cover bg-gray-50 dark:bg-black/20" />
                <div className="flex-1 text-center md:text-left">
                  <h4 className="text-lg font-bold">{p.name}</h4>
                  <p className="text-sm text-gray-400">{p.category} • {p.variations?.length || 0} Variasi</p>
                  <p className="text-primary font-bold">Rp {p.price.toLocaleString('id-ID')}</p>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => { setEditingProduct(p); setIsModalOpen(true); }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-blue-50 hover:text-blue-500 transition-all">
                    <span className="material-symbols-outlined">edit</span>
                  </button>
                  <button onClick={() => { if(confirm('Hapus produk ini?')) dbService.deleteProduct(p.id).then(refreshData) }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-red-50 hover:text-red-500 transition-all">
                    <span className="material-symbols-outlined">delete</span>
                  </button>
                </div>
              </div>
            ))}
            {products.length === 0 && <div className="text-center py-20 text-gray-400 font-bold">Belum ada produk.</div>}
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-4">
            <button onClick={() => { setEditingCS({}); setIsModalOpen(true); }} className="bg-dashed border-2 border-dashed border-gray-200 dark:border-gray-800 p-8 rounded-2xl text-center text-gray-400 hover:border-primary hover:text-primary transition-all mb-4">
              + Tambah Customer Service
            </button>
            {csContacts.map(c => (
              <div key={c.id} className="bg-white dark:bg-[#1a2e1a] p-6 rounded-2xl flex items-center justify-between border border-gray-100 dark:border-gray-800">
                <div>
                  <h4 className="text-lg font-bold">{c.name}</h4>
                  <p className="text-gray-400">+{c.phoneNumber}</p>
                  <span className={`inline-block mt-2 px-3 py-1 rounded-full text-[10px] font-black uppercase ${c.isActive ? 'bg-primary/20 text-primary' : 'bg-gray-100 text-gray-400'}`}>{c.isActive ? 'Aktif' : 'Non-aktif'}</span>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => { setEditingCS(c); setIsModalOpen(true); }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-blue-50 hover:text-blue-500"><span className="material-symbols-outlined">edit</span></button>
                  <button onClick={() => { if(confirm('Hapus CS ini?')) dbService.deleteCSContact(c.id).then(refreshData) }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-red-50 hover:text-red-500"><span className="material-symbols-outlined">delete</span></button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="relative w-full max-w-4xl bg-white dark:bg-background-dark rounded-3xl p-8 shadow-2xl overflow-y-auto max-h-[90vh]">
            <h2 className="text-3xl font-black mb-10 tracking-tighter">
              {activeTab === 'products' ? (editingProduct?.id ? 'Edit Produk' : 'Tambah Produk') : 'Manajemen CS'}
            </h2>

            {activeTab === 'products' ? (
              <form onSubmit={handleSaveProduct} className="flex flex-col gap-10">
                {/* Basic Info */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="flex flex-col gap-2">
                    <label className="text-sm font-bold">Nama Produk</label>
                    <input required className="h-12 border rounded-xl px-4 dark:bg-black/20 outline-none focus:border-primary" value={editingProduct?.name || ''} onChange={e => setEditingProduct({ ...editingProduct, name: e.target.value })} />
                  </div>
                  <div className="flex flex-col gap-2">
                    <label className="text-sm font-bold">Kategori</label>
                    <input required className="h-12 border rounded-xl px-4 dark:bg-black/20 outline-none focus:border-primary" value={editingProduct?.category || ''} onChange={e => setEditingProduct({ ...editingProduct, category: e.target.value })} />
                  </div>
                  <div className="flex flex-col gap-2 md:col-span-2">
                    <label className="text-sm font-bold">Deskripsi</label>
                    <textarea required className="h-24 border rounded-xl p-4 dark:bg-black/20 resize-none outline-none focus:border-primary" value={editingProduct?.description || ''} onChange={e => setEditingProduct({ ...editingProduct, description: e.target.value })} />
                  </div>
                </div>

                {/* Media Section */}
                <div>
                  <h3 className="text-lg font-black mb-4 flex items-center gap-2 tracking-tight">
                    <span className="material-symbols-outlined">image</span> Media Produk
                  </h3>
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    {/* Cover Media */}
                    <div className="flex flex-col gap-2 col-span-1 md:col-span-2">
                      <label className="text-xs font-black uppercase tracking-widest text-primary">Cover (Wajib)</label>
                      <div className="relative aspect-video rounded-2xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden transition-colors hover:border-primary">
                        {editingProduct?.coverMedia?.url ? (
                          editingProduct.coverMedia.type === 'video' ? (
                            <video src={editingProduct.coverMedia.url} className="w-full h-full object-cover" />
                          ) : (
                            <img src={editingProduct.coverMedia.url} className="w-full h-full object-cover" />
                          )
                        ) : (
                          <div className="text-center p-4">
                            <span className="material-symbols-outlined text-4xl text-gray-300">add_a_photo</span>
                            <p className="text-[10px] text-gray-400 font-black uppercase mt-2">Pilih Media</p>
                          </div>
                        )}
                        <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*,video/*" onChange={e => handleMediaUpload(e, true)} />
                      </div>
                    </div>

                    {/* Gallery items */}
                    {[...Array(9)].map((_, idx) => {
                      const item = editingProduct?.gallery?.[idx];
                      return (
                        <div key={idx} className="flex flex-col gap-2">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Media {idx+1}</label>
                          <div className="relative aspect-square rounded-xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-100 dark:border-gray-800 flex items-center justify-center overflow-hidden transition-colors hover:border-primary">
                            {item?.url ? (
                               item.type === 'video' ? <video src={item.url} className="w-full h-full object-cover" /> : <img src={item.url} className="w-full h-full object-cover" />
                            ) : (
                              <span className="material-symbols-outlined text-2xl text-gray-200">add</span>
                            )}
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*,video/*" onChange={e => handleMediaUpload(e, false, idx)} />
                          </div>
                        </div>
                      )
                    })}
                  </div>
                  {isUploading && <p className="text-xs text-primary font-black mt-3 animate-pulse uppercase tracking-widest">Uploading to ImageKit...</p>}
                </div>

                {/* Variations Section */}
                <div>
                  <div className="flex items-center justify-between mb-4">
                    <h3 className="text-lg font-black flex items-center gap-2 tracking-tight">
                      <span className="material-symbols-outlined">inventory_2</span> Variasi Produk
                    </h3>
                    <button type="button" onClick={addVariation} className="text-xs font-black text-primary hover:underline uppercase tracking-widest">+ Tambah Variasi</button>
                  </div>
                  <div className="flex flex-col gap-3">
                    {(editingProduct?.variations || []).map(v => (
                      <div key={v.id} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-4 rounded-2xl bg-gray-50 dark:bg-black/20 items-end border border-gray-100 dark:border-gray-800">
                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Nama</label>
                          <input className="h-10 border rounded-lg px-3 text-sm dark:bg-black/20 outline-none" value={v.name} onChange={e => updateVariation(v.id, 'name', e.target.value)} placeholder="Misal: XL" required />
                        </div>
                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Harga (Rp)</label>
                          <input type="number" className="h-10 border rounded-lg px-3 text-sm dark:bg-black/20 outline-none" value={v.price || ''} onChange={e => updateVariation(v.id, 'price', Number(e.target.value))} placeholder="Harga" required />
