                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Stok</label>
                          <input type="number" className="h-10 border rounded-lg px-3 text-sm dark:bg-black/20 outline-none" value={v.stock || ''} onChange={e => updateVariation(v.id, 'stock', Number(e.target.value))} placeholder="Stok" required />
                        </div>
                        <button type="button" onClick={() => removeVariation(v.id)} className="h-10 bg-red-50 text-red-500 rounded-lg font-black text-[10px] uppercase tracking-widest hover:bg-red-500 hover:text-white transition-all">Hapus</button>
                      </div>
                    ))}
                    {(editingProduct?.variations?.length === 0) && <p className="text-center text-sm text-gray-400 italic py-4">Belum ada variasi.</p>}
                  </div>
                </div>

                <div className="flex items-center gap-4 py-6 border-t border-gray-100 dark:border-gray-800">
                  <input type="checkbox" id="isFeatured" className="rounded text-primary focus:ring-primary" checked={editingProduct?.isFeatured || false} onChange={e => setEditingProduct({ ...editingProduct, isFeatured: e.target.checked })} />
                  <label htmlFor="isFeatured" className="text-sm font-bold">Feature di Halaman Utama</label>
                </div>

                <div className="flex gap-4">
                  <button type="submit" disabled={isUploading} className="flex-1 h-14 bg-primary text-[#111811] rounded-2xl font-black text-lg shadow-xl shadow-primary/20 hover:brightness-110 disabled:opacity-50">
                    {editingProduct?.id ? 'Simpan Perubahan' : 'Buat Produk'}
                  </button>
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-10 h-14 border rounded-2xl font-bold hover:bg-gray-50 dark:hover:bg-black/20">Batal</button>
                </div>
              </form>
            ) : (
              <form onSubmit={handleSaveCS} className="flex flex-col gap-6">
                <div className="flex flex-col gap-2">
                  <label className="text-sm font-bold">Nama CS</label>
                  <input required className="h-12 border rounded-xl px-4 dark:bg-black/20 outline-none focus:border-primary" value={editingCS?.name || ''} onChange={e => setEditingCS({ ...editingCS, name: e.target.value })} />
                </div>
                <div className="flex flex-col gap-2">
                  <label className="text-sm font-bold">WhatsApp (Tanpa '+', misal: 62812...)</label>
                  <input required className="h-12 border rounded-xl px-4 dark:bg-black/20 outline-none focus:border-primary" value={editingCS?.phoneNumber || ''} onChange={e => setEditingCS({ ...editingCS, phoneNumber: e.target.value.replace(/\D/g, '') })} />
                </div>
                <div className="flex items-center gap-4">
                  <input type="checkbox" id="isActive" className="rounded text-primary focus:ring-primary" checked={editingCS?.isActive ?? true} onChange={e => setEditingCS({ ...editingCS, isActive: e.target.checked })} />
                  <label htmlFor="isActive" className="text-sm font-bold">Aktif</label>
                </div>
                <div className="flex gap-4 mt-6">
                  <button type="submit" className="flex-1 h-14 bg-primary text-[#111811] rounded-xl font-bold shadow-lg shadow-primary/20 hover:brightness-110">Simpan CS</button>
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-8 h-14 border rounded-xl font-bold hover:bg-gray-50 dark:hover:bg-black/20">Batal</button>
                </div>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

