    } catch (error) {
      console.error('IK Upload Error:', error);
      alert('Gagal mengunggah ke ImageKit. Pastikan opsi "Allow Public Upload" sudah AKTIF di Dashboard ImageKit Anda.');
      throw error;
    } finally {
      setIsUploading(false);
    }
  };

  const handleMediaUpload = async (e: React.ChangeEvent<HTMLInputElement>, isCover: boolean, index?: number) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const url = await uploadToImageKit(file);
      const media: Media = { type: file.type.startsWith('video') ? 'video' : 'image', url };

      if (isCover) {
        setEditingProduct(prev => ({ ...prev, coverMedia: media, image: url }));
      } else {
        setEditingProduct(prev => {
          const gallery = [...(prev?.gallery || [])];
          if (index !== undefined) gallery[index] = media;
          else if (gallery.length < 9) gallery.push(media);
          return { ...prev, gallery };
        });
      }
    } catch (err) {}
  };

  const addVariation = () => {
    const newVar: Variation = { id: Date.now().toString(), name: '', price: 0, stock: 0 };
    setEditingProduct(prev => ({ ...prev, variations: [...(prev?.variations || []), newVar] }));
  };

  const updateVariation = (id: string, field: keyof Variation, value: any) => {
    setEditingProduct(prev => ({
      ...prev,
      variations: (prev?.variations || []).map(v => v.id === id ? { ...v, [field]: value } : v)
    }));
  };

  const removeVariation = (id: string) => {
    setEditingProduct(prev => ({
      ...prev,
      variations: (prev?.variations || []).filter(v => v.id !== id)
    }));
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;

    const product: Product = {
      id: editingProduct.id || Date.now().toString(),
      name: editingProduct.name || '',
      description: editingProduct.description || '',
      price: editingProduct.variations?.[0]?.price || Number(editingProduct.price) || 0,
      category: editingProduct.category || 'General',
      image: editingProduct.coverMedia?.url || editingProduct.image || '',
      coverMedia: editingProduct.coverMedia || { type: 'image', url: '' },
      gallery: editingProduct.gallery || [],
      variations: editingProduct.variations || [],
      rating: editingProduct.rating || 5.0,
      reviews: editingProduct.reviews || 0,
      isFeatured: !!editingProduct.isFeatured,
      createdAt: editingProduct.createdAt || Date.now()
    };

    await dbService.saveProduct(product);
    refreshData();
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  const handleSaveCS = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCS) return;

    const contact: CSContact = {
      id: editingCS.id || Date.now().toString(),
      name: editingCS.name || '',
      phoneNumber: editingCS.phoneNumber || '',
      isActive: editingCS.isActive ?? true,
    };

    await dbService.saveCSContact(contact);
    refreshData();
    setIsModalOpen(false);
    setEditingCS(null);
  };

  const activeCSCount = csContacts.filter(c => c.isActive).length;

  return (
    <div className="px-4 md:px-10 lg:px-40 py-10 min-h-screen">
      <div className="max-w-[1200px] mx-auto">
        <div className="flex flex-col md:flex-row items-center justify-between mb-10 gap-6">
          <div>
            <h1 className="text-4xl font-black tracking-tighter">Admin Panel</h1>
            <p className="text-gray-400 mt-1 font-medium">Manajemen Toko LuminaGoods</p>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={() => { setEditingProduct({ gallery: [], variations: [], isFeatured: false }); setIsModalOpen(true); setActiveTab('products'); }}
              className="h-12 px-6 bg-primary text-[#111811] rounded-xl font-black flex items-center gap-2 hover:scale-105 transition-all shadow-lg shadow-primary/20"
            >
              <span className="material-symbols-outlined">add</span>
              Produk Baru
            </button>
            <button 
              onClick={handleLogout}
              className="h-12 px-6 border border-gray-200 dark:border-gray-800 rounded-xl font-bold hover:bg-red-50 hover:text-red-500 transition-all"
            >
              Logout
            </button>
          </div>
        </div>

        <div className="flex border-b border-gray-200 dark:border-gray-800 mb-8 overflow-x-auto no-scrollbar">
          {['products', 'cs'].map(tab => (
            <button 
              key={tab}
              className={`px-8 py-4 font-black text-sm uppercase tracking-widest whitespace-nowrap transition-all ${activeTab === tab ? 'border-b-4 border-primary text-primary' : 'text-gray-400 hover:text-gray-600'}`}
              onClick={() => setActiveTab(tab as any)}
            >
              {tab === 'products' ? 'Daftar Produk' : 'Customer Service'}
            </button>
          ))}
        </div>

        {activeTab === 'products' ? (
          <div className="grid grid-cols-1 gap-4">
            {products.map(p => (
              <div key={p.id} className="bg-white dark:bg-[#1a2e1a] p-4 rounded-3xl flex flex-col md:flex-row items-center gap-6 border border-gray-100 dark:border-gray-800 shadow-sm transition-all hover:shadow-md group">
                <div className="relative size-24 shrink-0 rounded-2xl overflow-hidden bg-gray-50 dark:bg-black/20">
                  <img src={p.coverMedia?.url || p.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                  {p.isFeatured && (
                    <div className="absolute top-1 left-1 bg-primary text-[#111811] text-[8px] font-black px-1.5 py-0.5 rounded-md uppercase tracking-tighter">Featured</div>
                  )}
                </div>
                <div className="flex-1 text-center md:text-left">
                  <h4 className="text-xl font-black tracking-tight">{p.name}</h4>
                  <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">{p.category} • {p.variations?.length || 0} Variasi</p>
                  <p className="text-primary font-black text-lg mt-1">Rp {p.price.toLocaleString('id-ID')}</p>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => { setEditingProduct(p); setIsModalOpen(true); }} className="p-4 bg-gray-50 dark:bg-black/20 rounded-2xl hover:bg-blue-50 hover:text-blue-500 transition-all">
                    <span className="material-symbols-outlined">edit</span>
                  </button>
                  <button onClick={() => { if(confirm('Hapus produk ini secara permanen?')) dbService.deleteProduct(p.id).then(refreshData) }} className="p-4 bg-gray-50 dark:bg-black/20 rounded-2xl hover:bg-red-50 hover:text-red-500 transition-all">
                    <span className="material-symbols-outlined">delete</span>
                  </button>
                </div>
              </div>
            ))}
            {products.length === 0 && (
              <div className="text-center py-32 bg-gray-50 dark:bg-black/10 rounded-3xl border-2 border-dashed border-gray-200 dark:border-gray-800">
                <span className="material-symbols-outlined text-6xl text-gray-200 mb-4">inventory_2</span>
                <p className="text-gray-400 font-bold uppercase tracking-widest">Belum ada produk yang ditambahkan</p>
              </div>
            )}
          </div>
        ) : (
          <div className="flex flex-col gap-6">
            <div className="bg-primary/10 border border-primary/20 p-6 rounded-3xl flex gap-4 items-start">
              <span className="material-symbols-outlined text-primary text-3xl shrink-0">info</span>
              <div>
                <h4 className="font-black text-primary uppercase text-sm tracking-widest mb-1">Sistem Rotasi CS Aktif</h4>
                <p className="text-xs text-gray-600 dark:text-gray-400 leading-relaxed font-medium">
                  Saat ini Anda memiliki <strong>{activeCSCount} CS aktif</strong>. Sistem akan memilih salah satu dari mereka secara acak 
                  setiap kali pembeli melakukan checkout. Ini memastikan beban kerja admin Anda terbagi secara merata.
                </p>
              </div>
            </div>

            <button onClick={() => { setEditingCS({}); setIsModalOpen(true); }} className="bg-dashed border-2 border-dashed border-gray-200 dark:border-gray-800 p-10 rounded-3xl text-center text-gray-400 hover:border-primary hover:text-primary transition-all group">
              <span className="material-symbols-outlined text-4xl mb-2 group-hover:scale-110 transition-transform">person_add</span>
              <p className="font-black uppercase tracking-widest text-sm">Tambah CS Baru</p>
            </button>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {csContacts.map(c => (
                <div key={c.id} className="bg-white dark:bg-[#1a2e1a] p-6 rounded-3xl flex items-center justify-between border border-gray-100 dark:border-gray-800 shadow-sm">
                  <div className="flex items-center gap-4">
                    <div className={`size-12 rounded-full flex items-center justify-center font-black text-lg ${c.isActive ? 'bg-primary text-[#111811]' : 'bg-gray-100 text-gray-400'}`}>
                      {c.name.charAt(0)}
                    </div>
                    <div>
                      <h4 className="text-lg font-black tracking-tight">{c.name}</h4>
                      <p className="text-gray-400 font-bold text-sm">+{c.phoneNumber}</p>
                      <div className="flex items-center gap-2 mt-1">
                        <span className={`size-2 rounded-full ${c.isActive ? 'bg-primary animate-pulse' : 'bg-gray-300'}`}></span>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${c.isActive ? 'text-primary' : 'text-gray-400'}`}>
                          {c.isActive ? 'Menerima Order' : 'Istirahat'}
                        </span>
                      </div>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => { setEditingCS(c); setIsModalOpen(true); }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-blue-50 hover:text-blue-500 transition-all">
                      <span className="material-symbols-outlined text-sm">edit</span>
                    </button>
                    <button onClick={() => { if(confirm('Hapus CS ini?')) dbService.deleteCSContact(c.id).then(refreshData) }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-red-50 hover:text-red-500 transition-all">
                      <span className="material-symbols-outlined text-sm">delete</span>
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="relative w-full max-w-4xl bg-white dark:bg-background-dark rounded-[40px] p-8 md:p-12 shadow-2xl overflow-y-auto max-h-[90vh] no-scrollbar">
            <h2 className="text-4xl font-black mb-10 tracking-tighter">
              {activeTab === 'products' ? (editingProduct?.id ? 'Edit Detail Produk' : 'Buat Produk Baru') : 'Pengaturan CS'}
            </h2>

            {activeTab === 'products' ? (
              <form onSubmit={handleSaveProduct} className="flex flex-col gap-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="flex flex-col gap-2">
                    <label className="text-xs font-black uppercase tracking-widest text-gray-400">Nama Produk</label>
                    <input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary transition-colors font-bold" value={editingProduct?.name || ''} onChange={e => setEditingProduct({ ...editingProduct, name: e.target.value })} />
                  </div>
                  <div className="flex flex-col gap-2">
                    <label className="text-xs font-black uppercase tracking-widest text-gray-400">Kategori</label>
                    <input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary transition-colors font-bold" value={editingProduct?.category || ''} onChange={e => setEditingProduct({ ...editingProduct, category: e.target.value })} />
                  </div>
                  <div className="flex flex-col gap-2 md:col-span-2">
                    <label className="text-xs font-black uppercase tracking-widest text-gray-400">Deskripsi Lengkap</label>
                    <textarea required className="h-32 border-2 border-gray-100 dark:border-gray-800 rounded-2xl p-6 dark:bg-black/20 resize-none outline-none focus:border-primary transition-colors font-bold" value={editingProduct?.description || ''} onChange={e => setEditingProduct({ ...editingProduct, description: e.target.value })} />
                  </div>
                </div>

                <div>
                  <h3 className="text-xl font-black mb-6 flex items-center gap-2 tracking-tight">
                    <span className="material-symbols-outlined text-primary">photo_library</span> Media & Gallery
                  </h3>
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    <div className="flex flex-col gap-2 col-span-1 md:col-span-2">
                      <label className="text-[10px] font-black uppercase tracking-widest text-primary">Cover Utama (Video/Foto)</label>
                      <div className="relative aspect-video rounded-3xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden transition-all hover:border-primary group">
                        {editingProduct?.coverMedia?.url ? (
                          editingProduct.coverMedia.type === 'video' ? (
                            <video src={editingProduct.coverMedia.url} className="w-full h-full object-cover" />
                          ) : (
                            <img src={editingProduct.coverMedia.url} className="w-full h-full object-cover" />
                          )
                        ) : (
                          <div className="text-center p-4">
                            <span className="material-symbols-outlined text-5xl text-gray-200 group-hover:text-primary transition-colors">add_a_photo</span>
                            <p className="text-[10px] text-gray-400 font-black uppercase mt-2">Upload Cover</p>
                          </div>
                        )}
                        <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*,video/*" onChange={e => handleMediaUpload(e, true)} />
                      </div>
                    </div>

                    {[...Array(6)].map((_, idx) => {
                      const item = editingProduct?.gallery?.[idx];
                      return (
                        <div key={idx} className="flex flex-col gap-2">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Slide {idx+1}</label>
                          <div className="relative aspect-square rounded-2xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-100 dark:border-gray-800 flex items-center justify-center overflow-hidden transition-all hover:border-primary">
                            {item?.url ? (
                               item.type === 'video' ? <video src={item.url} className="w-full h-full object-cover" /> : <img src={item.url} className="w-full h-full object-cover" />
                            ) : (
                              <span className="material-symbols-outlined text-2xl text-gray-200">add</span>
                            )}
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*,video/*" onChange={e => handleMediaUpload(e, false, idx)} />
                          </div>
                        </div>
                      )
                    })}
                  </div>
                  {isUploading && <p className="text-xs text-primary font-black mt-4 animate-pulse uppercase tracking-widest">Memproses File ke ImageKit...</p>}
                </div>

                <div>
                  <div className="flex items-center justify-between mb-6">
                    <h3 className="text-xl font-black flex items-center gap-2 tracking-tight">
                      <span className="material-symbols-outlined text-primary">sell</span> Variasi & Harga
                    </h3>
                    <button type="button" onClick={addVariation} className="px-4 py-2 bg-primary/10 text-primary rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-primary hover:text-[#111811] transition-all">+ Tambah Opsi</button>
                  </div>
                  <div className="flex flex-col gap-4">
                    {(editingProduct?.variations || []).map(v => (
                      <div key={v.id} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-6 rounded-3xl bg-gray-50 dark:bg-black/20 items-end border border-gray-100 dark:border-gray-800">
                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Nama Varian</label>
                          <input className="h-12 border-2 border-white dark:border-gray-800 rounded-xl px-4 text-sm dark:bg-black/20 outline-none font-bold" value={v.name} onChange={e => updateVariation(v.id, 'name', e.target.value)} placeholder="Misal: Ukuran XL" required />
                        </div>
                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Harga Satuan (Rp)</label>
                          <input type="number" className="h-12 border-2 border-white dark:border-gray-800 rounded-xl px-4 text-sm dark:bg-black/20 outline-none font-bold" value={v.price || ''} onChange={e => updateVariation(v.id, 'price', Number(e.target.value))} placeholder="Harga" required />
                        </div>
                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Stok Gudang</label>
                          <input type="number" className="h-12 border-2 border-white dark:border-gray-800 rounded-xl px-4 text-sm dark:bg-black/20 outline-none font-bold" value={v.stock || ''} onChange={e => updateVariation(v.id, 'stock', Number(e.target.value))} placeholder="Stok" required />
                        </div>
                        <button type="button" onClick={() => removeVariation(v.id)} className="h-12 bg-red-50 text-red-500 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-red-500 hover:text-white transition-all">Hapus Varian</button>
                      </div>
                    ))}
                    {(editingProduct?.variations?.length === 0) && <p className="text-center text-sm text-gray-400 italic py-6">Wajib menambahkan minimal satu variasi produk.</p>}
                  </div>
                </div>

                <div className="flex items-center gap-4 py-8 border-t border-gray-100 dark:border-gray-800">
                  <input type="checkbox" id="isFeatured" className="size-5 rounded border-2 border-gray-200 text-primary focus:ring-primary transition-all" checked={editingProduct?.isFeatured || false} onChange={e => setEditingProduct({ ...editingProduct, isFeatured: e.target.checked })} />
                  <label htmlFor="isFeatured" className="text-sm font-black uppercase tracking-widest cursor-pointer">Tampilkan di Koleksi Unggulan (Halaman Utama)</label>
                </div>

                <div className="flex flex-col md:flex-row gap-4">
                  <button type="submit" disabled={isUploading} className="flex-1 h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all disabled:opacity-50">
                    {editingProduct?.id ? 'Simpan Perubahan' : 'Terbitkan Produk'}
                  </button>
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-12 h-16 border-2 border-gray-100 dark:border-gray-800 rounded-2xl font-black text-lg hover:bg-gray-50 dark:hover:bg-black/20 transition-all">Batal</button>
                </div>
              </form>
            ) : (
              <form onSubmit={handleSaveCS} className="flex flex-col gap-8">
                <div className="flex flex-col gap-2">
                  <label className="text-xs font-black uppercase tracking-widest text-gray-400">Nama Lengkap Admin CS</label>
                  <input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary transition-colors font-bold" value={editingCS?.name || ''} onChange={e => setEditingCS({ ...editingCS, name: e.target.value })} placeholder="Contoh: Admin Siska" />
                </div>
                <div className="flex flex-col gap-2">
                  <label className="text-xs font-black uppercase tracking-widest text-gray-400">Nomor WhatsApp (Gunakan Kode Negara, Misal: 62812...)</label>
                  <input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary transition-colors font-bold" value={editingCS?.phoneNumber || ''} onChange={e => setEditingCS({ ...editingCS, phoneNumber: e.target.value.replace(/\D/g, '') })} placeholder="628123456789" />
                </div>
                <div className="flex items-center gap-4 bg-gray-50 dark:bg-black/20 p-6 rounded-2xl">
                  <input type="checkbox" id="isActive" className="size-6 rounded border-2 border-gray-200 text-primary focus:ring-primary transition-all" checked={editingCS?.isActive ?? true} onChange={e => setEditingCS({ ...editingCS, isActive: e.target.checked })} />
                  <label htmlFor="isActive" className="text-sm font-black uppercase tracking-widest cursor-pointer select-none">Aktif (Bisa Menerima Orderan Saat Ini)</label>
                </div>
                <div className="flex flex-col md:flex-row gap-4 mt-6">
                  <button type="submit" className="flex-1 h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all">Simpan Data CS</button>
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-10 h-16 border-2 border-gray-100 dark:border-gray-800 rounded-2xl font-black text-lg hover:bg-gray-50 dark:hover:bg-black/20 transition-all">Batal</button>
                </div>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

