import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dbService } from '../../services/dbService';
import { Product, CSContact, Media, Variation, SiteSettings } from '../../types';
import { useStore } from '../../App';

const IK_PUBLIC_KEY = process.env.VITE_IMAGEKIT_PUBLIC_KEY || '';
const IK_URL_ENDPOINT = process.env.VITE_IMAGEKIT_URL_ENDPOINT || '';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cs' | 'site'>('products');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null);
  const [editingCS, setEditingCS] = useState<Partial<CSContact> | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings | null>(null);
  const [isUploading, setIsUploading] = useState(false);

  const navigate = useNavigate();
  const { refreshData, products, csContacts, siteSettings } = useStore();

  useEffect(() => {
    const isAuth = localStorage.getItem('lumina_admin_auth');
    if (!isAuth) navigate('/admin/login');
    setLocalSettings(siteSettings);
  }, [navigate, siteSettings]);

  const handleLogout = () => {
    localStorage.removeItem('lumina_admin_auth');
    navigate('/admin/login');
  };

  const uploadToImageKit = async (file: File): Promise<string> => {
    if (!IK_PUBLIC_KEY || !IK_URL_ENDPOINT) {
      alert('Error: Kredensial ImageKit belum diatur di Vercel (VITE_IMAGEKIT_PUBLIC_KEY & VITE_IMAGEKIT_URL_ENDPOINT).');
      throw new Error('Missing ImageKit Credentials');
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('fileName', file.name);
      formData.append('publicKey', IK_PUBLIC_KEY);
      formData.append('useUniqueFileName', 'true');

      const response = await fetch('https://upload.imagekit.io/api/v1/files/upload', {
        method: 'POST',
        body: formData,
      });

      const result = await response.json();
      if (!response.ok) throw new Error(result.message || 'Unggahan gagal');
      return result.url;
    } catch (error) {
      console.error('IK Upload Error:', error);
      alert('Gagal mengunggah ke ImageKit. Pastikan opsi "Allow Public Upload" sudah AKTIF di Dashboard ImageKit Anda.');
      throw error;
    } finally {
      setIsUploading(false);
    }
  };

  const handleMediaUpload = async (e: React.ChangeEvent<HTMLInputElement>, isCover: boolean, index?: number) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const url = await uploadToImageKit(file);
      const media: Media = { type: file.type.startsWith('video') ? 'video' : 'image', url };

      if (isCover) {
        setEditingProduct(prev => ({ ...prev, coverMedia: media, image: url }));
      } else {
        setEditingProduct(prev => {
          const gallery = [...(prev?.gallery || [])];
          if (index !== undefined) gallery[index] = media;
          else if (gallery.length < 9) gallery.push(media);
          return { ...prev, gallery };
        });
      }
    } catch (err) {}
  };

  const handleSiteFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, field: 'logoUrl' | 'heroImage') => {
    const file = e.target.files?.[0];
    if (!file || !localSettings) return;

    try {
      const url = await uploadToImageKit(file);
      setLocalSettings({ ...localSettings, [field]: url });
    } catch (err) {}
  };

  const addVariation = () => {
    const newVar: Variation = { id: Date.now().toString(), name: '', price: 0, stock: 0 };
    setEditingProduct(prev => ({ ...prev, variations: [...(prev?.variations || []), newVar] }));
  };

  const updateVariation = (id: string, field: keyof Variation, value: any) => {
    setEditingProduct(prev => ({
      ...prev,
      variations: (prev?.variations || []).map(v => v.id === id ? { ...v, [field]: value } : v)
    }));
  };

  const removeVariation = (id: string) => {
    setEditingProduct(prev => ({
      ...prev,
      variations: (prev?.variations || []).filter(v => v.id !== id)
    }));
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;

    const product: Product = {
      id: editingProduct.id || Date.now().toString(),
      name: editingProduct.name || '',
      description: editingProduct.description || '',
      price: editingProduct.variations?.[0]?.price || Number(editingProduct.price) || 0,
      category: editingProduct.category || 'General',
      image: editingProduct.coverMedia?.url || editingProduct.image || '',
      coverMedia: editingProduct.coverMedia || { type: 'image', url: '' },
      gallery: editingProduct.gallery || [],
      variations: editingProduct.variations || [],
      rating: editingProduct.rating || 5.0,
      reviews: editingProduct.reviews || 0,
      isFeatured: !!editingProduct.isFeatured,
      createdAt: editingProduct.createdAt || Date.now()
    };

    await dbService.saveProduct(product);
    refreshData();
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  const handleSaveCS = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCS) return;

    const contact: CSContact = {
      id: editingCS.id || Date.now().toString(),
      name: editingCS.name || '',
      phoneNumber: editingCS.phoneNumber || '',
      isActive: editingCS.isActive ?? true,
    };

    await dbService.saveCSContact(contact);
    refreshData();
    setIsModalOpen(false);
    setEditingCS(null);
