            <p className="text-gray-400 mt-1 font-medium">Manajemen Toko {siteSettings.siteName}</p>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={() => { setEditingProduct({ gallery: [], variations: [], isFeatured: false }); setIsModalOpen(true); setActiveTab('products'); }}
              className="h-12 px-6 bg-primary text-[#111811] rounded-xl font-black flex items-center gap-2 hover:scale-105 transition-all shadow-lg shadow-primary/20"
            >
              <span className="material-symbols-outlined">add</span>
              Produk Baru
            </button>
            <button 
              onClick={handleLogout}
              className="h-12 px-6 border border-gray-200 dark:border-gray-800 rounded-xl font-bold hover:bg-red-50 hover:text-red-500 transition-all"
            >
              Logout
            </button>
          </div>
        </div>

        <div className="flex border-b border-gray-200 dark:border-gray-800 mb-8 overflow-x-auto no-scrollbar">
          {['products', 'cs', 'site'].map(tab => (
            <button 
              key={tab}
              className={`px-8 py-4 font-black text-sm uppercase tracking-widest whitespace-nowrap transition-all ${activeTab === tab ? 'border-b-4 border-primary text-primary' : 'text-gray-400 hover:text-gray-600'}`}
              onClick={() => setActiveTab(tab as any)}
            >
              {tab === 'products' ? 'Daftar Produk' : tab === 'cs' ? 'Customer Service' : 'Konfigurasi Situs'}
            </button>
          ))}
        </div>

        {activeTab === 'products' ? (
          <div className="grid grid-cols-1 gap-4">
            {products.map(p => (
              <div key={p.id} className="bg-white dark:bg-[#1a2e1a] p-4 rounded-3xl flex flex-col md:flex-row items-center gap-6 border border-gray-100 dark:border-gray-800 shadow-sm transition-all hover:shadow-md group">
                <div className="relative size-24 shrink-0 rounded-2xl overflow-hidden bg-gray-50 dark:bg-black/20">
                  <img src={p.coverMedia?.url || p.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
                  {p.isFeatured && (
                    <div className="absolute top-1 left-1 bg-primary text-[#111811] text-[8px] font-black px-1.5 py-0.5 rounded-md uppercase tracking-tighter">Featured</div>
                  )}
                </div>
                <div className="flex-1 text-center md:text-left">
                  <h4 className="text-xl font-black tracking-tight">{p.name}</h4>
                  <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">{p.category} • {p.variations?.length || 0} Variasi</p>
                  <p className="text-primary font-black text-lg mt-1">Rp {p.price.toLocaleString('id-ID')}</p>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => { setEditingProduct(p); setIsModalOpen(true); }} className="p-4 bg-gray-50 dark:bg-black/20 rounded-2xl hover:bg-blue-50 hover:text-blue-500 transition-all">
                    <span className="material-symbols-outlined">edit</span>
                  </button>
                  <button onClick={() => { if(confirm('Hapus produk ini secara permanen?')) dbService.deleteProduct(p.id).then(refreshData) }} className="p-4 bg-gray-50 dark:bg-black/20 rounded-2xl hover:bg-red-50 hover:text-red-500 transition-all">
                    <span className="material-symbols-outlined">delete</span>
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : activeTab === 'cs' ? (
          <div className="flex flex-col gap-6">
            <div className="bg-primary/10 border border-primary/20 p-6 rounded-3xl flex gap-4 items-start">
              <span className="material-symbols-outlined text-primary text-3xl shrink-0">info</span>
              <div>
                <h4 className="font-black text-primary uppercase text-sm tracking-widest mb-1">Sistem Rotasi CS Aktif</h4>
                <p className="text-xs text-gray-600 dark:text-gray-400 leading-relaxed font-medium">
                  Saat ini Anda memiliki <strong>{activeCSCount} CS aktif</strong>. Sistem akan memilih salah satu dari mereka secara acak 
                  setiap kali pembeli melakukan checkout.
                </p>
              </div>
            </div>

            <button onClick={() => { setEditingCS({}); setIsModalOpen(true); }} className="bg-dashed border-2 border-dashed border-gray-200 dark:border-gray-800 p-10 rounded-3xl text-center text-gray-400 hover:border-primary hover:text-primary transition-all group">
              <span className="material-symbols-outlined text-4xl mb-2 group-hover:scale-110 transition-transform">person_add</span>
              <p className="font-black uppercase tracking-widest text-sm">Tambah CS Baru</p>
            </button>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {csContacts.map(c => (
                <div key={c.id} className="bg-white dark:bg-[#1a2e1a] p-6 rounded-3xl flex items-center justify-between border border-gray-100 dark:border-gray-800 shadow-sm">
                  <div className="flex items-center gap-4">
                    <div className={`size-12 rounded-full flex items-center justify-center font-black text-lg ${c.isActive ? 'bg-primary text-[#111811]' : 'bg-gray-100 text-gray-400'}`}>
                      {c.name.charAt(0)}
                    </div>
                    <div>
                      <h4 className="text-lg font-black tracking-tight">{c.name}</h4>
                      <p className="text-gray-400 font-bold text-sm">+{c.phoneNumber}</p>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => { setEditingCS(c); setIsModalOpen(true); }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-blue-50 hover:text-blue-500 transition-all">
                      <span className="material-symbols-outlined text-sm">edit</span>
                    </button>
                    <button onClick={() => { if(confirm('Hapus CS ini?')) dbService.deleteCSContact(c.id).then(refreshData) }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:bg-red-50 hover:text-red-500 transition-all">
                      <span className="material-symbols-outlined text-sm">delete</span>
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="bg-white dark:bg-[#1a2e1a] p-10 rounded-[40px] border border-gray-100 dark:border-gray-800 shadow-xl max-w-4xl mx-auto">
             <h2 className="text-3xl font-black mb-10 tracking-tighter">Site Customization</h2>
             {localSettings && (
               <form onSubmit={handleSaveSiteSettings} className="flex flex-col gap-10">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="flex flex-col gap-2">
                     <label className="text-xs font-black uppercase tracking-widest text-gray-400">Nama Website</label>
                     <input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary font-bold" value={localSettings.siteName} onChange={e => setLocalSettings({...localSettings, siteName: e.target.value})} />
                   </div>

                   <div className="flex flex-col gap-2">
                     <label className="text-xs font-black uppercase tracking-widest text-gray-400">Logo Website</label>
                     <div className="relative h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 flex items-center justify-between group overflow-hidden">
                       <span className="text-xs text-gray-400 font-bold truncate pr-4">{localSettings.logoUrl || 'Belum ada logo'}</span>
                       <span className="material-symbols-outlined text-primary">upload_file</span>
                       <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleSiteFileUpload(e, 'logoUrl')} />
                     </div>
                   </div>

                   <div className="flex flex-col gap-2 md:col-span-2">
                     <label className="text-xs font-black uppercase tracking-widest text-gray-400">Gambar Hero Utama</label>
                     <div className="relative aspect-video rounded-3xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden transition-all hover:border-primary group">
                        <img src={localSettings.heroImage} className="absolute inset-0 w-full h-full object-cover opacity-30 group-hover:opacity-100 transition-opacity" />
                        <div className="relative z-10 text-center pointer-events-none">
                           <span className="material-symbols-outlined text-4xl text-primary mb-2">image</span>
                           <p className="text-[10px] font-black uppercase tracking-widest">Ganti Gambar Hero</p>
                        </div>
                        <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleSiteFileUpload(e, 'heroImage')} />
                     </div>
                   </div>

                   <div className="flex flex-col gap-2 md:col-span-2">
                     <label className="text-xs font-black uppercase tracking-widest text-gray-400">Judul Hero (Gunakan \n untuk baris baru)</label>
                     <textarea required className="h-28 border-2 border-gray-100 dark:border-gray-800 rounded-2xl p-6 dark:bg-black/20 outline-none focus:border-primary font-bold resize-none" value={localSettings.heroTitle} onChange={e => setLocalSettings({...localSettings, heroTitle: e.target.value})} />
                   </div>

                   <div className="flex flex-col gap-2 md:col-span-2">
                     <label className="text-xs font-black uppercase tracking-widest text-gray-400">Sub-judul Hero</label>
                     <textarea required className="h-28 border-2 border-gray-100 dark:border-gray-800 rounded-2xl p-6 dark:bg-black/20 outline-none focus:border-primary font-bold resize-none" value={localSettings.heroSubtitle} onChange={e => setLocalSettings({...localSettings, heroSubtitle: e.target.value})} />
                   </div>

                   <div className="flex flex-col gap-2 md:col-span-2">
                     <label className="text-xs font-black uppercase tracking-widest text-gray-400">Deskripsi Footer</label>
                     <textarea required className="h-28 border-2 border-gray-100 dark:border-gray-800 rounded-2xl p-6 dark:bg-black/20 outline-none focus:border-primary font-bold resize-none" value={localSettings.footerDescription} onChange={e => setLocalSettings({...localSettings, footerDescription: e.target.value})} />
                   </div>
                 </div>

                 <button type="submit" disabled={isUploading} className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all disabled:opacity-50 mt-4">
