            {activeTab === 'products' ? (
              <form onSubmit={handleSaveProduct} className="flex flex-col gap-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="flex flex-col gap-2">
                    <label className="text-xs font-black uppercase tracking-widest text-gray-400">Nama Produk</label>
                    <input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary transition-colors font-bold" value={editingProduct?.name || ''} onChange={e => setEditingProduct({ ...editingProduct, name: e.target.value })} />
                  </div>
                  <div className="flex flex-col gap-2">
                    <label className="text-xs font-black uppercase tracking-widest text-gray-400">Kategori</label>
                    <input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary transition-colors font-bold" value={editingProduct?.category || ''} onChange={e => setEditingProduct({ ...editingProduct, category: e.target.value })} />
                  </div>
                  <div className="flex flex-col gap-2 md:col-span-2">
                    <label className="text-xs font-black uppercase tracking-widest text-gray-400">Deskripsi Lengkap</label>
                    <textarea required className="h-32 border-2 border-gray-100 dark:border-gray-800 rounded-2xl p-6 dark:bg-black/20 resize-none outline-none focus:border-primary transition-colors font-bold" value={editingProduct?.description || ''} onChange={e => setEditingProduct({ ...editingProduct, description: e.target.value })} />
                  </div>
                </div>

                <div>
                  <h3 className="text-xl font-black mb-6 flex items-center gap-2 tracking-tight">
                    <span className="material-symbols-outlined text-primary">photo_library</span> Media & Gallery
                  </h3>
                  <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    <div className="flex flex-col gap-2 col-span-1 md:col-span-2">
                      <label className="text-[10px] font-black uppercase tracking-widest text-primary">Cover Utama (Video/Foto)</label>
                      <div className="relative aspect-video rounded-3xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden transition-all hover:border-primary group">
                        {editingProduct?.coverMedia?.url ? (
                          editingProduct.coverMedia.type === 'video' ? (
                            <video src={editingProduct.coverMedia.url} className="w-full h-full object-cover" />
                          ) : (
                            <img src={editingProduct.coverMedia.url} className="w-full h-full object-cover" />
                          )
                        ) : (
                          <div className="text-center p-4">
                            <span className="material-symbols-outlined text-5xl text-gray-200 group-hover:text-primary transition-colors">add_a_photo</span>
                            <p className="text-[10px] text-gray-400 font-black uppercase mt-2">Upload Cover</p>
                          </div>
                        )}
                        <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*,video/*" onChange={e => handleMediaUpload(e, true)} />
                      </div>
                    </div>

                    {[...Array(6)].map((_, idx) => {
                      const item = editingProduct?.gallery?.[idx];
                      return (
                        <div key={idx} className="flex flex-col gap-2">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Slide {idx+1}</label>
                          <div className="relative aspect-square rounded-2xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-100 dark:border-gray-800 flex items-center justify-center overflow-hidden transition-all hover:border-primary">
                            {item?.url ? (
                               item.type === 'video' ? <video src={item.url} className="w-full h-full object-cover" /> : <img src={item.url} className="w-full h-full object-cover" />
                            ) : (
                              <span className="material-symbols-outlined text-2xl text-gray-200">add</span>
                            )}
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*,video/*" onChange={e => handleMediaUpload(e, false, idx)} />
                          </div>
                        </div>
                      )
                    })}
                  </div>
                  {isUploading && <p className="text-xs text-primary font-black mt-4 animate-pulse uppercase tracking-widest">Memproses File ke ImageKit...</p>}
                </div>

                <div>
                  <div className="flex items-center justify-between mb-6">
                    <h3 className="text-xl font-black flex items-center gap-2 tracking-tight">
                      <span className="material-symbols-outlined text-primary">sell</span> Variasi & Harga
                    </h3>
                    <button type="button" onClick={addVariation} className="px-4 py-2 bg-primary/10 text-primary rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-primary hover:text-[#111811] transition-all">+ Tambah Opsi</button>
                  </div>
                  <div className="flex flex-col gap-4">
                    {(editingProduct?.variations || []).map(v => (
                      <div key={v.id} className="grid grid-cols-1 md:grid-cols-4 gap-4 p-6 rounded-3xl bg-gray-50 dark:bg-black/20 items-end border border-gray-100 dark:border-gray-800">
                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Nama Varian</label>
                          <input className="h-12 border-2 border-white dark:border-gray-800 rounded-xl px-4 text-sm dark:bg-black/20 outline-none font-bold" value={v.name} onChange={e => updateVariation(v.id, 'name', e.target.value)} placeholder="Misal: Ukuran XL" required />
                        </div>
                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Harga Satuan (Rp)</label>
                          <input type="number" className="h-12 border-2 border-white dark:border-gray-800 rounded-xl px-4 text-sm dark:bg-black/20 outline-none font-bold" value={v.price || ''} onChange={e => updateVariation(v.id, 'price', Number(e.target.value))} placeholder="Harga" required />
                        </div>
                        <div className="flex flex-col gap-1">
                          <label className="text-[10px] font-black uppercase tracking-widest text-gray-400">Stok Gudang</label>
                          <input type="number" className="h-12 border-2 border-white dark:border-gray-800 rounded-xl px-4 text-sm dark:bg-black/20 outline-none font-bold" value={v.stock || ''} onChange={e => updateVariation(v.id, 'stock', Number(e.target.value))} placeholder="Stok" required />
                        </div>
                        <button type="button" onClick={() => removeVariation(v.id)} className="h-12 bg-red-50 text-red-500 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-red-500 hover:text-white transition-all">Hapus Varian</button>
                      </div>
                    ))}
                    {(editingProduct?.variations?.length === 0) && <p className="text-center text-sm text-gray-400 italic py-6">Wajib menambahkan minimal satu variasi produk.</p>}
                  </div>
                </div>

                <div className="flex items-center gap-4 py-8 border-t border-gray-100 dark:border-gray-800">
                  <input type="checkbox" id="isFeatured" className="size-5 rounded border-2 border-gray-200 text-primary focus:ring-primary transition-all" checked={editingProduct?.isFeatured || false} onChange={e => setEditingProduct({ ...editingProduct, isFeatured: e.target.checked })} />
                  <label htmlFor="isFeatured" className="text-sm font-black uppercase tracking-widest cursor-pointer">Tampilkan di Koleksi Unggulan (Halaman Utama)</label>
                </div>

                <div className="flex flex-col md:flex-row gap-4">
                  <button type="submit" disabled={isUploading} className="flex-1 h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all disabled:opacity-50">
                    {editingProduct?.id ? 'Simpan Perubahan' : 'Terbitkan Produk'}
                  </button>
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-12 h-16 border-2 border-gray-100 dark:border-gray-800 rounded-2xl font-black text-lg hover:bg-gray-50 dark:hover:bg-black/20 transition-all">Batal</button>
                </div>
              </form>
            ) : (
              <form onSubmit={handleSaveCS} className="flex flex-col gap-8">
                <div className="flex flex-col gap-2">
                  <label className="text-xs font-black uppercase tracking-widest text-gray-400">Nama Lengkap Admin CS</label>
                  <input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary transition-colors font-bold" value={editingCS?.name || ''} onChange={e => setEditingCS({ ...editingCS, name: e.target.value })} placeholder="Contoh: Admin Siska" />
                </div>
                <div className="flex flex-col gap-2">
                  <label className="text-xs font-black uppercase tracking-widest text-gray-400">Nomor WhatsApp (Gunakan Kode Negara, Misal: 62812...)</label>
                  <input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary transition-colors font-bold" value={editingCS?.phoneNumber || ''} onChange={e => setEditingCS({ ...editingCS, phoneNumber: e.target.value.replace(/\D/g, '') })} placeholder="628123456789" />
                </div>
                <div className="flex items-center gap-4 bg-gray-50 dark:bg-black/20 p-6 rounded-2xl">
                  <input type="checkbox" id="isActive" className="size-6 rounded border-2 border-gray-200 text-primary focus:ring-primary transition-all" checked={editingCS?.isActive ?? true} onChange={e => setEditingCS({ ...editingCS, isActive: e.target.checked })} />
                  <label htmlFor="isActive" className="text-sm font-black uppercase tracking-widest cursor-pointer select-none">Aktif (Bisa Menerima Orderan Saat Ini)</label>
                </div>
                <div className="flex flex-col md:flex-row gap-4 mt-6">
                  <button type="submit" className="flex-1 h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all">Simpan Data CS</button>
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-10 h-16 border-2 border-gray-100 dark:border-gray-800 rounded-2xl font-black text-lg hover:bg-gray-50 dark:hover:bg-black/20 transition-all">Batal</button>
                </div>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

