/**
 * Persiapan Integrasi Neon Database
 * 
 * Anda perlu mengatur variabel lingkungan berikut di Vercel/Hosting:
 * VITE_NEON_API_URL: URL endpoint API Anda yang terhubung ke Neon
 * VITE_NEON_API_KEY: Key otentikasi jika diperlukan
 */
const NEON_API_URL = process.env.VITE_NEON_API_URL || '';
const PRODUCTS_KEY = 'lumina_products';
const CS_KEY = 'lumina_cs_contacts';
const SITE_SETTINGS_KEY = 'lumina_site_settings';

const DEFAULT_SETTINGS: SiteSettings = {
  siteName: 'LuminaGoods',
  logoUrl: '',
  heroImage: 'https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&q=80&w=2000',
  heroTitle: 'Elegance in Every Detail.',
  heroSubtitle: 'Discover premium goods curated for those who appreciate high-quality craftsmanship and modern minimalist design.',
  footerDescription: 'Crafting a seamless shopping experience for the modern aesthetic. Your one-stop shop for premium, artisanal UMKM goods.'
};

const INITIAL_PRODUCTS: Product[] = [
  {
    id: '1',
    name: 'Handcrafted Leather Tote',
    description: 'Quality leather tote bag made with vegetable tanned leather. Perfect for daily use.',
    price: 1200000,
    category: 'Fashion',
    image: 'https://images.unsplash.com/photo-1544816153-17684070a7b1?auto=format&fit=crop&q=80&w=800',
    coverMedia: { type: 'image', url: 'https://images.unsplash.com/photo-1544816153-17684070a7b1?auto=format&fit=crop&q=80&w=800' },
    gallery: [],
    variations: [
      { id: 'v1', name: 'Tan Brown', price: 1200000, stock: 10 },
      { id: 'v2', name: 'Deep Black', price: 1300000, stock: 5 }
    ],
    rating: 4.9,
    reviews: 120,
    isFeatured: true,
    createdAt: Date.now()
  }
];

// Helper untuk fetch ke Neon jika URL tersedia, jika tidak gunakan localStorage
async function apiFetch(endpoint: string, options?: RequestInit) {
  if (!NEON_API_URL) return null;
  try {
    const res = await fetch(`${NEON_API_URL}${endpoint}`, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...(process.env.VITE_NEON_API_KEY ? { 'Authorization': `Bearer ${process.env.VITE_NEON_API_KEY}` } : {}),
        ...options?.headers
      }
    });
    if (!res.ok) throw new Error('API Error');
    return await res.json();
  } catch (e) {
    console.error('Neon DB Fetch Error:', e);
    return null;
  }
}

export const dbService = {
  async getProducts(): Promise<Product[]> {
    const apiData = await apiFetch('/products');
    if (apiData) return apiData;

    const data = localStorage.getItem(PRODUCTS_KEY);
    return data ? JSON.parse(data) : INITIAL_PRODUCTS;
  },

  async saveProduct(product: Product): Promise<void> {
    const success = await apiFetch('/products', {
      method: 'POST',
      body: JSON.stringify(product)
    });

    if (!success) {
      const products = await this.getProducts();
      const index = products.findIndex(p => p.id === product.id);
      if (index >= 0) products[index] = product;
      else products.push(product);
      localStorage.setItem(PRODUCTS_KEY, JSON.stringify(products));
    }
  },

  async deleteProduct(id: string): Promise<void> {
    const success = await apiFetch(`/products/${id}`, { method: 'DELETE' });

    if (!success) {
      const products = await this.getProducts();
      const filtered = products.filter(p => p.id !== id);
      localStorage.setItem(PRODUCTS_KEY, JSON.stringify(filtered));
    }
  },

  async getCSContacts(): Promise<CSContact[]> {
    const apiData = await apiFetch('/cs-contacts');
    if (apiData) return apiData;

    const data = localStorage.getItem(CS_KEY);
    return data ? JSON.parse(data) : [{ id: '1', name: 'Admin Utama', phoneNumber: '6281234567890', isActive: true }];
  },

  async saveCSContact(contact: CSContact): Promise<void> {
    const success = await apiFetch('/cs-contacts', {
      method: 'POST',
      body: JSON.stringify(contact)
    });

    if (!success) {
      const contacts = await this.getCSContacts();
      const index = contacts.findIndex(c => c.id === contact.id);
      if (index >= 0) contacts[index] = contact;
      else contacts.push(contact);
      localStorage.setItem(CS_KEY, JSON.stringify(contacts));
    }
  },

  async deleteCSContact(id: string): Promise<void> {
    const success = await apiFetch(`/cs-contacts/${id}`, { method: 'DELETE' });

    if (!success) {
      const contacts = await this.getCSContacts();
      const filtered = contacts.filter(c => c.id !== id);
      localStorage.setItem(CS_KEY, JSON.stringify(filtered));
    }
  },

  async getSiteSettings(): Promise<SiteSettings> {
    const apiData = await apiFetch('/settings');
    if (apiData) return apiData;

    const data = localStorage.getItem(SITE_SETTINGS_KEY);
    return data ? JSON.parse(data) : DEFAULT_SETTINGS;
  },

  async saveSiteSettings(settings: SiteSettings): Promise<void> {
    const success = await apiFetch('/settings', {
      method: 'POST',
      body: JSON.stringify(settings)
    });

    if (!success) {
      localStorage.setItem(SITE_SETTINGS_KEY, JSON.stringify(settings));
    }
  }
};

