const App: React.FC = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [csContacts, setCSContacts] = useState<CSContact[]>([]);
  const [testimonials, setTestimonials] = useState<Testimonial[]>([]);
  const [siteSettings, setSiteSettings] = useState<SiteSettings | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);

  const fetchData = useCallback(async () => {
    const [p, c, s, t] = await Promise.all([
      dbService.getProducts(), 
      dbService.getCSContacts(),
      dbService.getSiteSettings(),
      dbService.getTestimonials()
    ]);
    setProducts(p);
    setCSContacts(c);
    setSiteSettings(s);
    setTestimonials(t);
  }, []);

  useEffect(() => {
    fetchData();
    const savedCart = localStorage.getItem('lumina_cart');
    if (savedCart) setCart(JSON.parse(savedCart));
  }, [fetchData]);

  useEffect(() => {
    localStorage.setItem('lumina_cart', JSON.stringify(cart));
  }, [cart]);

  const addToCart = (product: Product, variation?: Variation) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === product.id && item.selectedVariation?.id === variation?.id);
      if (existing) {
        return prev.map(item => (item.id === product.id && item.selectedVariation?.id === variation?.id) ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, selectedVariation: variation, quantity: 1 }];
    });
    setIsCartOpen(true);
  };

  const removeFromCart = (productId: string, variationId?: string) => {
    setCart(prev => prev.filter(item => !(item.id === productId && item.selectedVariation?.id === variationId)));
  };

  const updateCartQuantity = (productId: string, variationId: string, quantity: number) => {
    if (quantity < 1) return removeFromCart(productId, variationId);
    setCart(prev => prev.map(item => (item.id === productId && item.selectedVariation?.id === variationId) ? { ...item, quantity } : item));
  };

  const clearCart = () => setCart([]);

  if (!siteSettings) return null;

  return (
    <StoreContext.Provider value={{ 
      products, cart, addToCart, removeFromCart, updateCartQuantity, 
      clearCart, csContacts, testimonials, siteSettings, refreshData: fetchData, isCartOpen, setIsCartOpen 
    }}>
      <Router>
        <div className="min-h-screen flex flex-col">
          <Header onCartOpen={() => setIsCartOpen(true)} cartCount={cart.reduce((acc, item) => acc + item.quantity, 0)} />
          <main className="flex-1">
            <Routes>
              <Route path="/" element={<HomePage />} />
              <Route path="/products" element={<ProductsPage />} />
              <Route path="/product/:id" element={<ProductDetailPage />} />
              <Route path="/about" element={<AboutPage />} />
              <Route path="/contact" element={<ContactPage />} />
              <Route path="/admin/login" element={<AdminLogin />} />
              <Route path="/admin/*" element={<AdminDashboard />} />
            </Routes>
          </main>
          <Footer />
          <CartSidebar isOpen={isCartOpen} onClose={() => setIsCartOpen(false)} />
        </div>
      </Router>
    </StoreContext.Provider>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dbService } from '../../services/dbService';
import { Product, CSContact, Media, Variation, SiteSettings, Testimonial } from '../../types';
import { useStore } from '../../App';

const IK_PUBLIC_KEY = process.env.VITE_IMAGEKIT_PUBLIC_KEY || '';
const IK_URL_ENDPOINT = process.env.VITE_IMAGEKIT_URL_ENDPOINT || '';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cs' | 'site' | 'testimonials'>('products');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null);
  const [editingCS, setEditingCS] = useState<Partial<CSContact> | null>(null);
  const [editingTestimonial, setEditingTestimonial] = useState<Partial<Testimonial> | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings | null>(null);
  const [isUploading, setIsUploading] = useState(false);

  const navigate = useNavigate();
  const { refreshData, products, csContacts, siteSettings, testimonials } = useStore();

  useEffect(() => {
    const isAuth = localStorage.getItem('lumina_admin_auth');
    if (!isAuth) navigate('/admin/login');
    setLocalSettings(siteSettings);
  }, [navigate, siteSettings]);

  const handleLogout = () => {
    localStorage.removeItem('lumina_admin_auth');
    navigate('/admin/login');
  };

  const uploadToImageKit = async (file: File): Promise<string> => {
    if (!IK_PUBLIC_KEY || !IK_URL_ENDPOINT) {
      alert('Error: Kredensial ImageKit belum diatur (VITE_IMAGEKIT_PUBLIC_KEY & VITE_IMAGEKIT_URL_ENDPOINT).');
      throw new Error('Missing ImageKit Credentials');
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('fileName', file.name);
      formData.append('publicKey', IK_PUBLIC_KEY);
      formData.append('useUniqueFileName', 'true');

      const response = await fetch('https://upload.imagekit.io/api/v1/files/upload', {
        method: 'POST',
        body: formData,
      });

      const result = await response.json();
      if (!response.ok) throw new Error(result.message || 'Unggahan gagal');
      return result.url;
    } catch (error) {
      console.error('IK Upload Error:', error);
      alert('Gagal mengunggah ke ImageKit.');
      throw error;
    } finally {
      setIsUploading(false);
    }
  };

  const handleMediaUpload = async (e: React.ChangeEvent<HTMLInputElement>, isCover: boolean, index?: number) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const url = await uploadToImageKit(file);
      const media: Media = { type: file.type.startsWith('video') ? 'video' : 'image', url };
      if (isCover) setEditingProduct(prev => ({ ...prev, coverMedia: media, image: url }));
      else setEditingProduct(prev => {
        const gallery = [...(prev?.gallery || [])];
        if (index !== undefined) gallery[index] = media;
        else if (gallery.length < 9) gallery.push(media);
        return { ...prev, gallery };
      });
    } catch (err) {}
  };

  const handleTestimonialUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const url = await uploadToImageKit(file);
      setEditingTestimonial(prev => ({ ...prev, imageUrl: url }));
    } catch (err) {}
  };

  const handleSiteFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, field: 'logoUrl' | 'heroImage') => {
    const file = e.target.files?.[0];
    if (!file || !localSettings) return;
    try {
      const url = await uploadToImageKit(file);
      setLocalSettings({ ...localSettings, [field]: url });
    } catch (err) {}
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;
    const product: Product = {
      id: editingProduct.id || Date.now().toString(),
      name: editingProduct.name || '',
      description: editingProduct.description || '',
      price: editingProduct.variations?.[0]?.price || Number(editingProduct.price) || 0,
      category: editingProduct.category || 'General',
      image: editingProduct.coverMedia?.url || editingProduct.image || '',
      coverMedia: editingProduct.coverMedia || { type: 'image', url: '' },
      gallery: editingProduct.gallery || [],
      variations: editingProduct.variations || [],
      isFeatured: !!editingProduct.isFeatured,
      createdAt: editingProduct.createdAt || Date.now()
    };
    await dbService.saveProduct(product);
    refreshData();
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  const handleSaveCS = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCS) return;
    const contact: CSContact = {
      id: editingCS.id || Date.now().toString(),
      name: editingCS.name || '',
      phoneNumber: editingCS.phoneNumber || '',
      isActive: editingCS.isActive ?? true,
    };
    await dbService.saveCSContact(contact);
    refreshData();
    setIsModalOpen(false);
    setEditingCS(null);
  };

  const handleSaveTestimonial = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingTestimonial || !editingTestimonial.imageUrl) return;
    const testimonial: Testimonial = {
      id: editingTestimonial.id || Date.now().toString(),
      imageUrl: editingTestimonial.imageUrl,
      customerName: editingTestimonial.customerName || '',
      isActive: editingTestimonial.isActive ?? true,
    };
    await dbService.saveTestimonial(testimonial);
    refreshData();
    setIsModalOpen(false);
    setEditingTestimonial(null);
  };

  const toggleTestimonial = async (t: Testimonial) => {
    await dbService.saveTestimonial({ ...t, isActive: !t.isActive });
    refreshData();
  };

  return (
    <div className="px-4 md:px-10 lg:px-40 py-10 min-h-screen">
      <div className="max-w-[1200px] mx-auto">
        <div className="flex flex-col md:flex-row items-center justify-between mb-10 gap-6">
          <div>
            <h1 className="text-4xl font-black tracking-tighter">Admin Panel</h1>
            <p className="text-gray-400 mt-1 font-medium">Manajemen Toko {siteSettings.siteName}</p>
          </div>
          <div className="flex gap-4">
            {activeTab === 'products' && (
              <button onClick={() => { setEditingProduct({ gallery: [], variations: [], isFeatured: false }); setIsModalOpen(true); }} className="h-12 px-6 bg-primary text-[#111811] rounded-xl font-black flex items-center gap-2 hover:scale-105 transition-all shadow-lg shadow-primary/20">
                <span className="material-symbols-outlined">add</span> Produk Baru
              </button>
            )}
            {activeTab === 'testimonials' && (
              <button onClick={() => { setEditingTestimonial({ isActive: true }); setIsModalOpen(true); }} className="h-12 px-6 bg-primary text-[#111811] rounded-xl font-black flex items-center gap-2 hover:scale-105 transition-all shadow-lg shadow-primary/20">
                <span className="material-symbols-outlined">add_photo_alternate</span> Upload Testimoni
              </button>
            )}
            <button onClick={handleLogout} className="h-12 px-6 border border-gray-200 dark:border-gray-800 rounded-xl font-bold hover:bg-red-50 hover:text-red-500 transition-all">Logout</button>
          </div>
        </div>

        <div className="flex border-b border-gray-200 dark:border-gray-800 mb-8 overflow-x-auto no-scrollbar">
          {['products', 'testimonials', 'cs', 'site'].map(tab => (
            <button 
              key={tab}
              className={`px-8 py-4 font-black text-sm uppercase tracking-widest whitespace-nowrap transition-all ${activeTab === tab ? 'border-b-4 border-primary text-primary' : 'text-gray-400 hover:text-gray-600'}`}
              onClick={() => setActiveTab(tab as any)}
            >
              {tab === 'products' ? 'Produk' : tab === 'testimonials' ? 'Testimoni' : tab === 'cs' ? 'Customer Service' : 'Situs'}
            </button>
          ))}
        </div>

        {activeTab === 'products' ? (
          <div className="grid grid-cols-1 gap-4">
            {products.map(p => (
              <div key={p.id} className="bg-white dark:bg-[#1a2e1a] p-4 rounded-3xl flex flex-col md:flex-row items-center gap-6 border border-gray-100 dark:border-gray-800 shadow-sm transition-all">
                <div className="relative size-24 shrink-0 rounded-2xl overflow-hidden bg-gray-50 dark:bg-black/20">
                  <img src={p.coverMedia?.url || p.image} className="w-full h-full object-cover" />
                </div>
                <div className="flex-1 text-center md:text-left">
                  <h4 className="text-xl font-black tracking-tight">{p.name}</h4>
                  <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">{p.category}</p>
                  <p className="text-primary font-black text-lg mt-1">Rp {p.price.toLocaleString('id-ID')}</p>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => { setEditingProduct(p); setIsModalOpen(true); }} className="p-4 bg-gray-50 dark:bg-black/20 rounded-2xl hover:text-blue-500 transition-all"><span className="material-symbols-outlined">edit</span></button>
                  <button onClick={() => { if(confirm('Hapus?')) dbService.deleteProduct(p.id).then(refreshData) }} className="p-4 bg-gray-50 dark:bg-black/20 rounded-2xl hover:text-red-500 transition-all"><span className="material-symbols-outlined">delete</span></button>
                </div>
              </div>
            ))}
          </div>
        ) : activeTab === 'testimonials' ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {testimonials.map(t => (
              <div key={t.id} className="relative group bg-white dark:bg-[#1a2e1a] rounded-3xl border border-gray-100 dark:border-gray-800 overflow-hidden shadow-sm">
                <img src={t.imageUrl} className="w-full aspect-[3/4] object-cover" />
                <div className={`absolute top-4 left-4 size-3 rounded-full ${t.isActive ? 'bg-primary' : 'bg-gray-400'}`} />
                <div className="p-4">
                  <p className="text-xs font-black text-center uppercase tracking-widest mb-4 truncate">{t.customerName || 'No Name'}</p>
                  <div className="flex gap-2">
                    <button onClick={() => toggleTestimonial(t)} className="flex-1 h-10 rounded-xl bg-gray-50 dark:bg-black/20 font-bold text-[10px] uppercase tracking-widest hover:bg-primary/10 transition-colors">
                      {t.isActive ? 'Nonaktifkan' : 'Aktifkan'}
                    </button>
                    <button onClick={() => { if(confirm('Hapus testimoni ini?')) dbService.deleteTestimonial(t.id).then(refreshData) }} className="size-10 flex items-center justify-center rounded-xl bg-red-50 text-red-500 hover:bg-red-500 hover:text-white transition-all">
                      <span className="material-symbols-outlined text-sm">delete</span>
                    </button>
                  </div>
                </div>
              </div>
            ))}
            {testimonials.length === 0 && <p className="col-span-full text-center py-20 text-gray-400 font-bold italic">Belum ada testimoni. Upload screenshot WhatsApp Anda di sini.</p>}
          </div>
        ) : activeTab === 'cs' ? (
          <div className="flex flex-col gap-6">
            <button onClick={() => { setEditingCS({}); setIsModalOpen(true); }} className="bg-dashed border-2 border-dashed border-gray-200 dark:border-gray-800 p-10 rounded-3xl text-center text-gray-400 hover:border-primary hover:text-primary transition-all group">
              <span className="material-symbols-outlined text-4xl mb-2 group-hover:scale-110 transition-transform">person_add</span>
              <p className="font-black uppercase tracking-widest text-sm">Tambah CS Baru</p>
            </button>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {csContacts.map(c => (
                <div key={c.id} className="bg-white dark:bg-[#1a2e1a] p-6 rounded-3xl flex items-center justify-between border border-gray-100 dark:border-gray-800 shadow-sm">
                  <div className="flex items-center gap-4">
                    <div className={`size-12 rounded-full flex items-center justify-center font-black text-lg ${c.isActive ? 'bg-primary text-[#111811]' : 'bg-gray-100 text-gray-400'}`}>{c.name.charAt(0)}</div>
                    <div><h4 className="text-lg font-black tracking-tight">{c.name}</h4><p className="text-gray-400 font-bold text-sm">+{c.phoneNumber}</p></div>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => { setEditingCS(c); setIsModalOpen(true); }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:text-blue-500 transition-all"><span className="material-symbols-outlined text-sm">edit</span></button>
                    <button onClick={() => { if(confirm('Hapus?')) dbService.deleteCSContact(c.id).then(refreshData) }} className="p-3 bg-gray-50 dark:bg-black/20 rounded-xl hover:text-red-500 transition-all"><span className="material-symbols-outlined text-sm">delete</span></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ) : (
          <div className="bg-white dark:bg-[#1a2e1a] p-10 rounded-[40px] border border-gray-100 dark:border-gray-800 shadow-xl max-w-4xl mx-auto">
             <form onSubmit={e => { e.preventDefault(); if(localSettings) { dbService.saveSiteSettings(localSettings).then(() => { refreshData(); alert('Berhasil!'); }); } }} className="flex flex-col gap-10">
               <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                 <div className="flex flex-col gap-2"><label className="text-xs font-black uppercase tracking-widest text-gray-400">Nama Website</label><input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary font-bold" value={localSettings?.siteName || ''} onChange={e => localSettings && setLocalSettings({...localSettings, siteName: e.target.value})} /></div>
                 <div className="flex flex-col gap-2"><label className="text-xs font-black uppercase tracking-widest text-gray-400">Logo</label><div className="relative h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 flex items-center justify-between group overflow-hidden cursor-pointer"><span className="text-xs text-gray-400 font-bold truncate pr-4">{localSettings?.logoUrl || 'Belum ada logo'}</span><span className="material-symbols-outlined text-primary">upload_file</span><input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleSiteFileUpload(e, 'logoUrl')} /></div></div>
                 <div className="flex flex-col gap-2 md:col-span-2"><label className="text-xs font-black uppercase tracking-widest text-gray-400">Gambar Hero</label><div className="relative aspect-video rounded-3xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden group"><img src={localSettings?.heroImage} className="absolute inset-0 w-full h-full object-cover opacity-30 group-hover:opacity-100 transition-opacity" /><span className="relative z-10 material-symbols-outlined text-4xl text-primary">image</span><input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleSiteFileUpload(e, 'heroImage')} /></div></div>
                 <div className="flex flex-col gap-2 md:col-span-2"><label className="text-xs font-black uppercase tracking-widest text-gray-400">Judul Hero</label><textarea className="h-28 border-2 border-gray-100 dark:border-gray-800 rounded-2xl p-6 dark:bg-black/20 outline-none focus:border-primary font-bold resize-none" value={localSettings?.heroTitle} onChange={e => localSettings && setLocalSettings({...localSettings, heroTitle: e.target.value})} /></div>
                 <div className="flex flex-col gap-2 md:col-span-2"><label className="text-xs font-black uppercase tracking-widest text-gray-400">Sub-judul Hero</label><textarea className="h-28 border-2 border-gray-100 dark:border-gray-800 rounded-2xl p-6 dark:bg-black/20 outline-none focus:border-primary font-bold resize-none" value={localSettings?.heroSubtitle} onChange={e => localSettings && setLocalSettings({...localSettings, heroSubtitle: e.target.value})} /></div>
                 <div className="flex flex-col gap-2 md:col-span-2"><label className="text-xs font-black uppercase tracking-widest text-gray-400">Deskripsi Footer</label><textarea className="h-28 border-2 border-gray-100 dark:border-gray-800 rounded-2xl p-6 dark:bg-black/20 outline-none focus:border-primary font-bold resize-none" value={localSettings?.footerDescription} onChange={e => localSettings && setLocalSettings({...localSettings, footerDescription: e.target.value})} /></div>
               </div>
               <button type="submit" disabled={isUploading} className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all disabled:opacity-50">Update Seluruh Situs</button>
             </form>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="relative w-full max-w-4xl bg-white dark:bg-background-dark rounded-[40px] p-8 md:p-12 shadow-2xl overflow-y-auto max-h-[90vh] no-scrollbar">
            <h2 className="text-4xl font-black mb-10 tracking-tighter">
              {activeTab === 'products' ? (editingProduct?.id ? 'Edit Produk' : 'Produk Baru') : activeTab === 'testimonials' ? 'Upload Testimoni' : 'Data CS'}
            </h2>

            {activeTab === 'products' ? (
              <form onSubmit={handleSaveProduct} className="flex flex-col gap-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="flex flex-col gap-2"><label className="text-xs font-black uppercase tracking-widest text-gray-400">Nama</label><input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary font-bold" value={editingProduct?.name || ''} onChange={e => setEditingProduct({ ...editingProduct, name: e.target.value })} /></div>
                  <div className="flex flex-col gap-2"><label className="text-xs font-black uppercase tracking-widest text-gray-400">Kategori</label><input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary font-bold" value={editingProduct?.category || ''} onChange={e => setEditingProduct({ ...editingProduct, category: e.target.value })} /></div>
                  <div className="flex flex-col gap-2 md:col-span-2"><label className="text-xs font-black uppercase tracking-widest text-gray-400">Deskripsi</label><textarea required className="h-32 border-2 border-gray-100 dark:border-gray-800 rounded-2xl p-6 dark:bg-black/20 resize-none outline-none focus:border-primary font-bold" value={editingProduct?.description || ''} onChange={e => setEditingProduct({ ...editingProduct, description: e.target.value })} /></div>
                </div>
                <div className="flex flex-col md:flex-row gap-4">
                  <button type="submit" disabled={isUploading} className="flex-1 h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl hover:scale-[1.02] transition-all disabled:opacity-50">Simpan Produk</button>
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-12 h-16 border-2 border-gray-100 dark:border-gray-800 rounded-2xl font-black text-lg">Batal</button>
                </div>
              </form>
            ) : activeTab === 'testimonials' ? (
              <form onSubmit={handleSaveTestimonial} className="flex flex-col gap-8">
                <div className="flex flex-col gap-2">
                  <label className="text-xs font-black uppercase tracking-widest text-gray-400">Screenshot Bukti Chat WhatsApp</label>
                  <div className="relative aspect-video rounded-3xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden transition-all hover:border-primary group">
                    {editingTestimonial?.imageUrl ? (
                      <img src={editingTestimonial.imageUrl} className="w-full h-full object-cover" />
                    ) : (
                      <div className="text-center p-4">
                        <span className="material-symbols-outlined text-5xl text-gray-200 group-hover:text-primary">add_photo_alternate</span>
                        <p className="text-[10px] text-gray-400 font-black uppercase mt-2">Upload Screenshot</p>
                      </div>
                    )}
                    <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" onChange={handleTestimonialUpload} />
                  </div>
                </div>
                <div className="flex flex-col gap-2">
                  <label className="text-xs font-black uppercase tracking-widest text-gray-400">Nama Customer (Opsional)</label>
                  <input className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary font-bold" value={editingTestimonial?.customerName || ''} onChange={e => setEditingTestimonial({ ...editingTestimonial, customerName: e.target.value })} placeholder="Misal: Bunda Nayla" />
                </div>
                <div className="flex flex-col md:flex-row gap-4 mt-6">
                  <button type="submit" disabled={isUploading || !editingTestimonial?.imageUrl} className="flex-1 h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all disabled:opacity-50">Upload Testimoni</button>
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-10 h-16 border-2 border-gray-100 dark:border-gray-800 rounded-2xl font-black text-lg">Batal</button>
                </div>
              </form>
            ) : (
              <form onSubmit={handleSaveCS} className="flex flex-col gap-8">
                <div className="flex flex-col gap-2">
                  <label className="text-xs font-black uppercase tracking-widest text-gray-400">Nama Admin CS</label>
                  <input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary font-bold" value={editingCS?.name || ''} onChange={e => setEditingCS({ ...editingCS, name: e.target.value })} />
                </div>
                <div className="flex flex-col gap-2">
                  <label className="text-xs font-black uppercase tracking-widest text-gray-400">Nomor WhatsApp (628...)</label>
                  <input required className="h-14 border-2 border-gray-100 dark:border-gray-800 rounded-2xl px-6 dark:bg-black/20 outline-none focus:border-primary font-bold" value={editingCS?.phoneNumber || ''} onChange={e => setEditingCS({ ...editingCS, phoneNumber: e.target.value.replace(/\D/g, '') })} />
                </div>
                <div className="flex flex-col md:flex-row gap-4 mt-6">
                  <button type="submit" className="flex-1 h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all">Simpan CS</button>
                  <button type="button" onClick={() => setIsModalOpen(false)} className="px-10 h-16 border-2 border-gray-100 dark:border-gray-800 rounded-2xl font-black text-lg">Batal</button>
                </div>
              </form>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dbService } from '../../services/dbService';
import { Product, CSContact, Media, Variation, SiteSettings, Testimonial } from '../../types';
import { useStore } from '../../App';

const IK_PUBLIC_KEY = process.env.VITE_IMAGEKIT_PUBLIC_KEY || '';
const IK_URL_ENDPOINT = process.env.VITE_IMAGEKIT_URL_ENDPOINT || '';

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cs' | 'site' | 'testimonials'>('products');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null);
  const [editingCS, setEditingCS] = useState<Partial<CSContact> | null>(null);
  const [editingTestimonial, setEditingTestimonial] = useState<Partial<Testimonial> | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings | null>(null);
  const [isUploading, setIsUploading] = useState(false);

  const navigate = useNavigate();
  const { refreshData, products, csContacts, siteSettings, testimonials } = useStore();

  useEffect(() => {
    const isAuth = localStorage.getItem('lumina_admin_auth');
    if (!isAuth) navigate('/admin/login');
    setLocalSettings(siteSettings);
  }, [navigate, siteSettings]);

  const handleLogout = () => {
    localStorage.removeItem('lumina_admin_auth');
    navigate('/admin/login');
  };

  const uploadToImageKit = async (file: File): Promise<string> => {
    if (!IK_PUBLIC_KEY || !IK_URL_ENDPOINT) {
      alert('Error: Kredensial ImageKit belum diatur (VITE_IMAGEKIT_PUBLIC_KEY & VITE_IMAGEKIT_URL_ENDPOINT).');
      throw new Error('Missing ImageKit Credentials');
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('fileName', file.name);
      formData.append('publicKey', IK_PUBLIC_KEY);
      formData.append('useUniqueFileName', 'true');

      const response = await fetch('https://upload.imagekit.io/api/v1/files/upload', {
        method: 'POST',
        body: formData,
      });

      const result = await response.json();
      if (!response.ok) throw new Error(result.message || 'Unggahan gagal');
      return result.url;
    } catch (error) {
      console.error('IK Upload Error:', error);
      alert('Gagal mengunggah ke ImageKit.');
      throw error;
    } finally {
      setIsUploading(false);
    }
  };

  const handleMediaUpload = async (e: React.ChangeEvent<HTMLInputElement>, isCover: boolean, index?: number) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const url = await uploadToImageKit(file);
      const media: Media = { type: file.type.startsWith('video') ? 'video' : 'image', url };
      if (isCover) setEditingProduct(prev => ({ ...prev, coverMedia: media, image: url }));
      else setEditingProduct(prev => {
        const gallery = [...(prev?.gallery || [])];
        if (index !== undefined) gallery[index] = media;
        else if (gallery.length < 9) gallery.push(media);
        return { ...prev, gallery };
      });
    } catch (err) {}
  };

  const handleTestimonialUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const url = await uploadToImageKit(file);
      setEditingTestimonial(prev => ({ ...prev, imageUrl: url }));
    } catch (err) {}
  };

  const handleSiteFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, field: 'logoUrl' | 'heroImage') => {
    const file = e.target.files?.[0];
    if (!file || !localSettings) return;
    try {
      const url = await uploadToImageKit(file);
      setLocalSettings({ ...localSettings, [field]: url });
    } catch (err) {}
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;
    const product: Product = {
      id: editingProduct.id || Date.now().toString(),
      name: editingProduct.name || '',
      description: editingProduct.description || '',
      price: editingProduct.variations?.[0]?.price || Number(editingProduct.price) || 0,
      category: editingProduct.category || 'General',
      image: editingProduct.coverMedia?.url || editingProduct.image || '',
      coverMedia: editingProduct.coverMedia || { type: 'image', url: '' },
      gallery: editingProduct.gallery || [],
      variations: editingProduct.variations || [],
      isFeatured: !!editingProduct.isFeatured,
      createdAt: editingProduct.createdAt || Date.now()
    };
    await dbService.saveProduct(product);
    refreshData();
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  const handleSaveCS = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingCS) return;
    const contact: CSContact = {
      id: editingCS.id || Date.now().toString(),
      name: editingCS.name || '',
      phoneNumber: editingCS.phoneNumber || '',
      isActive: editingCS.isActive ?? true,
    };
    await dbService.saveCSContact(contact);
    refreshData();
    setIsModalOpen(false);
    setEditingCS(null);
  };

