    e.preventDefault();
    if (!adminCreds.username || !adminCreds.password) return;
    await dbService.saveAdminCredentials(adminCreds);
    alert('Username dan Password berhasil diperbarui! Silakan gunakan kredensial baru saat login berikutnya.');
  };

