        {activeTab === 'products' ? (
          <div className="grid grid-cols-1 gap-4">
            {products.map(p => (
              <div key={p.id} className="bg-white dark:bg-[#1a2e1a] p-4 rounded-3xl flex flex-col md:flex-row items-center gap-6 border border-gray-100 dark:border-gray-800 shadow-sm transition-all">
                <div className="relative size-24 shrink-0 rounded-2xl overflow-hidden bg-gray-50 dark:bg-black/20">
                  <img src={p.coverMedia?.url || p.image} className="w-full h-full object-cover" />
                </div>
                <div className="flex-1 text-center md:text-left">
