/**
 * apiFetch handles communication with your backend/bridge.
 * If NEON_API_URL is not set, it gracefully falls back to localStorage.
 */
async function apiFetch(endpoint: string, options?: RequestInit) {
  if (!NEON_API_URL) return null;

  try {
    const res = await fetch(`${NEON_API_URL}${endpoint}`, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...(NEON_API_KEY ? { 'Authorization': `Bearer ${NEON_API_KEY}` } : {}),
        ...options?.headers
      }
    });

    if (!res.ok) {
      console.warn(`API responded with status: ${res.status}`);
      return null;
    }

    return await res.json();
  } catch (e) {
    console.error('Connection to Neon API failed:', e);
    return null;
  }
}

