export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dbService } from '../../services/dbService';
import { Product, CSContact, Media, Variation, SiteSettings, Testimonial, AdminCredentials } from '../../types';
import { useStore } from '../../App';

// Helper untuk membaca env variable dari Vite/Vercel
const getEnv = (key: string): string => {
  // @ts-ignore
  if (import.meta.env && import.meta.env[key]) return import.meta.env[key];
  // @ts-ignore
  if (typeof process !== 'undefined' && process.env && process.env[key]) return process.env[key];
  return '';
};

const IK_PUBLIC_KEY = getEnv('VITE_IMAGEKIT_PUBLIC_KEY');

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cs' | 'site' | 'testimonials' | 'security'>('products');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null);
  const [editingCS, setEditingCS] = useState<Partial<CSContact> | null>(null);
  const [editingTestimonial, setEditingTestimonial] = useState<Partial<Testimonial> | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings | null>(null);
  const [adminCreds, setAdminCreds] = useState<AdminCredentials>({ username: '', password: '' });
  const [isUploading, setIsUploading] = useState(false);

  // State untuk input manual URL jika upload gagal
  const [manualUrl, setManualUrl] = useState('');

  const navigate = useNavigate();
  const { refreshData, products, csContacts, siteSettings, testimonials } = useStore();

  useEffect(() => {
    const isAuth = localStorage.getItem('lumina_admin_auth');
    if (!isAuth) navigate('/admin/login');
    setLocalSettings(siteSettings);
    dbService.getAdminCredentials().then(setAdminCreds);
  }, [navigate, siteSettings]);

  const handleLogout = () => {
    localStorage.removeItem('lumina_admin_auth');
    navigate('/admin/login');
  };

  const uploadToImageKit = async (file: File): Promise<string> => {
    if (!IK_PUBLIC_KEY) {
      console.error("Public Key tidak ditemukan di environment.");
      alert("Error: VITE_IMAGEKIT_PUBLIC_KEY tidak ditemukan di environment variables.");
      throw new Error('Missing Public Key');
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('fileName', file.name || `upload_${Date.now()}`);
      formData.append('publicKey', IK_PUBLIC_KEY);
      formData.append('useUniqueFileName', 'true');

      const response = await fetch('https://upload.imagekit.io/api/v1/files/upload', {
        method: 'POST',
        body: formData,
      });

      const result = await response.json();

      if (!response.ok) {
        const errorMsg = result.message || 'Gagal mengunggah';
        console.error('ImageKit Error Detail:', result);

        if (errorMsg.includes('authorization') || errorMsg.includes('signature')) {
          alert('GAGAL: ImageKit menolak upload tanpa tanda tangan (unsigned).\n\nSOLUSI:\n1. Di Dashboard ImageKit, pergi ke Developer Options -> API Keys.\n2. Cari bagian "Upload Policy".\n3. Aktifkan/Centang "Allow Unsigned Upload".\n\nAtau gunakan fitur "Input Manual URL" di bawah tombol upload.');
        } else {
          alert(`Error ImageKit: ${errorMsg}`);
        }
        throw new Error(errorMsg);
      }

      return result.url;
    } catch (error: any) {
      console.error('Upload catch error:', error);
      throw error;
    } finally {
      setIsUploading(false);
    }
  };

  const handleMediaUpload = async (e: React.ChangeEvent<HTMLInputElement>, isCover: boolean, index?: number) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const url = await uploadToImageKit(file);
      applyMediaUrl(url, isCover, index, file.type.startsWith('video') ? 'video' : 'image');
    } catch (err) {}
  };

  const applyMediaUrl = (url: string, isCover: boolean, index?: number, type: 'image' | 'video' = 'image') => {
    const media: Media = { type, url };
    if (isCover) {
      setEditingProduct(prev => ({ ...prev, coverMedia: media, image: url }));
    } else {
      setEditingProduct(prev => {
        const gallery = [...(prev?.gallery || [])];
        if (index !== undefined) gallery[index] = media;
