        ) : activeTab === 'cs' ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
             <button onClick={() => { setEditingCS({ isActive: true }); setIsModalOpen(true); }} className="p-8 border-2 border-dashed border-gray-200 dark:border-gray-800 rounded-3xl text-gray-400 hover:border-primary hover:text-primary transition-all flex flex-col items-center justify-center">
               <span className="material-symbols-outlined text-4xl">person_add</span>
