                    <div className="md:col-span-2 flex flex-col gap-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Alamat Fisik</label><input className="h-12 border-2 rounded-xl px-4 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 outline-none focus:border-primary font-bold" value={localSettings?.contactAddress} onChange={e => localSettings && setLocalSettings({...localSettings, contactAddress: e.target.value})} /></div>
                    <div className="flex flex-col gap-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Instagram URL</label><input className="h-12 border-2 rounded-xl px-4 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 outline-none focus:border-primary font-bold" value={localSettings?.instagramUrl} onChange={e => localSettings && setLocalSettings({...localSettings, instagramUrl: e.target.value})} /></div>
                    <div className="flex flex-col gap-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">TikTok URL</label><input className="h-12 border-2 rounded-xl px-4 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 outline-none focus:border-primary font-bold" value={localSettings?.tiktokUrl} onChange={e => localSettings && setLocalSettings({...localSettings, tiktokUrl: e.target.value})} /></div>
                  </div>
                </div>

                <button className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-lg shadow-xl shadow-primary/20 hover:scale-[1.01] transition-all">Simpan Semua Pengaturan</button>
             </form>
          </div>
        )}
      </div>

      {/* MODAL FORM */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="relative w-full max-w-4xl bg-white dark:bg-background-dark rounded-[40px] p-8 md:p-12 shadow-2xl overflow-y-auto max-h-[90vh] no-scrollbar">
             <div className="flex justify-between items-center mb-10">
               <h2 className="text-4xl font-black tracking-tighter">
                 {activeTab === 'products' ? (editingProduct?.id ? 'Edit Produk' : 'Produk Baru') : 'Formulir Data'}
               </h2>
               <button onClick={() => setIsModalOpen(false)} className="p-4 rounded-full bg-gray-50 dark:bg-black/20 hover:bg-gray-100 transition-colors"><span className="material-symbols-outlined">close</span></button>
             </div>

             {activeTab === 'products' ? (
               <form onSubmit={handleSaveProduct} className="flex flex-col gap-10">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="flex flex-col gap-2"><label className="text-xs font-black text-gray-400 uppercase tracking-widest">Nama Produk</label><input required className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={editingProduct?.name || ''} onChange={e => setEditingProduct({ ...editingProduct, name: e.target.value })} /></div>
                   <div className="flex flex-col gap-2"><label className="text-xs font-black text-gray-400 uppercase tracking-widest">Kategori</label><input required className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={editingProduct?.category || ''} onChange={e => setEditingProduct({ ...editingProduct, category: e.target.value })} /></div>
                   <div className="flex flex-col gap-2 md:col-span-2"><label className="text-xs font-black text-gray-400 uppercase tracking-widest">Deskripsi Produk</label><textarea required className="h-32 border-2 rounded-2xl p-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 resize-none focus:border-primary outline-none font-bold" value={editingProduct?.description || ''} onChange={e => setEditingProduct({ ...editingProduct, description: e.target.value })} /></div>

                   {/* COVER PHOTO SECTION */}
                   <div className="flex flex-col gap-4 border-2 border-gray-100 dark:border-gray-800 p-6 rounded-3xl bg-gray-50/50 dark:bg-black/10">
                     <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Foto Utama (Cover)</label>
                     <div className="relative aspect-video rounded-2xl bg-white dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden">
                       {editingProduct?.coverMedia?.url || editingProduct?.image ? (
                         <img src={editingProduct.coverMedia?.url || editingProduct.image} className="absolute inset-0 w-full h-full object-contain" />
                       ) : <span className="material-symbols-outlined text-4xl text-gray-200">add_photo_alternate</span>}
                       <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" onChange={async (e) => {
                         const file = e.target.files?.[0];
                         if(file) {
                           try {
                             const url = await uploadToImageKit(file);
                             applyMediaUrl(url, true);
                           } catch(e) {}
                         }
                       }} disabled={isUploading} />
                       {isUploading && <div className="absolute inset-0 bg-black/20 backdrop-blur-sm flex items-center justify-center text-white font-black">Mengunggah...</div>}
                     </div>
                     <div className="flex gap-2">
                        <input className="flex-1 h-10 border rounded-xl px-4 text-xs font-bold bg-white dark:bg-black/30 outline-none focus:border-primary transition-colors" placeholder="Atau paste URL gambar manual..." value={manualUrl} onChange={e => setManualUrl(e.target.value)} />
                        <button type="button" onClick={() => { if(manualUrl) applyMediaUrl(manualUrl, true); }} className="px-4 bg-black text-white dark:bg-white dark:text-black rounded-xl text-[10px] font-black uppercase">Pakai URL</button>
                     </div>
                   </div>

                   {/* GALLERY SECTION */}
                   <div className="flex flex-col gap-4 border-2 border-gray-100 dark:border-gray-800 p-6 rounded-3xl bg-gray-50/50 dark:bg-black/10">
                     <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Galeri Tambahan (Maks 9)</label>
                     <div className="grid grid-cols-3 gap-3">
                        {(editingProduct?.gallery || []).map((m, idx) => (
                          <div key={idx} className="relative aspect-square rounded-xl bg-white dark:bg-black/20 overflow-hidden group">
                            <img src={m.url} className="w-full h-full object-cover" />
                            <button type="button" onClick={() => {
                               setEditingProduct(prev => ({...prev, gallery: prev?.gallery?.filter((_, i) => i !== idx)}));
                            }} className="absolute top-1 right-1 size-6 bg-red-500 text-white rounded-full flex items-center justify-center shadow-lg"><span className="material-symbols-outlined text-sm">close</span></button>
                          </div>
                        ))}
                        {(editingProduct?.gallery?.length || 0) < 9 && (
                          <div className="relative aspect-square rounded-xl border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center hover:border-primary cursor-pointer transition-colors">
                            <span className="material-symbols-outlined">add</span>
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" onChange={async (e) => {
                               const file = e.target.files?.[0];
                               if(file) {
                                 try {
                                   const url = await uploadToImageKit(file);
                                   applyMediaUrl(url, false);
                                 } catch(e) {}
                               }
                            }} disabled={isUploading} />
                          </div>
                        )}
                     </div>
                     <div className="flex gap-2">
                        <input className="flex-1 h-10 border rounded-xl px-4 text-xs font-bold bg-white dark:bg-black/30 outline-none focus:border-primary" placeholder="Paste URL manual untuk galeri..." value={manualUrl} onChange={e => setManualUrl(e.target.value)} />
                        <button type="button" onClick={() => { if(manualUrl) applyMediaUrl(manualUrl, false); }} className="px-4 bg-black text-white dark:bg-white dark:text-black rounded-xl text-[10px] font-black uppercase">Tambah URL</button>
                     </div>
                   </div>

                   {/* VARIATIONS SECTION */}
                   <div className="flex flex-col gap-4 md:col-span-2">
                     <div className="flex items-center justify-between">
                       <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Variasi & Harga</label>
                       <button type="button" onClick={() => setEditingProduct(p => ({...p, variations: [...(p?.variations || []), { id: Date.now().toString(), name: '', price: 0, stock: 10 }]}))} className="text-primary font-black text-xs uppercase flex items-center gap-1 hover:underline"><span className="material-symbols-outlined text-sm">add</span> Tambah Variasi</button>
                     </div>
                     <div className="space-y-3">
                       {editingProduct?.variations?.map((v, idx) => (
                         <div key={v.id} className="grid grid-cols-1 md:grid-cols-4 gap-3 bg-gray-50 dark:bg-black/20 p-4 rounded-2xl items-center border border-gray-100 dark:border-gray-800">
                           <input placeholder="Nama (Contoh: XL)" className="bg-white dark:bg-black/20 border-none rounded-xl h-10 px-4 font-bold text-sm" value={v.name} onChange={e => setEditingProduct(p => ({...p, variations: p?.variations?.map(it => it.id === v.id ? {...it, name: e.target.value} : it)}))} />
                           <input type="number" placeholder="Harga" className="bg-white dark:bg-black/20 border-none rounded-xl h-10 px-4 font-bold text-sm" value={v.price} onChange={e => setEditingProduct(p => ({...p, variations: p?.variations?.map(it => it.id === v.id ? {...it, price: Number(e.target.value)} : it)}))} />
                           <input type="number" placeholder="Stok" className="bg-white dark:bg-black/20 border-none rounded-xl h-10 px-4 font-bold text-sm" value={v.stock} onChange={e => setEditingProduct(p => ({...p, variations: p?.variations?.map(it => it.id === v.id ? {...it, stock: Number(e.target.value)} : it)}))} />
                           <button type="button" onClick={() => setEditingProduct(p => ({...p, variations: p?.variations?.filter(it => it.id !== v.id)}))} className="text-red-500 hover:text-red-700 font-bold text-[10px] uppercase">Hapus</button>
                         </div>
                       ))}
                       {(!editingProduct?.variations || editingProduct.variations.length === 0) && (
                          <p className="text-center text-[10px] text-gray-400 font-bold py-2 italic border-2 border-dashed border-gray-100 rounded-xl">Minimal harus ada 1 variasi/harga</p>
                       )}
                     </div>
                   </div>

                   <label className="flex items-center gap-3 cursor-pointer">
                     <input type="checkbox" checked={editingProduct?.isFeatured} onChange={e => setEditingProduct({...editingProduct, isFeatured: e.target.checked})} className="size-6 rounded-lg text-primary focus:ring-primary border-gray-200 dark:border-gray-800" />
                     <span className="font-black text-sm uppercase tracking-widest">Tampilkan di Halaman Utama</span>
                   </label>
                 </div>
                 <button type="submit" disabled={isUploading} className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all disabled:opacity-50">Simpan Produk Sekarang</button>
               </form>
             ) : activeTab === 'cs' ? (
               <form onSubmit={e => {
                 e.preventDefault();
                 if(editingCS) dbService.saveCSContact(editingCS as CSContact).then(() => { refreshData(); setIsModalOpen(false); });
               }} className="flex flex-col gap-6">
                  <div className="flex flex-col gap-2">
                    <label className="text-[10px] font-black uppercase text-gray-400">Nama Lengkap CS</label>
                    <input required placeholder="Contoh: Admin Susi" className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={editingCS?.name || ''} onChange={e => setEditingCS({ ...editingCS, name: e.target.value })} />
                  </div>
                  <div className="flex flex-col gap-2">
                    <label className="text-[10px] font-black uppercase text-gray-400">Nomor WhatsApp (Format: 628123xxx)</label>
                    <input required placeholder="628123456789" className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={editingCS?.phoneNumber || ''} onChange={e => setEditingCS({ ...editingCS, phoneNumber: e.target.value })} />
                  </div>
                  <label className="flex items-center gap-3 cursor-pointer mt-2">
                    <input type="checkbox" checked={editingCS?.isActive} onChange={e => setEditingCS({...editingCS, isActive: e.target.checked})} className="size-6 rounded-lg text-primary focus:ring-primary border-gray-200 dark:border-gray-800" />
                    <span className="font-black text-sm uppercase tracking-widest">Kontak Aktif</span>
                  </label>
                  <button className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-lg shadow-xl shadow-primary/20">Simpan Kontak CS</button>
               </form>
             ) : (
               <form onSubmit={e => {
                 e.preventDefault();
                 if(editingTestimonial) dbService.saveTestimonial(editingTestimonial as Testimonial).then(() => { refreshData(); setIsModalOpen(false); });
               }} className="flex flex-col gap-6">
                 <div className="flex flex-col gap-4">
                    <label className="text-[10px] font-black uppercase text-gray-400 text-center">Foto Testimoni / Review Pelanggan</label>
                    <div className="relative aspect-square max-w-sm mx-auto rounded-3xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden group">
                        {editingTestimonial?.imageUrl ? <img src={editingTestimonial.imageUrl} className="w-full h-full object-cover" /> : <span className="material-symbols-outlined text-4xl">add_photo_alternate</span>}
                        <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" onChange={async (e) => {
                          const file = e.target.files?.[0];
                          if(file) {
                            try {
                              const url = await uploadToImageKit(file);
                              setEditingTestimonial({...editingTestimonial, imageUrl: url});
                            } catch(e) {}
                          }
                        }} />
                    </div>
                    <div className="flex gap-2 max-w-sm mx-auto w-full">
                        <input className="flex-1 h-10 border rounded-xl px-4 text-xs font-bold bg-white dark:bg-black/30 outline-none focus:border-primary" placeholder="Atau paste URL gambar..." value={manualUrl} onChange={e => setManualUrl(e.target.value)} />
                        <button type="button" onClick={() => { if(manualUrl) setEditingTestimonial({...editingTestimonial, imageUrl: manualUrl}); setManualUrl(''); }} className="px-4 bg-black text-white dark:bg-white dark:text-black rounded-xl text-[10px] font-black uppercase">Pakai</button>
                    </div>
                 </div>
                 <div className="flex flex-col gap-2">
                    <label className="text-[10px] font-black uppercase text-gray-400">Nama Pelanggan (Opsional)</label>
                    <input placeholder="Contoh: Bpk. Budi - Jakarta" className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={editingTestimonial?.customerName || ''} onChange={e => setEditingTestimonial({ ...editingTestimonial, customerName: e.target.value })} />
                 </div>
                 <button className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-lg shadow-xl shadow-primary/20">Simpan Testimoni</button>
               </form>
             )}
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dbService } from '../../services/dbService';
import { Product, CSContact, Media, Variation, SiteSettings, Testimonial, AdminCredentials } from '../../types';
import { useStore } from '../../App';

const getEnv = (key: string): string => {
  // @ts-ignore
  if (import.meta.env && import.meta.env[key]) return import.meta.env[key];
  // @ts-ignore
  if (typeof process !== 'undefined' && process.env && process.env[key]) return process.env[key];
  return '';
};

const IK_PUBLIC_KEY = getEnv('VITE_IMAGEKIT_PUBLIC_KEY');

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cs' | 'site' | 'testimonials' | 'security'>('products');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null);
  const [editingCS, setEditingCS] = useState<Partial<CSContact> | null>(null);
  const [editingTestimonial, setEditingTestimonial] = useState<Partial<Testimonial> | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings | null>(null);
  const [adminCreds, setAdminCreds] = useState<AdminCredentials>({ username: '', password: '' });
  const [isUploading, setIsUploading] = useState(false);
  const [showIKHelp, setShowIKHelp] = useState(false);

  const [manualUrl, setManualUrl] = useState('');

  const navigate = useNavigate();
  const { refreshData, products, csContacts, siteSettings, testimonials } = useStore();

  useEffect(() => {
    const isAuth = localStorage.getItem('lumina_admin_auth');
    if (!isAuth) navigate('/admin/login');
    setLocalSettings(siteSettings);
    dbService.getAdminCredentials().then(setAdminCreds);
  }, [navigate, siteSettings]);

  const handleLogout = () => {
    localStorage.removeItem('lumina_admin_auth');
    navigate('/admin/login');
  };

  const uploadToImageKit = async (file: File): Promise<string> => {
    if (!IK_PUBLIC_KEY) {
      alert("Public Key ImageKit belum diisi di environment variable.");
      throw new Error('Missing Public Key');
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('fileName', file.name || `upload_${Date.now()}`);
      formData.append('publicKey', IK_PUBLIC_KEY);
      formData.append('useUniqueFileName', 'true');

      const response = await fetch('https://upload.imagekit.io/api/v1/files/upload', {
        method: 'POST',
        body: formData,
      });

      const result = await response.json();

      if (!response.ok) {
        const errorMsg = result.message || 'Gagal mengunggah';
        alert(`Gagal Upload: ${errorMsg}\n\nTips: Jika muncul error "Authorization", pastikan fitur "Unsigned Upload" sudah aktif di Dashboard ImageKit.`);
        throw new Error(errorMsg);
      }

      return result.url;
    } catch (error) {
      console.error(error);
      throw error;
    } finally {
      setIsUploading(false);
    }
  };

  const applyMediaUrl = (url: string, isCover: boolean, index?: number) => {
    if (!url) return;
    const media: Media = { type: 'image', url };
    if (isCover) {
      setEditingProduct(prev => ({ ...prev, coverMedia: media, image: url }));
    } else {
      setEditingProduct(prev => {
        const gallery = [...(prev?.gallery || [])];
        if (index !== undefined) gallery[index] = media;
        else gallery.push(media);
        return { ...prev, gallery };
      });
    }
    setManualUrl('');
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;
    const basePrice = editingProduct.variations?.[0]?.price || Number(editingProduct.price) || 0;
    const product: Product = {
      id: editingProduct.id || Date.now().toString(),
      name: editingProduct.name || '',
      description: editingProduct.description || '',
      price: basePrice,
      category: editingProduct.category || 'Umum',
      image: editingProduct.coverMedia?.url || editingProduct.image || '',
      coverMedia: editingProduct.coverMedia || { type: 'image', url: '' },
      gallery: editingProduct.gallery || [],
      variations: editingProduct.variations || [],
      isFeatured: !!editingProduct.isFeatured,
      createdAt: editingProduct.createdAt || Date.now()
    };
    await dbService.saveProduct(product);
    refreshData();
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  return (
    <div className="px-4 md:px-10 lg:px-40 py-10 min-h-screen">
      <div className="max-w-[1200px] mx-auto">
        <div className="flex flex-col md:flex-row items-center justify-between mb-10 gap-6">
          <div>
            <h1 className="text-4xl font-black tracking-tighter">Admin Panel</h1>
            <p className="text-gray-400 mt-1 font-medium uppercase text-xs tracking-widest">Manajemen Konten & Produk</p>
          </div>
          <div className="flex gap-4">
            <button 
              onClick={() => setShowIKHelp(!showIKHelp)}
              className="h-12 px-5 border border-primary/30 text-primary rounded-xl font-bold flex items-center gap-2 hover:bg-primary/5 transition-all"
            >
              <span className="material-symbols-outlined text-xl">help</span> Bantuan Upload
            </button>
            <button onClick={handleLogout} className="h-12 px-6 border border-gray-200 dark:border-gray-800 rounded-xl font-bold hover:bg-red-50 hover:text-red-500 transition-all">Logout</button>
          </div>
        </div>

        {/* Bantuan Troubleshooting UI */}
        {showIKHelp && (
          <div className="mb-10 p-8 bg-primary/10 border-2 border-primary/20 rounded-[32px] animate-in fade-in slide-in-from-top-4 duration-500">
            <h3 className="text-xl font-black mb-4 flex items-center gap-2">
              <span className="material-symbols-outlined">lightbulb</span> Masalah Upload ImageKit?
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 text-sm">
              <div className="space-y-3">
                <p className="font-bold">1. Cara Aktifkan di ImageKit:</p>
                <ul className="list-disc pl-5 space-y-1 text-gray-600 dark:text-gray-400">
                  <li>Klik <b>Settings</b> (Ikon Gerigi).</li>
                  <li>Klik <b>Images</b> (Pilihan paling atas).</li>
                  <li>Cari bagian <b>Upload</b> dan aktifkan <b>"Allow Unsigned Upload"</b>.</li>
                </ul>
              </div>
              <div className="space-y-3">
                <p className="font-bold">2. Solusi Alternatif (URL Manual):</p>
                <p className="text-gray-600 dark:text-gray-400">
                  Jika tetap gagal, gunakan situs seperti <b>PostImg.cc</b> atau <b>ImgBB.com</b>. Unggah foto di sana, salin "Direct Link", lalu tempel di kolom <b>"Link Gambar Manual"</b> yang tersedia di setiap form aplikasi ini.
                </p>
              </div>
            </div>
          </div>
        )}

        <div className="flex border-b border-gray-200 dark:border-gray-800 mb-8 overflow-x-auto no-scrollbar">
          {['products', 'testimonials', 'cs', 'site', 'security'].map(tab => (
            <button key={tab} className={`px-8 py-4 font-black text-sm uppercase tracking-widest whitespace-nowrap transition-all ${activeTab === tab ? 'border-b-4 border-primary text-primary' : 'text-gray-400 hover:text-gray-600'}`} onClick={() => setActiveTab(tab as any)}>
              {tab === 'products' ? 'Produk' : tab === 'testimonials' ? 'Testimoni' : tab === 'cs' ? 'Kontak CS' : tab === 'site' ? 'Situs' : 'Keamanan'}
            </button>
          ))}
        </div>

        {activeTab === 'products' ? (
          <div className="grid grid-cols-1 gap-4">
            <button onClick={() => { setEditingProduct({ gallery: [], variations: [], isFeatured: false }); setIsModalOpen(true); }} className="p-8 border-2 border-dashed border-gray-200 dark:border-gray-800 rounded-3xl text-gray-400 hover:border-primary hover:text-primary transition-all flex flex-col items-center justify-center mb-4">
               <span className="material-symbols-outlined text-4xl">add_circle</span>
               <p className="font-black mt-2 uppercase text-xs tracking-widest">Tambah Produk Baru</p>
            </button>
            {products.map(p => (
              <div key={p.id} className="bg-white dark:bg-[#1a2e1a] p-5 rounded-3xl flex flex-col md:flex-row items-center gap-6 border border-gray-100 dark:border-gray-800 shadow-sm">
                <img src={p.coverMedia?.url || p.image} className="size-24 shrink-0 rounded-2xl object-cover bg-gray-50 dark:bg-black/20" />
                <div className="flex-1">
                  <h4 className="text-xl font-black">{p.name}</h4>
                  <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">{p.category}</p>
                  <p className="text-primary font-black text-lg mt-1">Rp {p.price.toLocaleString('id-ID')}</p>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => { setEditingProduct(p); setIsModalOpen(true); }} className="p-4 bg-gray-50 dark:bg-black/20 rounded-2xl hover:text-primary transition-all"><span className="material-symbols-outlined">edit</span></button>
