             <form onSubmit={e => { e.preventDefault(); if(localSettings) dbService.saveSiteSettings(localSettings).then(() => { refreshData(); alert('Pengaturan situs diperbarui!'); }); }} className="flex flex-col gap-10">
                <div className="space-y-8">
                  <h3 className="text-xl font-black border-b border-gray-100 dark:border-gray-800 pb-4">Brand & Hero Banner</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="flex flex-col gap-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nama Toko</label><input className="h-12 border-2 rounded-xl px-4 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 outline-none focus:border-primary font-bold" value={localSettings?.siteName} onChange={e => localSettings && setLocalSettings({...localSettings, siteName: e.target.value})} /></div>
                    <div className="flex flex-col gap-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Link Logo Manual</label><input className="h-12 border-2 rounded-xl px-4 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 outline-none focus:border-primary font-bold" value={localSettings?.logoUrl} onChange={e => localSettings && setLocalSettings({...localSettings, logoUrl: e.target.value})} placeholder="https://..." /></div>
                    <div className="md:col-span-2 flex flex-col gap-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Link Banner Hero Manual</label><input className="h-12 border-2 rounded-xl px-4 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 outline-none focus:border-primary font-bold" value={localSettings?.heroImage} onChange={e => localSettings && setLocalSettings({...localSettings, heroImage: e.target.value})} placeholder="https://..." /></div>
                    <div className="md:col-span-2 flex flex-col gap-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Judul Banner (Besar)</label><textarea className="h-24 border-2 rounded-xl p-4 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 outline-none focus:border-primary font-bold resize-none" value={localSettings?.heroTitle} onChange={e => localSettings && setLocalSettings({...localSettings, heroTitle: e.target.value})} /></div>
                  </div>
