             </button>
             {csContacts.map(c => (
               <div key={c.id} className="bg-white dark:bg-[#1a2e1a] p-6 rounded-3xl flex items-center justify-between border border-gray-100 dark:border-gray-800">
                 <div>
                   <h4 className="font-black text-lg">{c.name}</h4>
                   <p className="text-gray-400 font-bold">+{c.phoneNumber}</p>
                 </div>
                 <div className="flex gap-2">
                    <button onClick={() => { setEditingCS(c); setIsModalOpen(true); }} className="p-3 hover:text-primary transition-colors"><span className="material-symbols-outlined">edit</span></button>
                    <button onClick={() => { if(confirm('Hapus kontak CS ini?')) dbService.deleteCSContact(c.id).then(refreshData) }} className="p-3 hover:text-red-500 transition-colors"><span className="material-symbols-outlined">delete</span></button>
