                            <span className="material-symbols-outlined">add</span>
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" onChange={async (e) => {
                               const file = e.target.files?.[0];
                               if(file) {
                                 try {
                                   const url = await uploadToImageKit(file);
                                   applyMediaUrl(url, false);
                                 } catch(e) {}
                               }
                            }} disabled={isUploading} />
                          </div>
                        )}
                     </div>
                     <div className="flex gap-2">
                        <input className="flex-1 h-10 border rounded-xl px-4 text-xs font-bold bg-white dark:bg-black/30 outline-none focus:border-primary" placeholder="Link Manual untuk Galeri..." value={manualUrl} onChange={e => setManualUrl(e.target.value)} />
