                       <label className="text-xs font-black text-gray-400 uppercase tracking-widest">Variasi & Harga</label>
                       <button type="button" onClick={() => setEditingProduct(p => ({...p, variations: [...(p?.variations || []), { id: Date.now().toString(), name: '', price: 0, stock: 10 }]}))} className="text-primary font-black text-xs uppercase flex items-center gap-1 hover:underline"><span className="material-symbols-outlined text-sm">add</span> Tambah Variasi</button>
                     </div>
                     <div className="space-y-3">
                       {editingProduct?.variations?.map((v) => (
                         <div key={v.id} className="grid grid-cols-1 md:grid-cols-4 gap-3 bg-gray-50 dark:bg-black/20 p-4 rounded-2xl items-center border border-gray-100 dark:border-gray-800">
                           <input placeholder="Nama (Contoh: XL)" className="bg-white dark:bg-black/20 border-none rounded-xl h-10 px-4 font-bold text-sm" value={v.name} onChange={e => setEditingProduct(p => ({...p, variations: p?.variations?.map(it => it.id === v.id ? {...it, name: e.target.value} : it)}))} />
                           <input type="number" placeholder="Harga" className="bg-white dark:bg-black/20 border-none rounded-xl h-10 px-4 font-bold text-sm" value={v.price} onChange={e => setEditingProduct(p => ({...p, variations: p?.variations?.map(it => it.id === v.id ? {...it, price: Number(e.target.value)} : it)}))} />
                           <input type="number" placeholder="Stok" className="bg-white dark:bg-black/20 border-none rounded-xl h-10 px-4 font-bold text-sm" value={v.stock} onChange={e => setEditingProduct(p => ({...p, variations: p?.variations?.map(it => it.id === v.id ? {...it, stock: Number(e.target.value)} : it)}))} />
                           <button type="button" onClick={() => setEditingProduct(p => ({...p, variations: p?.variations?.filter(it => it.id !== v.id)}))} className="text-red-500 hover:text-red-700 font-bold text-[10px] uppercase">Hapus</button>
                         </div>
                       ))}
                       {(!editingProduct?.variations || editingProduct.variations.length === 0) && (
                          <p className="text-center text-[10px] text-gray-400 font-bold py-2 italic">Minimal harus ada 1 variasi harga.</p>
                       )}
                     </div>
                   </div>

                   <label className="flex items-center gap-3 cursor-pointer">
                     <input type="checkbox" checked={editingProduct?.isFeatured} onChange={e => setEditingProduct({...editingProduct, isFeatured: e.target.checked})} className="size-6 rounded-lg text-primary focus:ring-primary border-gray-200 dark:border-gray-800" />
                     <span className="font-black text-sm uppercase tracking-widest">Tampilkan di Beranda</span>
                   </label>
                 </div>
                 <button type="submit" disabled={isUploading} className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-2xl shadow-primary/30 hover:scale-[1.02] transition-all disabled:opacity-50">Simpan Produk Sekarang</button>
               </form>
             ) : activeTab === 'cs' ? (
               <form onSubmit={e => {
                 e.preventDefault();
                 if(editingCS) dbService.saveCSContact(editingCS as CSContact).then(() => { refreshData(); setIsModalOpen(false); });
               }} className="flex flex-col gap-6">
                  <input required placeholder="Nama CS (Contoh: Admin Susi)" className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={editingCS?.name || ''} onChange={e => setEditingCS({ ...editingCS, name: e.target.value })} />
                  <input required placeholder="Nomor WhatsApp (628...)" className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={editingCS?.phoneNumber || ''} onChange={e => setEditingCS({ ...editingCS, phoneNumber: e.target.value })} />
                  <button className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-lg shadow-xl shadow-primary/20">Simpan Kontak CS</button>
               </form>
             ) : (
               <form onSubmit={e => {
                 e.preventDefault();
                 if(editingTestimonial) dbService.saveTestimonial(editingTestimonial as Testimonial).then(() => { refreshData(); setIsModalOpen(false); });
               }} className="flex flex-col gap-6">
                 <div className="flex flex-col gap-4">
                    <div className="relative aspect-square max-w-sm mx-auto rounded-3xl bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden">
                        {editingTestimonial?.imageUrl ? <img src={editingTestimonial.imageUrl} className="w-full h-full object-cover" /> : <span className="material-symbols-outlined text-4xl">add_photo_alternate</span>}
