import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dbService } from '../../services/dbService';
import { Product, CSContact, Media, Variation, SiteSettings, Testimonial, AdminCredentials } from '../../types';
import { useStore } from '../../App';

const getEnv = (key: string): string => {
  // @ts-ignore
  if (import.meta.env && import.meta.env[key]) return import.meta.env[key];
  // @ts-ignore
  if (typeof process !== 'undefined' && process.env && process.env[key]) return process.env[key];
  return '';
};

const IK_PUBLIC_KEY = getEnv('VITE_IMAGEKIT_PUBLIC_KEY');

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cs' | 'site' | 'testimonials' | 'security'>('products');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null);
  const [editingCS, setEditingCS] = useState<Partial<CSContact> | null>(null);
  const [editingTestimonial, setEditingTestimonial] = useState<Partial<Testimonial> | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings | null>(null);
  const [adminCreds, setAdminCreds] = useState<AdminCredentials>({ username: '', password: '' });
  const [isUploading, setIsUploading] = useState(false);
  const [showTroubleshoot, setShowTroubleshoot] = useState(false);

  const [manualUrl, setManualUrl] = useState('');

  const navigate = useNavigate();
  const { refreshData, products, csContacts, siteSettings, testimonials } = useStore();

  useEffect(() => {
    const isAuth = localStorage.getItem('lumina_admin_auth');
    if (!isAuth) navigate('/admin/login');
    setLocalSettings(siteSettings);
    dbService.getAdminCredentials().then(setAdminCreds);
  }, [navigate, siteSettings]);

  const handleLogout = () => {
    localStorage.removeItem('lumina_admin_auth');
    navigate('/admin/login');
  };

  const uploadToImageKit = async (file: File): Promise<string> => {
    if (!IK_PUBLIC_KEY) {
      alert("Public Key ImageKit belum terpasang. Gunakan Link Manual.");
      throw new Error('Missing Public Key');
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('fileName', file.name || `upload_${Date.now()}`);
      formData.append('publicKey', IK_PUBLIC_KEY);
      formData.append('useUniqueFileName', 'true');

      const response = await fetch('https://upload.imagekit.io/api/v1/files/upload', {
        method: 'POST',
        body: formData,
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.message || 'Gagal');
      }

      return result.url;
    } catch (error: any) {
      alert(`Gagal: ${error.message}\n\nPastikan "Unsigned Upload" sudah ENABLED di ImageKit.`);
      throw error;
    } finally {
      setIsUploading(false);
    }
  };

  const applyMediaUrl = (url: string, isCover: boolean, index?: number) => {
    if (!url) return;
    const media: Media = { type: 'image', url };
    if (isCover) {
      setEditingProduct(prev => ({ ...prev, coverMedia: media, image: url }));
    } else {
      setEditingProduct(prev => {
        const gallery = [...(prev?.gallery || [])];
        if (index !== undefined) gallery[index] = media;
        else gallery.push(media);
        return { ...prev, gallery };
      });
    }
    setManualUrl('');
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;
    const product: Product = {
      id: editingProduct.id || Date.now().toString(),
      name: editingProduct.name || '',
      description: editingProduct.description || '',
      price: editingProduct.variations?.[0]?.price || Number(editingProduct.price) || 0,
      category: editingProduct.category || 'Umum',
      image: editingProduct.coverMedia?.url || editingProduct.image || '',
      coverMedia: editingProduct.coverMedia || { type: 'image', url: '' },
      gallery: editingProduct.gallery || [],
      variations: editingProduct.variations || [],
      isFeatured: !!editingProduct.isFeatured,
      createdAt: editingProduct.createdAt || Date.now()
    };
    await dbService.saveProduct(product);
    refreshData();
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  return (
    <div className="px-4 md:px-10 lg:px-40 py-10 min-h-screen">
      <div className="max-w-[1200px] mx-auto">
        <div className="flex flex-col md:flex-row items-center justify-between mb-10 gap-6">
          <div>
            <h1 className="text-4xl font-black tracking-tighter">Admin Dashboard</h1>
            <p className="text-gray-400 font-bold uppercase text-[10px] tracking-[0.2em] mt-1">LuminaGoods Management</p>
          </div>
          <div className="flex gap-3">
            <button onClick={() => setShowTroubleshoot(!showTroubleshoot)} className="h-12 px-5 bg-primary/10 text-primary rounded-2xl font-black text-xs flex items-center gap-2 border border-primary/20 hover:bg-primary/20 transition-all shadow-lg shadow-primary/5">
              <span className="material-symbols-outlined text-lg">videocam</span> Panduan Video
            </button>
            <button onClick={handleLogout} className="h-12 px-6 border-2 border-gray-100 dark:border-gray-800 rounded-2xl font-black text-xs hover:bg-red-500 hover:text-white transition-all">LOGOUT</button>
          </div>
        </div>

        {showTroubleshoot && (
          <div className="mb-10 bg-white dark:bg-[#1a2e1a] border-2 border-primary/30 rounded-[32px] p-8 shadow-xl animate-in slide-in-from-top-4 duration-300">
            <h3 className="text-xl font-black mb-6 flex items-center gap-2 text-primary">
              <span className="material-symbols-outlined">settings_suggest</span> Langkah Aktifkan Upload (Berdasarkan Video)
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-10 text-sm leading-relaxed">
              <div className="space-y-4">
                <p className="font-black text-gray-400 uppercase tracking-widest text-[10px]">Langkah di Dashboard ImageKit:</p>
                <ol className="space-y-3 font-medium text-gray-700 dark:text-gray-300">
                  <li className="flex gap-3"><span className="size-6 shrink-0 bg-primary text-[#111811] rounded-full flex items-center justify-center text-xs font-bold">1</span> Klik ikon <b>Settings</b> (ikon gerigi) di kiri bawah.</li>
                  <li className="flex gap-3"><span className="size-6 shrink-0 bg-primary text-[#111811] rounded-full flex items-center justify-center text-xs font-bold">2</span> Pilih menu <b>"Upload"</b> (ikon awan panah ke atas) di kolom sidebar tengah.</li>
                  <li className="flex gap-3"><span className="size-6 shrink-0 bg-primary text-[#111811] rounded-full flex items-center justify-center text-xs font-bold">3</span> Pilih sub-menu <b>"Upload Settings"</b>.</li>
                  <li className="flex gap-3"><span className="size-6 shrink-0 bg-primary text-[#111811] rounded-full flex items-center justify-center text-xs font-bold">4</span> Scroll ke bawah ke bagian <b>Authentication</b>.</li>
                  <li className="flex gap-3"><span className="size-6 shrink-0 bg-primary text-[#111811] rounded-full flex items-center justify-center text-xs font-bold">5</span> Ubah <b>"Allow unsigned upload"</b> menjadi <b className="text-primary">ENABLED</b>.</li>
                </ol>
              </div>
              <div className="space-y-4 bg-gray-50 dark:bg-black/20 p-6 rounded-2xl border border-gray-100 dark:border-gray-800">
                <p className="font-black text-gray-400 uppercase tracking-widest text-[10px]">Tetap Tidak Ketemu?</p>
                <p className="text-gray-500 font-medium">Jangan buang waktu, gunakan <b>Link Gambar Manual</b>. Unggah foto ke <a href="https://postimages.org/" target="_blank" className="text-primary underline">PostImages.org</a>, salin <b>Direct Link</b>, dan tempel di kotak input saat tambah produk. Ini cara paling instan dan pasti berhasil.</p>
              </div>
            </div>
          </div>
        )}

        <div className="flex border-b border-gray-100 dark:border-gray-800 mb-8 overflow-x-auto no-scrollbar gap-2">
          {['products', 'testimonials', 'cs', 'site', 'security'].map(tab => (
            <button key={tab} className={`px-8 py-4 font-black text-xs uppercase tracking-[0.1em] transition-all relative ${activeTab === tab ? 'text-primary' : 'text-gray-400'}`} onClick={() => setActiveTab(tab as any)}>
              {tab === 'products' ? 'Produk' : tab === 'testimonials' ? 'Testimoni' : tab === 'cs' ? 'Kontak' : tab === 'site' ? 'Website' : 'Admin'}
              {activeTab === tab && <div className="absolute bottom-0 left-0 right-0 h-1 bg-primary rounded-full shadow-[0_-2px_10px_rgba(19,236,19,0.5)]"></div>}
            </button>
          ))}
        </div>

        {activeTab === 'products' ? (
          <div className="grid grid-cols-1 gap-4">
            <button onClick={() => { setEditingProduct({ gallery: [], variations: [], isFeatured: false }); setIsModalOpen(true); }} className="group p-10 border-2 border-dashed border-gray-200 dark:border-gray-800 rounded-[40px] flex flex-col items-center justify-center hover:border-primary hover:bg-primary/5 transition-all">
               <div className="size-16 rounded-full bg-gray-50 dark:bg-black/20 flex items-center justify-center text-gray-400 group-hover:bg-primary group-hover:text-white transition-all mb-4">
                 <span className="material-symbols-outlined text-3xl">add</span>
               </div>
               <p className="font-black uppercase text-xs tracking-widest">Tambah Produk Baru</p>
            </button>
            {products.map(p => (
              <div key={p.id} className="bg-white dark:bg-[#1a2e1a] p-6 rounded-[32px] flex items-center gap-6 border border-gray-100 dark:border-gray-800 shadow-sm hover:shadow-md transition-all">
                <img src={p.coverMedia?.url || p.image} className="size-20 shrink-0 rounded-2xl object-cover" />
                <div className="flex-1">
                  <h4 className="text-lg font-black">{p.name}</h4>
                  <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">{p.category}</p>
                  <p className="text-primary font-black mt-1">Rp {p.price.toLocaleString('id-ID')}</p>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => { setEditingProduct(p); setIsModalOpen(true); }} className="size-12 bg-gray-50 dark:bg-black/20 rounded-xl hover:text-primary flex items-center justify-center"><span className="material-symbols-outlined">edit</span></button>
                  <button onClick={() => { if(confirm('Hapus produk ini?')) dbService.deleteProduct(p.id).then(refreshData) }} className="size-12 bg-gray-50 dark:bg-black/20 rounded-xl hover:text-red-500 flex items-center justify-center"><span className="material-symbols-outlined">delete</span></button>
                </div>
              </div>
            ))}
          </div>
        ) : activeTab === 'site' ? (
          <div className="bg-white dark:bg-[#1a2e1a] p-10 rounded-[40px] border border-gray-100 dark:border-gray-800 max-w-4xl mx-auto">
             <form onSubmit={e => { e.preventDefault(); if(localSettings) dbService.saveSiteSettings(localSettings).then(() => { refreshData(); alert('Tersimpan!'); }); }} className="flex flex-col gap-10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="flex flex-col gap-2 md:col-span-2">
                    <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Link Banner Hero (Saran: 1920x1080)</label>
                    <input className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 outline-none focus:border-primary font-bold" value={localSettings?.heroImage} onChange={e => localSettings && setLocalSettings({...localSettings, heroImage: e.target.value})} placeholder="https://..." />
                  </div>
                  <div className="flex flex-col gap-2">
                    <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Nama Toko</label>
                    <input className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 outline-none focus:border-primary font-bold" value={localSettings?.siteName} onChange={e => localSettings && setLocalSettings({...localSettings, siteName: e.target.value})} />
                  </div>
                  <div className="flex flex-col gap-2">
                    <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Link Logo</label>
                    <input className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 outline-none focus:border-primary font-bold" value={localSettings?.logoUrl} onChange={e => localSettings && setLocalSettings({...localSettings, logoUrl: e.target.value})} />
                  </div>
                  <div className="flex flex-col gap-2 md:col-span-2">
                    <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Judul Banner (Headline)</label>
                    <textarea className="h-28 border-2 rounded-2xl p-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 outline-none focus:border-primary font-bold resize-none" value={localSettings?.heroTitle} onChange={e => localSettings && setLocalSettings({...localSettings, heroTitle: e.target.value})} />
                  </div>
                </div>
                <button className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-lg shadow-xl shadow-primary/20">Simpan Konfigurasi</button>
             </form>
          </div>
        ) : activeTab === 'cs' ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
             <button onClick={() => { setEditingCS({ isActive: true }); setIsModalOpen(true); }} className="p-8 border-2 border-dashed border-gray-200 dark:border-gray-800 rounded-[32px] text-gray-400 hover:border-primary hover:text-primary transition-all flex items-center justify-center gap-4">
               <span className="material-symbols-outlined">person_add</span>
               <p className="font-black text-xs uppercase tracking-widest">Tambah Kontak CS</p>
             </button>
             {csContacts.map(c => (
               <div key={c.id} className="bg-white dark:bg-[#1a2e1a] p-6 rounded-[32px] flex items-center justify-between border border-gray-100 dark:border-gray-800">
                 <div>
                   <h4 className="font-black text-lg">{c.name}</h4>
                   <p className="text-gray-400 font-bold">+{c.phoneNumber}</p>
                 </div>
                 <div className="flex gap-2">
                    <button onClick={() => { setEditingCS(c); setIsModalOpen(true); }} className="size-10 flex items-center justify-center hover:text-primary"><span className="material-symbols-outlined">edit</span></button>
                    <button onClick={() => { if(confirm('Hapus?')) dbService.deleteCSContact(c.id).then(refreshData) }} className="size-10 flex items-center justify-center hover:text-red-500"><span className="material-symbols-outlined">delete</span></button>
                 </div>
               </div>
             ))}
          </div>
        ) : activeTab === 'testimonials' ? (
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
            <button onClick={() => { setEditingTestimonial({ isActive: true }); setIsModalOpen(true); }} className="flex flex-col items-center justify-center aspect-[3/4] rounded-[32px] border-2 border-dashed border-gray-200 dark:border-gray-800 hover:border-primary text-gray-400 hover:text-primary transition-all">
              <span className="material-symbols-outlined text-4xl mb-2">add_a_photo</span>
              <p className="text-[10px] font-black uppercase">Tambah Bukti Review</p>
            </button>
            {testimonials.map(t => (
              <div key={t.id} className="relative aspect-[3/4] rounded-[32px] border border-gray-100 dark:border-gray-800 overflow-hidden group">
                <img src={t.imageUrl} className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-4">
                   <button onClick={() => { setEditingTestimonial(t); setIsModalOpen(true); }} className="size-12 bg-white text-black rounded-full flex items-center justify-center"><span className="material-symbols-outlined">edit</span></button>
                   <button onClick={() => { if(confirm('Hapus?')) dbService.deleteTestimonial(t.id).then(refreshData) }} className="size-12 bg-red-500 text-white rounded-full flex items-center justify-center"><span className="material-symbols-outlined">delete</span></button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="max-w-md mx-auto bg-white dark:bg-[#1a2e1a] p-10 rounded-[40px] border border-gray-100 dark:border-gray-800 shadow-sm text-center">
             <span className="material-symbols-outlined text-5xl text-primary mb-4">key</span>
             <h3 className="text-2xl font-black mb-6">Keamanan Admin</h3>
             <form onSubmit={e => { e.preventDefault(); dbService.saveAdminCredentials(adminCreds).then(() => alert('Diperbarui!')); }} className="flex flex-col gap-4 text-left">
                <div className="flex flex-col gap-1">
                  <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Admin Username</label>
                  <input required className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={adminCreds.username} onChange={e => setAdminCreds({...adminCreds, username: e.target.value})} />
                </div>
                <div className="flex flex-col gap-1">
                  <label className="text-[10px] font-black uppercase text-gray-400 ml-2">Admin Password</label>
                  <input required type="password" className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={adminCreds.password} onChange={e => setAdminCreds({...adminCreds, password: e.target.value})} />
                </div>
                <button className="h-16 bg-primary text-[#111811] rounded-2xl font-black mt-4 shadow-xl shadow-primary/20">Simpan Kredensial</button>
             </form>
          </div>
        )}
      </div>

      {/* MODAL FORM */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setIsModalOpen(false)}></div>
          <div className="relative w-full max-w-4xl bg-white dark:bg-background-dark rounded-[40px] p-8 md:p-12 shadow-2xl overflow-y-auto max-h-[90vh] no-scrollbar">
             <div className="flex justify-between items-center mb-10">
               <h2 className="text-4xl font-black tracking-tighter">
                 {activeTab === 'products' ? (editingProduct?.id ? 'Edit Produk' : 'Produk Baru') : 'Tambah Data'}
               </h2>
               <button onClick={() => setIsModalOpen(false)} className="size-12 flex items-center justify-center rounded-full bg-gray-50 dark:bg-black/20"><span className="material-symbols-outlined">close</span></button>
             </div>

             {activeTab === 'products' ? (
               <form onSubmit={handleSaveProduct} className="flex flex-col gap-10">
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="flex flex-col gap-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Nama Barang</label><input required className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={editingProduct?.name || ''} onChange={e => setEditingProduct({ ...editingProduct, name: e.target.value })} /></div>
                   <div className="flex flex-col gap-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Kategori</label><input required className="h-14 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={editingProduct?.category || ''} onChange={e => setEditingProduct({ ...editingProduct, category: e.target.value })} /></div>
                   <div className="flex flex-col gap-2 md:col-span-2"><label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Penjelasan Produk</label><textarea required className="h-32 border-2 rounded-2xl p-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 resize-none focus:border-primary outline-none font-bold" value={editingProduct?.description || ''} onChange={e => setEditingProduct({ ...editingProduct, description: e.target.value })} /></div>

                   {/* FOTO PRODUK */}
                   <div className="flex flex-col gap-4 border-2 border-gray-100 dark:border-gray-800 p-8 rounded-[32px] bg-gray-50/50 dark:bg-black/10 md:col-span-2">
                     <div className="flex flex-col md:flex-row gap-8 items-center">
                        <div className="relative size-48 shrink-0 rounded-[32px] bg-white dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden group">
                           {editingProduct?.coverMedia?.url || editingProduct?.image ? (
                             <img src={editingProduct.coverMedia?.url || editingProduct.image} className="absolute inset-0 w-full h-full object-contain" />
                           ) : <span className="material-symbols-outlined text-4xl text-gray-200">add_photo_alternate</span>}
                           <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" onChange={async (e) => {
                             const file = e.target.files?.[0];
                             if(file) {
                               try {
                                 const url = await uploadToImageKit(file);
                                 applyMediaUrl(url, true);
                               } catch(e) {}
                             }
                           }} disabled={isUploading} />
                           {isUploading && <div className="absolute inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center text-white font-black text-xs uppercase">Mengunggah...</div>}
                        </div>
                        <div className="flex-1 w-full space-y-4">
                           <h4 className="font-black text-sm uppercase tracking-widest text-primary">Solusi: Paste Link Gambar</h4>
                           <p className="text-xs text-gray-400 leading-relaxed font-medium">Jika tombol upload gagal, silakan gunakan link manual di sini (Contoh: dari PostImages atau Google Drive).</p>
                           <div className="flex gap-2">
                             <input className="flex-1 h-12 border-2 rounded-xl px-4 font-bold text-sm bg-white dark:bg-black/40 border-gray-100 dark:border-gray-800 focus:border-primary transition-all outline-none" placeholder="https://..." value={manualUrl} onChange={e => setManualUrl(e.target.value)} />
                             <button type="button" onClick={() => { if(manualUrl) applyMediaUrl(manualUrl, true); }} className="px-6 bg-[#111811] text-white dark:bg-white dark:text-black rounded-xl font-black text-[10px] uppercase whitespace-nowrap">Pasang Link</button>
                           </div>
                        </div>
                     </div>
                   </div>

                   {/* VARIASI HARGA */}
                   <div className="flex flex-col gap-4 md:col-span-2">
                     <div className="flex items-center justify-between">
                       <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Opsi Harga & Stok</label>
                       <button type="button" onClick={() => setEditingProduct(p => ({...p, variations: [...(p?.variations || []), { id: Date.now().toString(), name: '', price: 0, stock: 10 }]}))} className="text-primary font-black text-xs uppercase flex items-center gap-1 hover:underline"><span className="material-symbols-outlined text-sm">add_circle</span> Tambah Harga</button>
                     </div>
                     <div className="space-y-3">
                       {editingProduct?.variations?.map((v) => (
                         <div key={v.id} className="grid grid-cols-1 md:grid-cols-4 gap-3 bg-gray-50 dark:bg-black/20 p-4 rounded-2xl items-center border border-gray-100 dark:border-gray-800">
                           <input placeholder="Label (ex: Standar)" className="bg-white dark:bg-black/20 border-none rounded-xl h-12 px-4 font-bold text-sm" value={v.name} onChange={e => setEditingProduct(p => ({...p, variations: p?.variations?.map(it => it.id === v.id ? {...it, name: e.target.value} : it)}))} />
                           <input type="number" placeholder="Harga" className="bg-white dark:bg-black/20 border-none rounded-xl h-12 px-4 font-bold text-sm" value={v.price} onChange={e => setEditingProduct(p => ({...p, variations: p?.variations?.map(it => it.id === v.id ? {...it, price: Number(e.target.value)} : it)}))} />
                           <input type="number" placeholder="Stok" className="bg-white dark:bg-black/20 border-none rounded-xl h-12 px-4 font-bold text-sm" value={v.stock} onChange={e => setEditingProduct(p => ({...p, variations: p?.variations?.map(it => it.id === v.id ? {...it, stock: Number(e.target.value)} : it)}))} />
                           <button type="button" onClick={() => setEditingProduct(p => ({...p, variations: p?.variations?.filter(it => it.id !== v.id)}))} className="text-red-500 hover:text-red-700 font-bold text-[10px] uppercase">Hapus</button>
                         </div>
                       ))}
                       {(!editingProduct?.variations || editingProduct.variations.length === 0) && (
                          <div className="p-4 border-2 border-dashed border-gray-100 rounded-2xl text-center text-[10px] font-black uppercase text-gray-400">Minimal wajib ada 1 pengaturan harga.</div>
                       )}
                     </div>
                   </div>

                   <label className="flex items-center gap-3 cursor-pointer mt-2">
                     <input type="checkbox" checked={editingProduct?.isFeatured} onChange={e => setEditingProduct({...editingProduct, isFeatured: e.target.checked})} className="size-6 rounded-lg text-primary focus:ring-primary border-gray-200 dark:border-gray-800" />
                     <span className="font-black text-xs uppercase tracking-widest">Tampilkan di Beranda</span>
                   </label>
                 </div>
                 <button type="submit" disabled={isUploading} className="h-16 bg-primary text-[#111811] rounded-[24px] font-black text-xl shadow-2xl shadow-primary/40 hover:scale-[1.02] transition-all disabled:opacity-50 mt-4">Simpan Data Produk</button>
               </form>
             ) : activeTab === 'cs' ? (
               <form onSubmit={e => {
                 e.preventDefault();
                 if(editingCS) dbService.saveCSContact(editingCS as CSContact).then(() => { refreshData(); setIsModalOpen(false); });
               }} className="flex flex-col gap-6">
                  <input required placeholder="Nama Admin CS" className="h-16 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold text-lg" value={editingCS?.name || ''} onChange={e => setEditingCS({ ...editingCS, name: e.target.value })} />
                  <input required placeholder="No WA (ex: 628...)" className="h-16 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold text-lg" value={editingCS?.phoneNumber || ''} onChange={e => setEditingCS({ ...editingCS, phoneNumber: e.target.value })} />
                  <button className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-xl shadow-primary/20">Simpan Kontak</button>
               </form>
             ) : (
               <form onSubmit={e => {
                 e.preventDefault();
                 if(editingTestimonial) dbService.saveTestimonial(editingTestimonial as Testimonial).then(() => { refreshData(); setIsModalOpen(false); });
               }} className="flex flex-col gap-8">
                 <div className="flex flex-col md:flex-row gap-8 items-center border-2 border-gray-100 dark:border-gray-800 p-8 rounded-[32px]">
                    <div className="relative aspect-[3/4] w-40 shrink-0 rounded-[24px] bg-gray-50 dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden">
                        {editingTestimonial?.imageUrl ? <img src={editingTestimonial.imageUrl} className="w-full h-full object-cover" /> : <span className="material-symbols-outlined text-4xl">add_photo</span>}
                        <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" onChange={async (e) => {
                          const file = e.target.files?.[0];
                          if(file) {
                            try {
                              const url = await uploadToImageKit(file);
                              setEditingTestimonial({...editingTestimonial, imageUrl: url});
                            } catch(e) {}
                          }
                        }} />
                    </div>
                    <div className="flex-1 w-full space-y-4">
                        <label className="text-[10px] font-black uppercase text-gray-400">Gunakan Link Manual Gambar Review</label>
                        <div className="flex gap-2">
                           <input className="flex-1 h-12 border-2 rounded-xl px-4 font-bold text-sm" placeholder="https://..." value={manualUrl} onChange={e => setManualUrl(e.target.value)} />
                           <button type="button" onClick={() => { if(manualUrl) setEditingTestimonial({...editingTestimonial, imageUrl: manualUrl}); setManualUrl(''); }} className="px-6 bg-black text-white rounded-xl font-black text-[10px] uppercase">Gunakan</button>
                        </div>
                    </div>
                 </div>
                 <input placeholder="Nama Pelanggan (ex: Ibu Siska - Bandung)" className="h-16 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={editingTestimonial?.customerName || ''} onChange={e => setEditingTestimonial({ ...editingTestimonial, customerName: e.target.value })} />
                 <button className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-xl shadow-primary/20">Simpan Testimoni</button>
               </form>
             )}
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { dbService } from '../../services/dbService';
import { Product, CSContact, Media, Variation, SiteSettings, Testimonial, AdminCredentials } from '../../types';
import { useStore } from '../../App';

const getEnv = (key: string): string => {
  // @ts-ignore
  if (import.meta.env && import.meta.env[key]) return import.meta.env[key];
  // @ts-ignore
  if (typeof process !== 'undefined' && process.env && process.env[key]) return process.env[key];
  return '';
};

const IK_PUBLIC_KEY = getEnv('VITE_IMAGEKIT_PUBLIC_KEY');

const AdminDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'products' | 'cs' | 'site' | 'testimonials' | 'security'>('products');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | null>(null);
  const [editingCS, setEditingCS] = useState<Partial<CSContact> | null>(null);
  const [editingTestimonial, setEditingTestimonial] = useState<Partial<Testimonial> | null>(null);
  const [localSettings, setLocalSettings] = useState<SiteSettings | null>(null);
  const [adminCreds, setAdminCreds] = useState<AdminCredentials>({ username: '', password: '' });
  const [isUploading, setIsUploading] = useState(false);
  const [showGuide, setShowGuide] = useState(false);

  const [manualUrl, setManualUrl] = useState('');

  const navigate = useNavigate();
  const { refreshData, products, csContacts, siteSettings, testimonials } = useStore();

  useEffect(() => {
    const isAuth = localStorage.getItem('lumina_admin_auth');
    if (!isAuth) navigate('/admin/login');
    setLocalSettings(siteSettings);
    dbService.getAdminCredentials().then(setAdminCreds);
  }, [navigate, siteSettings]);

  const handleLogout = () => {
    localStorage.removeItem('lumina_admin_auth');
    navigate('/admin/login');
  };

  const uploadToImageKit = async (file: File): Promise<string> => {
    if (!IK_PUBLIC_KEY) {
      alert("Public Key ImageKit belum dikonfigurasi di environment variable.");
      throw new Error('Missing Public Key');
    }

    setIsUploading(true);
    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('fileName', file.name || `img_${Date.now()}`);
      formData.append('publicKey', IK_PUBLIC_KEY);
      formData.append('useUniqueFileName', 'true');

      const response = await fetch('https://upload.imagekit.io/api/v1/files/upload', {
        method: 'POST',
        body: formData,
      });

      const result = await response.json();
      if (!response.ok) throw new Error(result.message || 'Gagal');
      return result.url;
    } catch (error: any) {
      alert(`Gagal: ${error.message}\n\nSolusi: Gunakan input "URL Gambar Manual" di bawah tombol upload.`);
      throw error;
    } finally {
      setIsUploading(false);
    }
  };

  const handleSaveProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingProduct) return;
    const product: Product = {
      id: editingProduct.id || Date.now().toString(),
      name: editingProduct.name || '',
      description: editingProduct.description || '',
      price: editingProduct.variations?.[0]?.price || Number(editingProduct.price) || 0,
      category: editingProduct.category || 'Umum',
      image: editingProduct.coverMedia?.url || editingProduct.image || '',
      coverMedia: editingProduct.coverMedia || { type: 'image', url: '' },
      gallery: editingProduct.gallery || [],
      variations: editingProduct.variations || [],
      isFeatured: !!editingProduct.isFeatured,
      createdAt: editingProduct.createdAt || Date.now()
    };
    await dbService.saveProduct(product);
    refreshData();
    setIsModalOpen(false);
    setEditingProduct(null);
  };

  return (
    <div className="px-4 md:px-10 lg:px-40 py-10 min-h-screen">
      <div className="max-w-[1200px] mx-auto">
        <div className="flex flex-col md:flex-row items-center justify-between mb-10 gap-6">
          <div className="flex items-center gap-4">
            <div className="size-12 bg-primary text-black rounded-2xl flex items-center justify-center">
              <span className="material-symbols-outlined text-3xl font-black">dashboard</span>
            </div>
            <div>
              <h1 className="text-4xl font-black tracking-tighter">Admin Dashboard</h1>
              <p className="text-gray-400 font-bold uppercase text-[10px] tracking-[0.2em] mt-1">Management Console</p>
            </div>
          </div>
          <div className="flex gap-3">
            <button onClick={() => setShowGuide(!showGuide)} className="h-12 px-6 bg-primary/10 text-primary border border-primary/20 rounded-2xl font-black text-xs flex items-center gap-2 hover:bg-primary/20 transition-all">
              <span className="material-symbols-outlined text-lg">help_center</span> PANDUAN GAMBAR
            </button>
            <button onClick={handleLogout} className="h-12 px-6 border-2 border-gray-100 dark:border-gray-800 rounded-2xl font-black text-xs hover:bg-red-500 hover:text-white transition-all">LOGOUT</button>
          </div>
        </div>

        {showGuide && (
          <div className="mb-10 bg-white dark:bg-[#1a2e1a] border-2 border-primary/20 rounded-[32px] p-8 shadow-2xl animate-in fade-in slide-in-from-top-4 duration-500">
