              <div className="size-16 shrink-0 bg-primary/10 rounded-3xl flex items-center justify-center text-primary">
                <span className="material-symbols-outlined text-4xl">image_search</span>
              </div>
              <div className="flex-1">
                <h3 className="text-xl font-black mb-2">Masalah dengan ImageKit?</h3>
