                   </label>
                 </div>
                 <button type="submit" disabled={isUploading} className="h-16 bg-primary text-[#111811] rounded-[24px] font-black text-xl shadow-2xl shadow-primary/40 hover:scale-[1.02] transition-all disabled:opacity-50 mt-4">SIMPAN DATA PRODUK</button>
               </form>
             ) : activeTab === 'cs' ? (
               <form onSubmit={e => {
                 e.preventDefault();
                 if(editingCS) dbService.saveCSContact(editingCS as CSContact).then(() => { refreshData(); setIsModalOpen(false); });
               }} className="flex flex-col gap-6">
                  <div className="flex flex-col gap-2">
                    <label className="text-[10px] font-black uppercase text-gray-400 ml-2 tracking-widest">Nama Panggilan CS</label>
                    <input required placeholder="Contoh: Kak Susi" className="h-16 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold text-lg" value={editingCS?.name || ''} onChange={e => setEditingCS({ ...editingCS, name: e.target.value })} />
