                  </div>
                  <button className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-xl shadow-primary/20">SIMPAN KONTAK</button>
               </form>
             ) : (
               <form onSubmit={e => {
                 e.preventDefault();
                 if(editingTestimonial) dbService.saveTestimonial(editingTestimonial as Testimonial).then(() => { refreshData(); setIsModalOpen(false); });
               }} className="flex flex-col gap-8">
                 <div className="flex flex-col md:flex-row gap-8 items-center border-2 border-gray-100 dark:border-gray-800 p-8 rounded-[32px] bg-gray-50/50 dark:bg-black/10">
                    <div className="relative aspect-[3/4] w-40 shrink-0 rounded-[24px] bg-white dark:bg-black/20 border-2 border-dashed border-gray-200 dark:border-gray-800 flex items-center justify-center overflow-hidden shadow-inner">
                        {editingTestimonial?.imageUrl ? <img src={editingTestimonial.imageUrl} className="w-full h-full object-cover" /> : <span className="material-symbols-outlined text-4xl text-gray-200">photo_camera</span>}
                        <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" accept="image/*" onChange={async (e) => {
                          const file = e.target.files?.[0];
                          if(file) {
                            try {
                              const url = await uploadToImageKit(file);
                              setEditingTestimonial({...editingTestimonial, imageUrl: url});
                            } catch(e) {}
                          }
                        }} />
                    </div>
                    <div className="flex-1 w-full space-y-4">
                        <label className="text-[10px] font-black uppercase text-gray-400 tracking-widest">URL Gambar Review Manual</label>
                        <div className="flex gap-2">
                           <input className="flex-1 h-14 border-2 rounded-xl px-4 font-bold text-sm bg-white dark:bg-black/40 border-gray-100 dark:border-gray-800 focus:border-primary outline-none" placeholder="https://..." value={editingTestimonial?.imageUrl || ''} onChange={e => setEditingTestimonial({ ...editingTestimonial, imageUrl: e.target.value })} />
                           <div className="px-4 bg-gray-100 dark:bg-black/40 rounded-xl flex items-center justify-center text-primary"><span className="material-symbols-outlined">link</span></div>
                        </div>
                    </div>
                 </div>
                 <div className="flex flex-col gap-2">
                    <label className="text-[10px] font-black uppercase text-gray-400 ml-2 tracking-widest">Identitas Pelanggan</label>
                    <input placeholder="Contoh: Bpk. Agus - Jakarta" className="h-16 border-2 rounded-2xl px-6 bg-gray-50 dark:bg-black/20 border-gray-100 dark:border-gray-800 focus:border-primary outline-none font-bold" value={editingTestimonial?.customerName || ''} onChange={e => setEditingTestimonial({ ...editingTestimonial, customerName: e.target.value })} />
                 </div>
                 <button className="h-16 bg-primary text-[#111811] rounded-2xl font-black text-xl shadow-xl shadow-primary/20">SIMPAN REVIEW</button>
               </form>
             )}
          </div>
        </div>
      )}
    </div>
  );
};

