 * Jalankan perintah SQL berikut di SQL Editor Neon Anda:
 * 
 * CREATE TABLE products (id TEXT PRIMARY KEY, name TEXT, description TEXT, price NUMERIC, category TEXT, image TEXT, cover_media JSONB, gallery JSONB, variations JSONB, is_featured BOOLEAN, created_at BIGINT);
 * CREATE TABLE cs_contacts (id TEXT PRIMARY KEY, name TEXT, phone_number TEXT, is_active BOOLEAN);
 * CREATE TABLE testimonials (id TEXT PRIMARY KEY, image_url TEXT, customer_name TEXT, is_active BOOLEAN);
