async function runQuery(sql: string) {
  if (!NEON_HOST || !NEON_API_KEY) {
    console.warn("Neon Config Missing.");
    return null;
  }

  try {
    const url = `https://${NEON_HOST}/sql`;

    // Kadang browser memblokir Content-Type: application/json di preflight jika server tidak mengizinkannya.
    // Kita pastikan header seminimal mungkin untuk menembus CORS.
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${NEON_API_KEY}`,
        'Content-Type': 'application/json' // Neon SQL API mewajibkan ini
      },
      body: JSON.stringify({ query: sql }),
    });

    if (!response.ok) {
      const errText = await response.text();
      // Jika error 401/403, hampir pasti karena API KEY (Password) salah
      if (response.status === 401 || response.status === 403) {
        throw new Error("Password Database Salah atau Tidak Diizinkan. Pastikan VITE_NEON_API_KEY berisi Database Password, bukan napi_...");
      }
      throw new Error(`Neon Error ${response.status}: ${errText}`);
    }

    const result = await response.json();
    if (result.error) throw new Error(result.error);
    return result.rows || [];
  } catch (e: any) {
    console.error('Neon Failure:', e.message);
    return null; 
  }
}

