// Manual Base64 Implementation as per guidelines
function decode(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

function encode(bytes: Uint8Array) {
  let binary = '';
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

const VoiceAssistant: React.FC = () => {
  const { siteSettings, products } = useStore();
  const [isActive, setIsActive] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const outAudioContextRef = useRef<AudioContext | null>(null);
  const sessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const stopAssistant = () => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
    if (outAudioContextRef.current) {
      outAudioContextRef.current.close();
      outAudioContextRef.current = null;
    }
    setIsActive(false);
    setIsConnecting(false);
  };

  const startAssistant = async () => {
    setIsConnecting(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const inCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = inCtx;
      outAudioContextRef.current = outCtx;

      // Create product context for the AI
      const productList = products.map(p => `- ${p.name}: Rp ${p.price.toLocaleString('id-ID')} (Kategori: ${p.category})`).join('\n');

      const systemInstruction = `Anda adalah LuminaVoice, asisten belanja pintar untuk toko "${siteSettings.siteName}".
      Data produk kami saat ini:
      ${productList}

      Tugas Anda:
      1. Membantu pelanggan memilih produk.
      2. Menjelaskan harga dan keunggulan produk.
      3. Jika pelanggan ingin membeli, arahkan untuk menambah ke keranjang dan klik checkout WhatsApp.
      4. Gunakan Bahasa Indonesia yang sangat ramah, santai, dan membantu (seperti asisten pribadi).
      5. Jawablah dengan singkat dan padat agar percakapan terasa real-time.`;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsActive(true);
            setIsConnecting(false);

            const source = inCtx.createMediaStreamSource(stream);
            const scriptProcessor = inCtx.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const pcmBlob: Blob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };

              sessionPromise.then(session => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(inCtx.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio && outCtx) {
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outCtx.currentTime);
              const audioBuffer = await decodeAudioData(decode(base64Audio), outCtx, 24000, 1);
              const source = outCtx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(outCtx.destination);
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
              source.onended = () => sourcesRef.current.delete(source);
            }

            if (message.serverContent?.interrupted) {
              sourcesRef.current.forEach(s => s.stop());
              sourcesRef.current.clear();
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => {
            console.error('AI Error:', e);
            stopAssistant();
          },
          onclose: () => {
            stopAssistant();
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } }
          },
          systemInstruction
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error('Failed to start AI Assistant:', err);
      setIsConnecting(false);
      alert('Gagal mengaktifkan mikrofon atau koneksi AI.');
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[200] flex flex-col items-end gap-4">
      {isActive && (
        <div className="bg-white dark:bg-[#1a2e1a] p-5 rounded-[32px] shadow-2xl border border-primary/30 animate-in slide-in-from-bottom-4 flex flex-col items-center gap-3">
          <div className="flex gap-1 items-center h-6 px-4">
            {[...Array(6)].map((_, i) => (
              <div 
                key={i} 
                className="w-1.5 bg-primary rounded-full animate-bounce" 
                style={{ 
                  height: `${Math.random() * 100 + 20}%`, 
                  animationDuration: `${Math.random() * 0.5 + 0.5}s`,
                  animationDelay: `${i * 0.1}s` 
                }}
              ></div>
            ))}
          </div>
          <span className="text-[10px] font-black uppercase tracking-widest text-primary animate-pulse">LuminaVoice Berjalan</span>
        </div>
      )}

      <button
        onClick={isActive ? stopAssistant : startAssistant}
        disabled={isConnecting}
        className={`size-20 rounded-full flex items-center justify-center shadow-2xl transition-all active:scale-90 relative group ${
          isActive 
            ? 'bg-red-500 text-white shadow-red-500/30' 
            : 'bg-primary text-[#111811] hover:scale-110 shadow-primary/30'
        } ${isConnecting ? 'opacity-50 cursor-not-allowed' : ''}`}
      >
        {/* Glow effect */}
        {!isActive && !isConnecting && (
           <div className="absolute inset-0 rounded-full bg-primary/40 animate-ping"></div>
        )}

        {isConnecting ? (
          <span className="material-symbols-outlined animate-spin text-4xl">progress_activity</span>
        ) : (
          <span className="material-symbols-outlined text-4xl font-black relative z-10">
            {isActive ? 'close' : 'graphic_eq'}
          </span>
        )}
      </button>
    </div>
  );
};

