const getEnv = (key: string): string => {
  try {
    // @ts-ignore
    if (typeof import.meta !== 'undefined' && import.meta.env) return import.meta.env[key] || '';
    if (typeof process !== 'undefined' && process.env) return process.env[key] || '';
  } catch (e) {}
  return '';
};

