import crypto from 'crypto';

/**
 * Backend service for ImageKit Server-side Authentication.
 * This generates the required signature for secure client-side uploads.
 * Standard implementation for Vercel Serverless Functions.
 */
export default function handler(req: any, res: any) {
  const privateKey = process.env.VITE_IMAGEKIT_PRIVATE_KEY || process.env.IMAGEKIT_PRIVATE_KEY;

  if (!privateKey) {
    return res.status(500).json({ 
      error: "ImageKit Private Key is not configured on the server." 
    });
  }

  // Generate unique token and expiration timestamp (valid for 30 minutes)
  const token = req.query.token || crypto.randomBytes(16).toString('hex');
  const expire = req.query.expire || Math.floor(Date.now() / 1000) + 1800;

  // HMAC-SHA1 signing for security
  const signature = crypto
    .createHmac('sha1', privateKey)
    .update(token + expire)
    .digest('hex');

  res.status(200).json({
    token,
    expire,
    signature,
  });
}

export interface ImageKitResponse {
  url: string;
  fileId: string;
  name: string;
  size: number;
  filePath: string;
}

const getEnv = (key: string): string => {
  try {
    // @ts-ignore
    if (typeof import.meta !== 'undefined' && import.meta.env) return import.meta.env[key] || '';
    // @ts-ignore
    if (typeof process !== 'undefined' && process.env) return process.env[key] || '';
  } catch (e) {}
  return '';
};

export const imageService = {
  /**
   * Fetches authentication parameters from the backend serverless function.
   */
  async getAuthParams() {
    try {
      const response = await fetch('/api/auth');
      if (!response.ok) {
        const errData = await response.json();
        throw new Error(errData.error || 'Failed to fetch auth params');
      }
      return await response.json();
    } catch (error: any) {
      console.error('Auth Param Error:', error);
      throw new Error('Gagal mendapatkan izin upload dari server.');
    }
  },

  /**
   * Performs direct client-side upload to ImageKit via XHR.
   */
  upload(file: File, onProgress?: (percent: number) => void): Promise<ImageKitResponse> {
    return new Promise(async (resolve, reject) => {
      try {
        const auth = await this.getAuthParams();
        const publicKey = getEnv('VITE_IMAGEKIT_PUBLIC_KEY');

        if (!publicKey) {
          return reject(new Error('VITE_IMAGEKIT_PUBLIC_KEY belum dikonfigurasi di environment.'));
        }

        const formData = new FormData();
        formData.append('file', file);
        formData.append('fileName', file.name || `media_${Date.now()}`);
        formData.append('publicKey', publicKey);
        formData.append('signature', auth.signature);
        formData.append('expire', auth.expire.toString());
        formData.append('token', auth.token);
        formData.append('useUniqueFileName', 'true');

        const xhr = new XMLHttpRequest();
        xhr.open('POST', 'https://upload.imagekit.io/api/v1/files/upload', true);

        if (onProgress) {
          xhr.upload.onprogress = (event) => {
            if (event.lengthComputable) {
              const percent = Math.round((event.loaded / event.total) * 100);
              onProgress(percent);
            }
          };
        }

        xhr.onload = () => {
          if (xhr.status >= 200 && xhr.status < 300) {
            try {
              const response = JSON.parse(xhr.responseText);
              resolve(response);
            } catch (e) {
              reject(new Error('Respon server tidak valid.'));
            }
          } else {
            reject(new Error(xhr.responseText || `Upload gagal (Status: ${xhr.status})`));
          }
        };

        xhr.onerror = () => reject(new Error('Kesalahan jaringan saat mengunggah media.'));
        xhr.send(formData);
      } catch (err) {
        reject(err);
      }
    });
  }
};

