};

// --- THEME FONTS MAPPING ---
export const FONT_THEMES: Record<string, { heading: string, body: string }> = {
  'Default': { heading: "'Inter'", body: "'Inter'" },
  'Display 1': { heading: "'Playfair Display'", body: "'Inter'" },
